    ('05353312-1885-16ce-b4c8-007655a3a5df', N'BRONZE', N'artifact-贈銅000388N000000000', N'銅鎏金寶冠－縮小複製品', N'金屬與火塑成器物，歲月再替表面留下時間的痕跡。這件「銅鎏金寶冠」縮小複製品，把銅器沉穩厚實的存在感帶進收藏空間。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：銅器' + NCHAR(10) + N'年代：清朝' + NCHAR(10) + N'商品尺寸：通高 6.83 公分、直徑 9.25 公分' + NCHAR(10) + N'原作尺寸：通高 13.65 公分、直徑 18.5 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'銅鎏金寶冠 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'本器為韓國作品。金色寶冠，冠帶部份結構與贈銅384「鳳凰式付冠」相似，但寶冠主體結構多了四道拱形結構，其上飾有龍、鳳等飾件，整體裝飾更為華美複雜，體積更大。冠帶上緣呈波浪狀，表面飾如意鉤連紋，冠帶底邊有一道連珠紋，冠帶面上雕飾蝙蝠等裝飾。冠帶等距懸飾有五組鳳凰形裝飾，每組以一似梳之柵欄形飾物懸掛冠帶上，其上再飾以一隻鳳凰；每隻鳳均身材細長，腹部緊貼柵欄形飾件，尾羽分成多股高聳伸展，微曲頸向前伸出冠帶外，頭朝下方作俯視狀，細長的口喙微張。寶冠正面三隻鳳凰之尾羽構成火燄形。四道拱形結構上皆懸飾龍、鳳、蟬、雲朵等飾件，由低至高第一道圓拱中央飾以一條龍，龍身細長彎曲，頭部造型與鳳相似，四周飾有雲朵等裝飾；第二道拱形上懸飾雙龍，由正面觀之在第一隻龍的兩側；第四道拱與前三道不同，添飾了幾個火燄雲狀的紋章，中央有文字符號。', 820.00, 20, N'/media/catalog/bronze/贈銅000388N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/24786?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1310000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'通高 6.83 公分、直徑 9.25 公分', '6f920dc5-ff6b-03d6-ece2-de7cdaa9cebe'),
    ('4966a4c8-e11e-f775-0664-01d0267dbd4f', N'CARVING', N'artifact-贈雕000121N000000000', N'骨雕蛙－縮小複製品', N'不同材料有不同個性，好的雕刻懂得順勢而為。以骨雕蛙為靈感製作的縮小複製品，保留一份因材施藝的工藝趣味。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：雕刻' + NCHAR(10) + N'年代：戰國' + NCHAR(10) + N'商品尺寸：長 1.2 公分、寬 0.85 公分、高 0.6 公分' + NCHAR(10) + N'原作尺寸：長 2.4 公分、寬 1.7 公分、高 1.2 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'骨雕蛙 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'以一小塊骨材，立雕出一隻蛙，圈點紋做雙眼，尖唇前伸，前、後足皆曲起，彷彿蓄勢待躍。蛙背已因墓葬其他墓葬物（銅器）而被染成綠色，確是「青」蛙。', 1440.00, 20, N'/media/catalog/carving/贈雕000121N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/45350?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1320000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'長 1.2 公分、寬 0.85 公分、高 0.6 公分', '2ae430e8-42a6-ff30-8ade-eca7bf4a6046'),
    ('c68a1c89-34cc-f73e-fe78-023604b46bb9', N'LACQUER', N'artifact-故漆000557N000000000', N'剔紅茶花圓盒－縮小複製品', N'漆藝講究耐心，也讓器物擁有難以取代的深沉質感。這件「剔紅茶花圓盒」縮小複製品，是一件越看越能發現味道的收藏。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：漆器' + NCHAR(10) + N'年代：明 永樂' + NCHAR(10) + N'商品尺寸：高 3.25 公分、深 1.95 公分、徑 9.35 公分' + NCHAR(10) + N'原作尺寸：高 6.5 公分、深 3.9 公分、徑 18.7 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'剔紅茶花圓盒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'蔗段式盒，子母口，圈足，底部及盒內髹褐漆。盒面為折枝茶花。自盒右下側起一主幹，開一大花後，再向左右分枝延伸，各開一花，中心為一組三片複葉，葉片順著枝葉生長的方向，向上排列，穿插著半開、欲開的花朵與花蕾，花葉佈展秩序井然。花形圓滿，葉片居間烘托，物象清晰分明，生氣盎然。漆色紅潤，刀法俐落，物象間黃漆顯露，花瓣、葉片起伏細膩，打磨圓潤，葉脈、瓣紋刻畫流暢。有條不紊的章法與精細嚴謹的工藝，充分表現永樂一朝高超的官方水平。側面為轉枝花卉，茶花、牡丹、菊花、梔子花，波浪狀的枝葉，花朵俯仰相間，兩兩成組，環繞不間。', 830.00, 20, N'/media/catalog/lacquer/故漆000557N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/17576?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 3.25 公分、深 1.95 公分、徑 9.35 公分', 'e4d36bd7-e3eb-2d59-6185-cb311e1632a7'),
    ('9dcf8501-4db3-fd56-fb53-026cc4d738de', N'ENAMEL', N'artifact-故琺000995N000000000', N'銅胎畫琺瑯花草五毒盒－縮小複製品', N'琺瑯以釉料與燒製換來鮮明而細緻的層次。這件「銅胎畫琺瑯花草五毒盒」縮小複製品，把這份講究工序的華美濃縮成展示亮點。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：琺瑯器' + NCHAR(10) + N'年代：清 乾隆' + NCHAR(10) + N'商品尺寸：長 3.3 公分、寬 4.35 公分、高 1.7 公分；盒蓋高 0.6 公分' + NCHAR(10) + N'原作尺寸：長 6.6 公分、寬 8.7 公分、高 3.4 公分；盒蓋高 1.2 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'銅胎畫琺瑯花草五毒盒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'花形小盒，子母口，全器呈花形，蓋頂、器底和口沿處皆鑲金邊。全器畫琺瑯為飾，粉藍色底，蓋面繪五個由粉、黃、藍、綠構成的幾何稜格紋，及蠍、蛇、蜈蚣、蟾蜍、蜘蛛五毒，間飾各式花草。蓋沿及盒身繪有黃褐色幾何稜紋，飾桃實、荷花等花草果實。器內壁施藍綠釉。白底朱色雙方框書「乾隆年製」四字楷款。', 840.00, 20, N'/media/catalog/enamel/故琺000995N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/61937?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1340000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'長 3.3 公分、寬 4.35 公分、高 1.7 公分；盒蓋高 0.6 公分', '60c460b2-54af-4a21-ed29-4c2091d0a809'),
    ('07b32248-7bd3-5583-b1ed-0279b5603eeb', N'LACQUER', N'artifact-故漆000555N000000000', N'剔紅雙龍戲珠盤－縮小複製品', N'光影落在漆面上，每個角度都有不同感受。這件「剔紅雙龍戲珠盤」縮小複製品延續漆器含蓄而精緻的魅力，為展示空間添上一份古雅。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：漆器' + NCHAR(10) + N'年代：明 萬曆二十三年' + NCHAR(10) + N'商品尺寸：高 1.3 公分、口徑 10.5 公分、足徑 8.5 公分' + NCHAR(10) + N'原作尺寸：高 2.6 公分、口徑 21.0 公分、足徑 17.0 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'剔紅雙龍戲珠盤 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'圓盤，圓沿，圈足，足內髹黑漆。底款「萬曆乙未年製」為萬曆廿三年，西元1595年。正面盤沿為連枝花卉。盤內一大圓，下段刻波浪紋錦地，一片起伏的海水，前方矗立三座山峰，山石旁海水洶湧，激起浪花。盤心上段，米字形方格錦地，左右兩龍對峙，一龍從天而降，龍首翻轉向上，一龍騰躍而起，兩龍隔一火球對視。龍身瘦長飛舞，正居盤心，張口吐舌，四足外揚，龍鰭飛揚，形貌強悍威嚴。行龍外，間飾如意雲紋。漆層薄，質硬，色暗，紋飾佈局均衡，構圖穩定，刀法熟練俐落，陰刻線條拙重，莊嚴穩重而華麗，是官方雕漆的典型。', 830.00, 20, N'/media/catalog/lacquer/故漆000555N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/17574?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 1.3 公分、口徑 10.5 公分、足徑 8.5 公分', 'ce234bc1-3d35-1287-c8da-9f1a31fa09ea'),
    ('076e43c2-c2bd-8961-f4f5-0288def981e3', N'CERAMIC', N'artifact-故瓷018095N000000000', N'青花梵文杯－縮小複製品', N'泥土經過塑形與窯火，才成為能被長久欣賞的器物。這件「青花梵文杯」縮小複製品，把陶瓷溫雅耐看的氣質帶到眼前。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：陶瓷' + NCHAR(10) + N'年代：明 萬曆' + NCHAR(10) + N'商品尺寸：口徑 2.3 公分、底徑 1.35 公分、高 1.2 公分' + NCHAR(10) + N'原作尺寸：口徑 4.6 公分、底徑 2.7 公分、高 2.4 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'青花梵文杯 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'本器為小杯，斂口，壁呈弧形，淺圈足，外壁繪青花花鳥，內壁以青花書梵文，底有「大明萬曆年製」青花楷書六字款。從器底「大明萬曆年製」款識的寫法來看，可能屬清代仿製。', 790.00, 20, N'/media/catalog/ceramic/故瓷018095N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/71736?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1330000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'口徑 2.3 公分、底徑 1.35 公分、高 1.2 公分', '7574d1eb-1b1a-c2eb-84eb-6d855c014d30'),
    ('a99e69b1-38e4-3d24-9c49-038c07534916', N'CERAMIC', N'artifact-故瓷018182N000000000', N'汝窯 青瓷盤－縮小複製品', N'從日常器用到典藏珍品，陶瓷記錄了不同時代對生活之美的想像。這件「汝窯 青瓷盤」縮小複製品，讓這段美感自然融入展示空間。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：陶瓷' + NCHAR(10) + N'年代：北宋' + NCHAR(10) + N'商品尺寸：高 3.2-1.85 公分、口徑 7.45 公分、足徑 5.4 公分' + NCHAR(10) + N'原作尺寸：高 3.2-3.7 公分、口徑 14.9 公分、足徑 10.8 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'汝窯 青瓷盤 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'盤，敞口，弧形圓壁自底足順著口沿向外斜直而上，平形底，圈足微外撇，形成具有金銀器風格的 「捲足」。全器罩施汝釉，隱含淡碧與淺粉二色，釉面滿佈開片紋，口沿釉薄處呈現淡粉紅色。底部有縮釉，並留存五枚支燒痕；底心刻篆書 「甲」字。縮釉、題刻、支燒痕處露出淡黃色胎。', 890.00, 20, N'/media/catalog/ceramic/故瓷018182N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/61067?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1320000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 3.2-1.85 公分、口徑 7.45 公分、足徑 5.4 公分', 'b673e226-4613-9fbe-5ce6-9df7c93e6791'),
    ('f82ef753-b3c4-94e4-4d75-03dc4056b7c2', N'ENAMEL', N'artifact-故琺000952N000000000', N'銅胎畫琺瑯花石蜻蜓鼻煙壺－縮小複製品', N'琺瑯以釉料與燒製換來鮮明而細緻的層次。這件「銅胎畫琺瑯花石蜻蜓鼻煙壺」縮小複製品，把這份講究工序的華美濃縮成展示亮點。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：琺瑯器' + NCHAR(10) + N'年代：清 乾隆' + NCHAR(10) + N'商品尺寸：寬 1.75 公分、高 2.75 公分' + NCHAR(10) + N'原作尺寸：寬 3.5 公分、高 5.5 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'銅胎畫琺瑯花石蜻蜓鼻煙壺 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'扁壺雙面開光繪靈芝、花、石與蜻蜓，餘以粉色地繪轉枝花果紋，底有楷書「乾隆年製」黑款，有銅鍍金雕花蓋與牙匙。應為廣琺瑯。', 770.00, 20, N'/media/catalog/enamel/故琺000952N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/61912?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1340000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'寬 1.75 公分、高 2.75 公分', 'f46296e5-6833-b3fc-ee63-9ebdcb852036'),
    ('5c1fd6a1-a91a-4f50-466b-03f013357a69', N'PAINTING', N'artifact-故畫00150300000', N'元趙孟頫百祿圖　卷－縮小複製品', N'畫面不只記錄所見，也保存創作者觀看世界的方式。這件「元趙孟頫百祿圖　卷」縮小複製品，邀你把這份想像帶進自己的空間。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：繪畫' + NCHAR(10) + N'年代：元武宗至大二年（1309）' + NCHAR(10) + N'商品尺寸：25.75 × 208.8 公分' + NCHAR(10) + N'原作尺寸：51.5 × 417.6 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'元趙孟頫百祿圖　卷 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'本幅描寫鹿群徜徉於山水間，或飲水，或對望，各具姿態。「鹿」與「祿」同音，寓意官祿。畫中松樹代表「長壽」，山水間並點綴表徵祥瑞的靈芝與罕見白鹿，整幅畫充滿吉祥的寓意。畫面青綠色調乾淨明亮，松樹與岩石的畫法，很接近清宮畫家方琮為郎世寧〈畫青羊〉所補背景，顯示此作與清代宮廷畫風的關係。(20100710)', 890.00, 20, N'/media/catalog/painting/故畫00150300000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/955?dep=P', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'25.75 × 208.8 公分', '3eac63c5-7d5c-dbc8-92cf-62c53d4a42d1'),
    ('fbec087f-b11b-c6dd-d70e-045fcddd760a', N'COIN', N'artifact-購錢004693N000000000', N'宣和通寶－縮小複製品', N'方寸之間，裝得下年代、制度與人們往來交易的痕跡。這件「宣和通寶」縮小複製品，從一枚錢幣打開認識歷史的新角度。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：錢幣' + NCHAR(10) + N'年代：北宋' + NCHAR(10) + N'商品尺寸：待測量' + NCHAR(10) + N'原作尺寸：待測量' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'宣和通寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'銅質。方孔圓錢，正面有篆書：「宣和通寶」四字，背面無文。', 810.00, 20, N'/media/catalog/coin/購錢004693N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/14031?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1330000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'待測量', 'bc3895d3-4b13-ddd6-6390-c78d1c8a24a7'),
    ('d3679bee-e9d2-15aa-b357-050e548cfe16', N'CERAMIC', N'artifact-贈瓷000454N000000000', N'陶編鐘－縮小複製品', N'一件陶瓷，可以從遠處看整體，也值得靠近欣賞質感。這件「陶編鐘」縮小複製品，為收藏角落留下一份安定而耐看的風景。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：陶瓷' + NCHAR(10) + N'年代：春秋' + NCHAR(10) + N'商品尺寸：待測量' + NCHAR(10) + N'原作尺寸：待測量' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'陶編鐘 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'陶鐘，器型仿青銅器編鐘，方鈕，鐘身有二十四枚，上下緣塗白陶衣，鼓部有白陶衣紋飾，已漫渙不清。', 1370.00, 20, N'/media/catalog/ceramic/贈瓷000454N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/43484?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1330000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'待測量', '641e6f09-4977-96b5-c2fd-0661277f65cc'),
    ('9d52bf03-7101-97d9-85fb-05fd9b2739dd', N'PAINTING', N'artifact-故畫00356500010', N'明人畫扇（亨）　冊　明宋旭暮雲春樹－縮小複製品', N'一幅畫最迷人的地方，是每次觀看都可能發現不同線索。這件「明人畫扇（亨）　冊　明宋旭暮雲春樹」縮小複製品，把畫面的節奏與意境帶進日常空間。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：繪畫' + NCHAR(10) + N'年代：明神宗萬曆三十年（1602）' + NCHAR(10) + N'商品尺寸：7.6 × 23.45 公分' + NCHAR(10) + N'原作尺寸：15.2 × 46.9 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'明人畫扇（亨）　冊　明宋旭暮雲春樹 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'宋旭（西元一五二五－一六○五年以後）字石門、初暘。後為僧，法名祖賢，又號天池髮僧、景而居士。嘉興人（一作湖州）博宗內外典，通禪理。善山水，兼長人物，萬曆間名重海內。師沈周，巨幅大障，頗有氣勢。喜用八分書款，萬曆三十三年，年八十一，猶在人世。' + NCHAR(13) + NCHAR(10) + N'　　平視河山，丘陵起伏，山光雲影，浮躍於眼前，寫暮色四合，用水墨渲染水天，橋上朱欄與寺廟紅牆，配以石綠點染樹葉，復令人於暮色漸垂中，有一分春日盎然生機，湧於心胸。本幅為「明人畫扇－亨」冊第十開。', 650.00, 20, N'/media/catalog/painting/故畫00356500010/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/15439?dep=P', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1360000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'7.6 × 23.45 公分', 'dd9f9eb2-b226-dff5-428b-0d754bec2efb'),
    ('ec717c70-1ef5-4f84-f533-0685f9bb16f5', N'JADE', N'artifact-故玉006635N000000000', N'玉螭紋帶扣－縮小複製品', N'從光澤、質地到琢磨留下的細節，玉器總有值得反覆欣賞之處。玉螭紋帶扣縮小複製品，邀你用更親近的距離重新認識它。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：玉器' + NCHAR(10) + N'年代：宋至元' + NCHAR(10) + N'商品尺寸：長 3.45 公分、寬 2.6 公分' + NCHAR(10) + N'原作尺寸：長 6.9 公分、寬 5.2 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'玉螭紋帶扣 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'玉質，邊緣染褐沁，帶綹。全器琢成帶扣，由兩環形玉片組成，上方各有一片近似三角形的突出物，中間也各帶一圓穿孔。一玉表面浮雕蜷曲盤繞於璧面的螭，另一面玉表面陰刻幾何紋。兩玉片由活動式扣環連結在一起。', 1190.00, 20, N'/media/catalog/jade/故玉006635N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/57707?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'長 3.45 公分、寬 2.6 公分', '49c1ec1a-db0a-7438-2fd6-c95823632206'),
    ('2cdd012e-04ae-b23b-42cc-06e37a6b49bb', N'ENAMEL', N'artifact-故琺000943N000000000', N'銅胎畫琺瑯花卉紋橢圓盒－縮小複製品', N'琺瑯以釉料與燒製換來鮮明而細緻的層次。這件「銅胎畫琺瑯花卉紋橢圓盒」縮小複製品，把這份講究工序的華美濃縮成展示亮點。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：琺瑯器' + NCHAR(10) + N'年代：清 雍正' + NCHAR(10) + N'商品尺寸：長 2.4 公分、寬 2 公分、高 1.45 公分' + NCHAR(10) + N'原作尺寸：長 4.8 公分、寬 4.0 公分、高 2.9 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'銅胎畫琺瑯花卉紋橢圓盒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'橢圓形掀蓋銅盒。器表通體先上一層白色底釉， 再以紅、黃、藍、白等色滿繪向日葵、水仙、雛菊等百花， 餘填黑色地釉。盒內罩淺藍色釉， 蓋沿寫「雍正年製」（1723-1735）單行黑料楷書款。紋飾設計與光影點染， 深受西洋風格影響。', 780.00, 20, N'/media/catalog/enamel/故琺000943N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/61904?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1340000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'長 2.4 公分、寬 2 公分、高 1.45 公分', '34a3678b-72c3-de10-7cf5-b6d1cc22dda0'),
    ('9ad86c6f-c837-b601-450e-07d0971685ef', N'JADE', N'artifact-故玉004360N000000000', N'玉羊－縮小複製品', N'一件玉器，可以寄託品味，也能收藏一段時代記憶。以玉羊為靈感製作的縮小複製品，為展示空間添上一份沉靜氣質。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：玉器' + NCHAR(10) + N'年代：遼或北宋' + NCHAR(10) + N'商品尺寸：長 1.85 公分、寬 0.8 公分、高 1.6 公分；木座長 1.85 公分、寬 1.05 公分、高 0.35 公分、連座高 1.9 公分' + NCHAR(10) + N'原作尺寸：長 3.7 公分、寬 1.6 公分、高 3.2 公分；木座長 3.7 公分、寬 2.1 公分、高 0.7 公分、連座高 3.8 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'玉羊 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'本器為玉羊，玉質，帶黃絲沁，器表油潤有光澤。體態壯碩，呈跪姿，羊角向內螺旋，嘴微張，羊眼為桯具鑽磨而成，腹部橫穿一圓孔，類似本器之圓雕動物可見於遼陳國公主墓出土馬形玉飾。本器由題材、跪踞形式、桯具使用方式，穿孔所顯現的使用功能，屬遼或北宋作品。本器附紫檀木座，存放在院藏「紫檀雕蟠龍方盒百什件」（故雜877）中。', 1070.00, 20, N'/media/catalog/jade/故玉004360N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/71754?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'長 1.85 公分、寬 0.8 公分、高 1.6 公分；木座長 1.85 公分、寬 1.05 公分、高 0.35 公分、連座高 1.9 公分', '4d81716c-1255-e2b9-fb58-367ab986c61c'),
    ('54c916b7-1027-f153-cf37-0add148d051b', N'COIN', N'artifact-購錢004669N000000000', N'元祐通寶－縮小複製品', N'方寸之間，裝得下年代、制度與人們往來交易的痕跡。這件「元祐通寶」縮小複製品，從一枚錢幣打開認識歷史的新角度。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：錢幣' + NCHAR(10) + N'年代：北宋' + NCHAR(10) + N'商品尺寸：待測量' + NCHAR(10) + N'原作尺寸：待測量' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'元祐通寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'銅質。方孔圓錢，正面有楷書：「元祐通寶」四字，背面無文。', 790.00, 20, N'/media/catalog/coin/購錢004669N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/14007?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1330000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'待測量', 'ed560770-63b0-f440-6f1c-e897144b460e'),
    ('a2590be3-aed0-5694-ab65-0bc4cf1c12af', N'COIN', N'artifact-購錢004753N000000000', N'熙寧元寶－縮小複製品', N'方寸之間，裝得下年代、制度與人們往來交易的痕跡。這件「熙寧元寶」縮小複製品，從一枚錢幣打開認識歷史的新角度。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：錢幣' + NCHAR(10) + N'年代：北宋' + NCHAR(10) + N'商品尺寸：待測量' + NCHAR(10) + N'原作尺寸：待測量' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'熙寧元寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'銅質。方孔圓錢，正面有楷書：「熙寧元寶」四字，背面無文。', 740.00, 20, N'/media/catalog/coin/購錢004753N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/14091?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1340000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'待測量', 'dee6ee18-89bc-30e1-c999-c2240c671063'),
    ('ff954aa2-e4e7-938c-be59-0da193cd1355', N'ENAMEL', N'artifact-故琺000973N000000000', N'玻璃胎畫琺瑯圖案式花紋鼻煙壺－縮小複製品', N'色彩是琺瑯最直接的吸引力，工序與細節則值得再三欣賞。以玻璃胎畫琺瑯圖案式花紋鼻煙壺為靈感製作的縮小複製品，讓空間多一抹典藏氣息。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：琺瑯器' + NCHAR(10) + N'年代：清 乾隆' + NCHAR(10) + N'商品尺寸：高 2.73 公分、寬 2 公分' + NCHAR(10) + N'原作尺寸：高 5.45 公分、寬 4.0 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'玻璃胎畫琺瑯圖案式花紋鼻煙壺 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'乳白半透明玻璃扁圓壺，頸有粉地卷草紋，瓶身繪伊斯蘭風格的對稱圖樣，底有楷書「乾隆年製」刻款。帶銅鍍金雕花蓋與牙匙。', 890.00, 20, N'/media/catalog/enamel/故琺000973N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/61931?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1340000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 2.73 公分、寬 2 公分', '5e98411e-d3da-db6f-4264-5ee8d60d97b9'),
    ('96f9586a-9889-b543-24df-0ec31ce9e10e', N'LACQUER', N'artifact-故漆000476N000000000', N'剔彩天下太平雙龍紋長方盤－縮小複製品', N'漆藝講究耐心，也讓器物擁有難以取代的深沉質感。這件「剔彩天下太平雙龍紋長方盤」縮小複製品，是一件越看越能發現味道的收藏。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：漆器' + NCHAR(10) + N'年代：明 萬曆' + NCHAR(10) + N'商品尺寸：長 16.1 公分、寬 10.15 公分、高 2.65 公分、深 1.6 公分、足徑長 13.5 公分、寬 7.55 公分' + NCHAR(10) + N'原作尺寸：長 32.2 公分、寬 20.3 公分、高 5.3 公分、深 3.2 公分、足徑長 27.0 公分、寬 15.1 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'剔彩天下太平雙龍紋長方盤 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'方盤，斜沿委角，圈足，足內髹黑漆。底刻大明萬曆己丑年製，為萬曆十七年，西元1589年。盤心為雙龍左右並峙，中央為自山峰長出的一枝花朵，花上一「天下太平」錢幣，兩旁還有珊瑚、麥穗，如意雲紋排列兩側，底為紅地花形斜方格錦地。雙龍造型相同，一足登地躍起，龍首及龍尾朝中央，身軀圓勁，刻意表現足部肌肉，張口瞪眼，龍鬚飄飄。畫面下段，綠地波浪紋錦地，最下方紅漆海水起伏，前方矗立三座山峰，山石旁海水洶湧，激起浪花。畫面穩重熱鬧，漆色潤，刀法凝練，表現皇家品味。', 890.00, 20, N'/media/catalog/lacquer/故漆000476N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/17571?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'長 16.1 公分、寬 10.15 公分、高 2.65 公分、深 1.6 公分、足徑長 13.5 公分、寬 7.55 公分', '0dc02988-7d76-b517-736a-e8ca5ddcd70e'),
    ('42a2f440-6512-325c-b26b-0f4dacdc4b48', N'ENAMEL', N'artifact-故琺000845N000000000', N'銀嵌銅胎畫琺瑯西洋人物圖鼻煙盒－縮小複製品', N'琺瑯以釉料與燒製換來鮮明而細緻的層次。這件「銀嵌銅胎畫琺瑯西洋人物圖鼻煙盒」縮小複製品，把這份講究工序的華美濃縮成展示亮點。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：琺瑯器' + NCHAR(10) + N'年代：清 乾隆' + NCHAR(10) + N'商品尺寸：長 3.15 公分、寬 2.35 公分、高 0.85 公分' + NCHAR(10) + N'原作尺寸：長 6.3 公分、寬 4.7 公分、高 1.7 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'銀嵌銅胎畫琺瑯西洋人物圖鼻煙盒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'長方掀蓋銀盒，蓋嵌銅胎畫琺瑯片，以點畫法彩繪衣著華麗的西洋男女於樹下相偎，用色明亮鮮麗，畫工細膩。琺瑯片背面有楷書「胡思明」黑款，查《清內務府造辦處活計檔》中有胡思明在乾隆六年（1741）及七年時為粵海關送入清宮造辦處畫琺瑯人之記錄，這件乾隆時期嵌胡思明畫琺瑯片銀質鼻煙盒，是罕見工匠姓名見諸於史料且有落款的器物，外觀造型無疑源自西洋鼻煙盒，更顯示乾隆時期廣東工匠在畫琺瑯技術層面上，成熟地掌握西洋技法、風格。', 860.00, 20, N'/media/catalog/enamel/故琺000845N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/61829?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1340000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'長 3.15 公分、寬 2.35 公分、高 0.85 公分', '0eace746-cadb-7abc-1d26-1d35e696cead'),
    ('db98366b-28ba-b965-e311-10f9330e7a2f', N'CERAMIC', N'artifact-故瓷018054N000000000', N'青花花卉紋菱花式盆－縮小複製品', N'從日常器用到典藏珍品，陶瓷記錄了不同時代對生活之美的想像。這件「青花花卉紋菱花式盆」縮小複製品，讓這段美感自然融入展示空間。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：陶瓷' + NCHAR(10) + N'年代：明 永樂' + NCHAR(10) + N'商品尺寸：口徑 11 公分、高 6.25 公分' + NCHAR(10) + N'原作尺寸：口徑 22.0 公分、高 12.5 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'青花花卉紋菱花式盆 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'六瓣菱花形花盆，侈口，深直壁下斂，厚胎。平底與圈足接縫形成一圈花式突棱，為接底之巧妙運用。器內施白釉，器表釉下鈷藍畫花，青色呈暈染狀。器外表以細筆鉤畫纏枝番蓮、折枝牡丹及靈芝，再粗筆填彩。外底白中偏藍綠色，足底平切露白胎，整體具明永樂、宣德花器的特徵。此時期的花盆，除青花之外，尚有五彩及各類單色釉，色彩豐富。', 890.00, 20, N'/media/catalog/ceramic/故瓷018054N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/60973?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1330000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'口徑 11 公分、高 6.25 公分', '980f5a6e-eb25-9a09-607e-c56dd222a6f5'),
    ('02ea7637-bd65-5b08-4d42-125e9d41d66c', N'LACQUER', N'artifact-故漆000336N000000000', N'剔彩春壽寶盒－縮小複製品', N'漆器耐看的地方，在於表面質感與製作時間共同留下的韻味。以剔彩春壽寶盒為靈感製作的縮小複製品，適合在近處慢慢欣賞。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：漆器' + NCHAR(10) + N'年代：清 乾隆' + NCHAR(10) + N'商品尺寸：通高 5.65 公分、口徑 15.2 公分、底徑 11.55 公分' + NCHAR(10) + N'原作尺寸：通高 11.3 公分、口徑 30.4 公分、底徑 23.1 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'剔彩春壽寶盒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'雕漆盒，器蓋同形，子母口、淺壁、平底，附平頂蓋，器表以剔彩為飾，漆層厚。蓋面中央飾「春」字，內有圓圈開光一壽星，兩側為雙龍，下飾聚寶盆，霞光四出，分層剔出各樣色彩，蓋緣與器腹均開光山水人物。器內壁髹黑漆，底面黑漆，有填金刻款「大清乾隆年製」六字三行楷款。', 820.00, 20, N'/media/catalog/lacquer/故漆000336N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/50940?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'通高 5.65 公分、口徑 15.2 公分、底徑 11.55 公分', '7834bcf0-1403-d85f-2ef1-171ec38cfc3a'),
    ('3879be94-6b3e-5be8-c62e-16d9f932b65f', N'ENAMEL', N'artifact-故琺000887N000000000', N'掐絲琺瑯香插－縮小複製品', N'色彩是琺瑯最直接的吸引力，工序與細節則值得再三欣賞。以掐絲琺瑯香插為靈感製作的縮小複製品，讓空間多一抹典藏氣息。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：琺瑯器' + NCHAR(10) + N'年代：清 乾隆' + NCHAR(10) + N'商品尺寸：高 1.05 公分、徑 5.45 公分' + NCHAR(10) + N'原作尺寸：高 2.1 公分、徑 10.9 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'掐絲琺瑯香插 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'淺圓盤，盤心安一小瓶，以供插香。全器施以淺藍釉，內外以掐絲琺瑯裝飾西番花、卷枝花卉。以小瓶為中心，圍繞著四枚如意形開光，內飾黃地回首夔龍紋。盤沿，銅邊鍍金。小瓶，口外侈，縮頸，扁鼓腹，撇足成一花瓣底座。口、頸及底座皆鍍金，瓶身飾以藍地五瓣花草紋。器底繪飾四枚紅色番蓮花捲草紋。底心鏨以楷款「乾隆年製」。', 900.00, 20, N'/media/catalog/enamel/故琺000887N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/61866?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1340000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 1.05 公分、徑 5.45 公分', 'ff07cadf-8aac-cc92-499a-8a05226ae8cf'),
    ('eb02eade-f42d-ead0-0393-17ee59dcb4d7', N'ENAMEL', N'artifact-故琺000942N000000000', N'銅胎畫琺瑯番蓮紋瓶－縮小複製品', N'想讓展示空間更有亮點，又保留古典工藝的細膩感，這件「銅胎畫琺瑯番蓮紋瓶」縮小複製品會是一件很有存在感的收藏。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：琺瑯器' + NCHAR(10) + N'年代：清 雍正' + NCHAR(10) + N'商品尺寸：高 15.05 公分、口徑 5.95 公分' + NCHAR(10) + N'原作尺寸：高 30.1 公分、口徑 11.9 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'銅胎畫琺瑯番蓮紋瓶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'敞口，折沿，長頸，雙螭耳，圓腹，外撇圈足，平底。雙耳鑄造成螭形，器表以畫琺瑯繪製紋飾，折沿為白地紅色捲草紋，器內淺藍地，器表黃地，口外繪藍色如意雲紋，頸部繪纏枝五彩番蓮紋，頸部下緣有四如意形開光，內繪黑地五彩番蓮紋；腹部繪纏枝番蓮紋，下緣飾一全藍色如意雲紋，下接黑地。底部黃地，中央有桃花、桃實及蝙蝠圖紋，桃子內有青花書「雍正年製」四字雙行宋體款。附圓形如意雲足座一只，與故琺941成一對。', 950.00, 20, N'/media/catalog/enamel/故琺000942N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/61903?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1340000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 15.05 公分、口徑 5.95 公分', '86b411f2-e197-1abf-5e12-c6115f41cf7e'),
    ('64be5f8a-a568-863b-1b61-19f1a7628a85', N'BRONZE', N'artifact-中銅000049N000000000', N'者減鐘－縮小複製品', N'有些文物不必鋪陳太多，安靜擺著就很有分量。這件「者減鐘」縮小複製品延續銅器特有的沉著氣質，適合成為展示中的視覺焦點。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：銅器' + NCHAR(10) + N'年代：春秋晚期' + NCHAR(10) + N'商品尺寸：高 22.25 公分、兩銑相距 11.75 公分' + NCHAR(10) + N'原作尺寸：高 44.5 公分、兩銑相距 23.5 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'者減鐘 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'甬鐘，枚為長錐形。甬上飾蟬紋和蟠虺紋，舞部和篆間作蟠虺紋。鼓部由蟠螭紋交錯盤繞而成，左右兩側各伸展出三個龍首，正面鼓部的紋飾局部作淺浮雕。銘文位於兩欒和鉦間，可見字數為七十二字，另有重文四字，合文一字，總計七十七字。銘文如下：「唯正月初吉丁亥，工□王皮□之子者減擇其吉金，自作□鐘，不白不□，不濼不淍，協于我霝籥，卑龢卑孚，用祈眉壽□釐，于其皇祖皇考，若召公壽，若參壽，卑汝□□音音，龢龢倉倉，其登于上下，聞于四方，子子孫孫永保是尚。」依銘文第二句，器主「者減」是春秋晚期吳王「皮□」之子，兩人名號皆為記音形式。全篇銘文內容主要為祈福語和形容此器的樂音悠揚美妙。清宮舊藏，原儲於西苑韻古堂。錄於《西清續鑑‧甲編》卷十七頁十二。', 1490.00, 20, N'/media/catalog/bronze/中銅000049N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/53480?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1300000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 22.25 公分、兩銑相距 11.75 公分', '4fc45a9c-3ece-2027-c95c-960d7385583f'),
    ('e023a78e-1c65-c534-21a8-1b08c08fb248', N'ENAMEL', N'artifact-故琺000903N000000000', N'銅胎畫琺瑯西洋人物圖鼻煙壺－縮小複製品', N'琺瑯工藝把色彩、材質與火候交織在同一件作品裡。這件「銅胎畫琺瑯西洋人物圖鼻煙壺」縮小複製品，適合近看其中豐富而有秩序的視覺層次。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：琺瑯器' + NCHAR(10) + N'年代：清 乾隆' + NCHAR(10) + N'商品尺寸：寬 1.8 公分、高 2.3 公分' + NCHAR(10) + N'原作尺寸：寬 3.6 公分、高 4.6 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'銅胎畫琺瑯西洋人物圖鼻煙壺 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'扁壺綠地彩繪編幅祥雲，雙面開光內彩繪西洋人物，底有楷書「乾隆年製」黑款，有粉色雕花料蓋與牙匙。應為廣琺瑯。', 930.00, 20, N'/media/catalog/enamel/故琺000903N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/61873?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1340000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'寬 1.8 公分、高 2.3 公分', '2c71cb4a-a863-36b1-f017-c62a6908f76f'),
    ('820077ed-4463-e5a5-778e-1bbdaabd51fe', N'LACQUER', N'artifact-故漆000519N000000000', N'剔紅曇花寶盒－縮小複製品', N'光影落在漆面上，每個角度都有不同感受。這件「剔紅曇花寶盒」縮小複製品延續漆器含蓄而精緻的魅力，為展示空間添上一份古雅。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：漆器' + NCHAR(10) + N'年代：清 乾隆' + NCHAR(10) + N'商品尺寸：徑 2.9 公分' + NCHAR(10) + N'原作尺寸：徑 5.8 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'剔紅曇花寶盒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'器作蒸餅式，子母口，淺壁，矮圈足。器髹紅色漆，器蓋面及周壁雕牡丹花卉。器裏及底均髹黑光漆。器內與底各陰刻楷書「曇花寶盒」及「大清乾隆年製」款識填金。', 810.00, 20, N'/media/catalog/lacquer/故漆000519N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/47340?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'徑 2.9 公分', 'f1b0d1a2-1ece-cc32-96f4-a49b5d935311'),
    ('6f0a9c4e-fb0a-30cc-6457-1e3d57f83eb9', N'ENAMEL', N'artifact-故琺000844N000000000', N'掐絲琺瑯瓶－縮小複製品', N'色彩是琺瑯最直接的吸引力，工序與細節則值得再三欣賞。以掐絲琺瑯瓶為靈感製作的縮小複製品，讓空間多一抹典藏氣息。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：琺瑯器' + NCHAR(10) + N'年代：清 乾隆' + NCHAR(10) + N'商品尺寸：高 3.9 公分、口徑 1.9 公分、腹徑 1.55 公分、底徑 1.5 公分' + NCHAR(10) + N'原作尺寸：高 7.8 公分、口徑 3.8 公分、腹徑 3.1 公分、底徑 3.0 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'掐絲琺瑯瓶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'銅胎掐絲琺瑯瓶，侈口短頸，碩腹，足外撇，鑄連於一金屬如意足座上。口部以透雕螭紋的金屬封住，頸部與腹外壁均以掐絲技法裝飾，頸部飾蕉葉；腹外壁飾藍地獸面紋，上下分別有一圈淺綠色如意雲頭，腹足交界處露胎銅稜一圈，足牆外壁飾淺綠色如意雲頭，收納於雕紫檀蟠龍方盒多寶格（故雕877）中。', 800.00, 20, N'/media/catalog/enamel/故琺000844N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/71745?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1340000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 3.9 公分、口徑 1.9 公分、腹徑 1.55 公分、底徑 1.5 公分', '05caf9a2-02e9-7373-683e-cc6050de934d'),
    ('fcbc0b11-44f5-48bc-a4ab-200d53bd1d66', N'CARVING', N'artifact-贈雕000188N000000000', N'牙梳－縮小複製品', N'不同材料有不同個性，好的雕刻懂得順勢而為。以牙梳為靈感製作的縮小複製品，保留一份因材施藝的工藝趣味。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：雕刻' + NCHAR(10) + N'年代：宋至元' + NCHAR(10) + N'商品尺寸：長 4.45 公分、寬 1.9 公分、背厚 0.15 公分' + NCHAR(10) + N'原作尺寸：長 8.9 公分、寬 3.8 公分、背厚 0.3 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'牙梳 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'全器半月形器之背寬大致相同，兩端平直，梳齒長度由中央向兩側依序遞減，梳背外緣陰刻兩道弦紋為飾，齒與背之間陰刻二道弦紋間隔。一根梳齒殘缺。全器並不平整，製作工藝樸拙。', 1000.00, 20, N'/media/catalog/carving/贈雕000188N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/45416?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1310000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'長 4.45 公分、寬 1.9 公分、背厚 0.15 公分', 'da2e191e-b1f7-7eb6-e85b-37ea6f23695e'),
    ('4254491a-9ff9-d163-5f1a-21b428b1dfab', N'COIN', N'artifact-購錢004755N000000000', N'天聖元寶－縮小複製品', N'方寸之間，裝得下年代、制度與人們往來交易的痕跡。這件「天聖元寶」縮小複製品，從一枚錢幣打開認識歷史的新角度。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：錢幣' + NCHAR(10) + N'年代：北宋' + NCHAR(10) + N'商品尺寸：待測量' + NCHAR(10) + N'原作尺寸：待測量' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'天聖元寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'銅質。方孔圓錢，正面有楷書：「天聖元寶」四字，背面無文。', 710.00, 20, N'/media/catalog/coin/購錢004755N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/14093?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1330000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'待測量', 'd89f1abc-4108-0b24-56ea-7ccb61e5c439'),
    ('b6dfe08b-71e6-9404-c3bc-22d770b22932', N'CERAMIC', N'artifact-故瓷010536N000000000', N'白瓷印花獅戲圖蔗段式洗－縮小複製品', N'從日常器用到典藏珍品，陶瓷記錄了不同時代對生活之美的想像。這件「白瓷印花獅戲圖蔗段式洗」縮小複製品，讓這段美感自然融入展示空間。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：陶瓷' + NCHAR(10) + N'年代：金至元' + NCHAR(10) + N'商品尺寸：高 2.65 公分、口徑 10.55 公分、底徑 5 公分' + NCHAR(10) + N'原作尺寸：高 5.3 公分、口徑 21.1 公分、底徑 10.0 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'白瓷印花獅戲圖蔗段式洗 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'侈口深壁洗，斜壁微弧，平底腹下以陰弦紋一道斜收折為底部，具圈足，足端平磨無釉，口鑲銅釦稜；外壁飾凸弦紋一道，作蔗段式。器裡以印花為飾，口沿下印弦紋二道，並印轉枝海石榴紋飾。底面寬平，印雄獅戲球紋。獅紋佔器面大半，具濃厚的綣髮與揚起的綣尾，並作巨目、濃眉、回首咧嘴銜長綬帶，帶端繫繡球。本器與故瓷12282大致相似，然釉汁濃厚，紋飾難辨。', 930.00, 20, N'/media/catalog/ceramic/故瓷010536N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/30165?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1320000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 2.65 公分、口徑 10.55 公分、底徑 5 公分', 'fe68be68-4f6b-1950-65ab-3f2ef8dc07b8'),
    ('2290eadf-de58-9cab-1102-236481293f00', N'PAINTING', N'artifact-故畫00353600008', N'明人畫扇集冊　冊　明丁雲鵬應真像－縮小複製品', N'從構圖、線條到題材安排，書畫總有值得慢慢閱讀之處。以明人畫扇集冊　冊　明丁雲鵬應真像為靈感製作的縮小複製品，讓欣賞不必受距離限制。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：繪畫' + NCHAR(10) + N'年代：明神宗萬曆四年（1576）' + NCHAR(10) + N'商品尺寸：8.05 × 25.05 公分' + NCHAR(10) + N'原作尺寸：16.1 × 50.1 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'明人畫扇集冊　冊　明丁雲鵬應真像 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'丁雲鵬（生於西元一五四七或一五四八年，至年八十二尚在世），字南羽，號聖華居士，安徽休寧人。善畫佛道人物，得唐吳道子法，又白描法學李公麟，為晚明人物畫名家。' + NCHAR(13) + NCHAR(10) + N'　　臨溪蒼松一株，枝幹虯結，松蔭下坐二羅漢。背後遠山隱約可見。款云：「萬曆丙子（西元一五七六年）八月寫。」本幅構圖意境甚雅，用筆多生圭角，略欠生動。此作選自「明人畫扇集冊」第八幅，是本院所藏丁氏作品中最早的一件。', 810.00, 20, N'/media/catalog/painting/故畫00353600008/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/18370?dep=P', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1360000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'8.05 × 25.05 公分', '4e1e1697-43f7-dc04-b2cd-c4026c735c29'),
    ('a6a784f8-bd29-7b33-31c2-238a6ade8bc0', N'BRONZE', N'artifact-故銅002509N000000000', N'銅鎏金扁壺－縮小複製品', N'青銅器迷人的地方，在於器物本身與漫長年代共同形成的質感。以銅鎏金扁壺為靈感製作的縮小複製品，值得從不同角度細看。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：銅器' + NCHAR(10) + N'年代：西漢' + NCHAR(10) + N'商品尺寸：高 4 公分' + NCHAR(10) + N'原作尺寸：高 8.0 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'銅鎏金扁壺 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'扁壺，圓口、短頸、扁腹、方圈足，器肩兩側有附耳。通體鎏金。', 1400.00, 20, N'/media/catalog/bronze/故銅002509N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/62210?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1310000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 4 公分', '59158f1e-8c8d-e01d-d774-c16416f70242'),
    ('b1584a00-6a4c-648c-33ab-23ad3bb9f51c', N'LACQUER', N'artifact-故漆000539N000000000', N'填漆春壽龍紋六瓣圓盤－縮小複製品', N'漆藝講究耐心，也讓器物擁有難以取代的深沉質感。這件「填漆春壽龍紋六瓣圓盤」縮小複製品，是一件越看越能發現味道的收藏。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：漆器' + NCHAR(10) + N'年代：清 乾隆' + NCHAR(10) + N'商品尺寸：口徑 6.35 公分' + NCHAR(10) + N'原作尺寸：口徑 12.7 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'填漆春壽龍紋六瓣圓盤 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'尖瓣式盒，胎薄，子母口，平底無足，造型優雅，盒內髹黑漆。黃褐漆地，上下口沿飾花卉紋，盒緣為六組山水人物，彈琴、舞鶴等，飾雲紋，盒蓋飾明嘉靖以來的壽春吉祥圖案。漆色暗沉，以黑、橘、綠、褐為主調，顏色種類眾多，線條流暢，混合描漆，部份漆面不平順，工藝技術中規中矩。', 670.00, 20, N'/media/catalog/lacquer/故漆000539N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/18373?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'口徑 6.35 公分', 'd44a3f77-034b-8636-6bdc-de154e819c38'),
    ('89945311-a040-6a3f-e621-25963c0f1e6d', N'ENAMEL', N'artifact-故琺000980N000000000', N'銅胎畫琺瑯杏柳春燕母子鼻煙壺－縮小複製品', N'琺瑯以釉料與燒製換來鮮明而細緻的層次。這件「銅胎畫琺瑯杏柳春燕母子鼻煙壺」縮小複製品，把這份講究工序的華美濃縮成展示亮點。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：琺瑯器' + NCHAR(10) + N'年代：清 乾隆' + NCHAR(10) + N'商品尺寸：寬 1.85 公分、高 2.7 公分' + NCHAR(10) + N'原作尺寸：寬 3.7 公分、高 5.4 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'銅胎畫琺瑯杏柳春燕母子鼻煙壺 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'銅胎扁壺，通景式構圖繪母子休憩於岸邊柳樹湖石旁，杏花點點，春燕飛翔於杏花柳樹間，一邊有兩頭水牛並肩而立。設色清新淡雅，底有「乾隆年製」楷書藍款。有銅鍍金雕花蓋與牙匙。原屬於永壽宮之收藏。', 780.00, 20, N'/media/catalog/enamel/故琺000980N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/61932?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1340000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'寬 1.85 公分、高 2.7 公分', '4d55ac8c-2a96-5c84-aa63-a0f5f383dbe5'),
    ('41d97446-f0a6-7294-3721-262397a32469', N'BRONZE', N'artifact-購銅000070N000000000', N'龍氏神人畫象紋鏡－縮小複製品', N'有些文物不必鋪陳太多，安靜擺著就很有分量。這件「龍氏神人畫象紋鏡」縮小複製品延續銅器特有的沉著氣質，適合成為展示中的視覺焦點。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：銅器' + NCHAR(10) + N'年代：東漢' + NCHAR(10) + N'商品尺寸：直徑 9.55 公分' + NCHAR(10) + N'原作尺寸：直徑 19.1 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'龍氏神人畫象紋鏡 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'圓鏡，半球鈕，連珠紋鈕座。鏡背飾人物及動物，間以蔓華紋。外環銘文26字：「龍氏作竟隹平且好，明天日月世之保，上有仙人不知老，渴飲玉泉。」鏡緣有三角形紋及卷雲紋。', 1260.00, 20, N'/media/catalog/bronze/購銅000070N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/14836?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1310000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'直徑 9.55 公分', '7e96b045-34db-5e14-a54d-3968f920ae24'),
    ('c4ff0470-7eb7-e9e5-7cf4-27be5b936442', N'JADE', N'artifact-故玉004354N000000000', N'玉握桿端飾－縮小複製品', N'玉石經過琢磨才成器，也在流傳中留下不同時代的眼光。玉握桿端飾化為縮小複製品，讓這份溫潤含蓄的玉器之美走進日常。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：玉器' + NCHAR(10) + N'年代：春秋晚期' + NCHAR(10) + N'商品尺寸：高 1.6 公分、口徑 1.3 公分、腹徑 1.9 公分；木座長 1.95 公分、寬 1.9 公分、高 0.5 公分、連座高 1.85 公分；銅膽高 1.3 公分、口徑 0.9 公分' + NCHAR(10) + N'原作尺寸：高 3.2 公分、口徑 2.6 公分、腹徑 3.8 公分；木座長 3.9 公分、寬 3.8 公分、高 1.0 公分、連座高 3.7 公分；銅膽高 2.6 公分、口徑 1.8 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'玉握桿端飾 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'本器為握桿端飾，玉質，器表浮雕側面龍首紋，器內重新掏膛，增加容積。器腹後打對稱兩孔。從器表規律排列的側面龍首紋，以及紋飾的琢磨痕跡來看，屬春秋晚期作品。本器附銅膽、木座，存放在院藏「紫檀雕蟠龍方盒百什件」（故雜877）中。', 1640.00, 20, N'/media/catalog/jade/故玉004354N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/71722?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 1.6 公分、口徑 1.3 公分、腹徑 1.9 公分；木座長 1.95 公分、寬 1.9 公分、高 0.5 公分、連座高 1.85 公分；銅膽高 1.3 公分、口徑 0.9 公分', '21f8e327-55c4-6a5c-dd91-5c079169028f'),
    ('860f9738-cf1f-b1ce-b8c1-2854fd6cff7b', N'CERAMIC', N'artifact-購瓷000154N000000000', N'灰釉直紋雙耳罐－縮小複製品', N'泥土經過塑形與窯火，才成為能被長久欣賞的器物。這件「灰釉直紋雙耳罐」縮小複製品，把陶瓷溫雅耐看的氣質帶到眼前。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：陶瓷' + NCHAR(10) + N'年代：戰國' + NCHAR(10) + N'商品尺寸：高 11.05 公分、腹寬 17.25 公分、口徑 8.75 公分' + NCHAR(10) + N'原作尺寸：高 22.1 公分、腹寬 34.5 公分、口徑 17.5 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'灰釉直紋雙耳罐 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'春秋、戰國時期，江蘇、浙江一帶高溫灰釉器的燒造頗為盛行。這件灰釉瓷直紋雙耳罐，是以瓷土為胎，施以透明鈣灰釉，在1200度的高溫下燒製而成的作品。罐呈直口、斜肩、圓鼓腹、腹部下收、平底。肩上對稱位置有二環形繫耳，耳內銜環。胎呈黃褐色，器表施釉至器腹中間，釉色青黃，釉層較薄，並有剝釉現象。器身上最搶眼之處是位於肩部和上腹部的直紋瓦楞線刻紋，同樣的作品在浙江德清亭子橋窯址可以得見，江蘇無錫鴻山越國貴族墓葬中也有類似作品出土。', 1300.00, 20, N'/media/catalog/ceramic/購瓷000154N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/43031?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1320000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 11.05 公分、腹寬 17.25 公分、口徑 8.75 公分', 'c444502c-9cb8-4abd-4176-ab10f4acba41'),
    ('d13125a5-6481-da3b-7669-288977a07368', N'CERAMIC', N'artifact-中日瓷000005N000000000', N'墨地素三彩四季花鳥瓷方瓶－縮小複製品', N'一件陶瓷，可以從遠處看整體，也值得靠近欣賞質感。這件「墨地素三彩四季花鳥瓷方瓶」縮小複製品，為收藏角落留下一份安定而耐看的風景。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：陶瓷' + NCHAR(10) + N'年代：清 康熙' + NCHAR(10) + N'商品尺寸：口徑 7.6 公分、肩部 7.5 × 7.5 公分、底 5.5 × 5.5 公分、高 25.5 公分' + NCHAR(10) + N'原作尺寸：口徑 15.2 公分、肩部 15 × 15 公分、底 11 × 11 公分、高 51 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'墨地素三彩四季花鳥瓷方瓶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'方瓶，圓撇口、長頸、平方肩下折，長筒型器身，平底。上圓下方器型，取琮式瓶天圓地方的造型概念。平底心有四方臍，內有透明釉下青花書「大清康熙年製」楷款。字體筆法隨性，為康熙時期民窯的作品。器內施白釉，外無釉，高溫素燒後，在無釉素坯的外壁上以焦墨鉤勒、點畫紋飾輪廓，再填繪綠葉，黃、紫色夏荷，秋菊，芙蓉等四季花。素坯留白作梅花，並有蝴蝶、鳥雀穿梭其間。花葉色彩分明，釉色分濃淡，使紋飾有陰陽向背的層次感。細心避開紋飾，填入勻亮如漆的墨地。彩上再罩一層透明乳白鉛釉。此類高溫素坯上低溫鉛釉的作品，為康熙時期素三彩的特色。 素三彩，釉色以黃、綠、紫、白為主，偶爾也加紅、藍色。或因釉彩直接施於無釉的素燒坯上，故有「素三彩」之稱。墨彩是康熙時期的創燒，濃厚漆黑瑩亮，獨樹一幟。以外銷歐洲為主，傳世數量不多。據推測，當時在歐洲或有如漆器般地被珍視。', 710.00, 20, N'/media/catalog/ceramic/中日瓷000005N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/71959?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1320000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'口徑 7.6 公分、肩部 7.5 × 7.5 公分、底 5.5 × 5.5 公分、高 25.5 公分', '30921d0e-a57d-8a52-1e1c-8af3a657f7ae'),
    ('5c2c494c-6f57-a5b6-bb7f-28dd21023d42', N'PAINTING', N'artifact-故畫003769N000000000', N'御筆寫生 冊－縮小複製品', N'一幅畫最迷人的地方，是每次觀看都可能發現不同線索。這件「御筆寫生 冊」縮小複製品，把畫面的節奏與意境帶進日常空間。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：繪畫' + NCHAR(10) + N'年代：清 乾隆' + NCHAR(10) + N'商品尺寸：長 2.35 公分、寬 2.35 公分' + NCHAR(10) + N'原作尺寸：長 4.7 公分、寬 4.7 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'御筆寫生 冊 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'紙本冊頁，梵夾式。內頁有水墨小品四幅，老幹，有「澂觀」、「會心不遠」朱白文章各一；生意，「德充符」、「中心止水靜」朱文章二；風篁，「中和」、「得佳趣」朱白文章各一；雪妍，「寫生」、「比德」白朱文章各一。前後有木質板面，上書「御筆寫生」填金識款。', 770.00, 20, N'/media/catalog/painting/故畫003769N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/49810?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'長 2.35 公分、寬 2.35 公分', 'e296861e-f213-3698-a598-563740ab4fe6'),
    ('0cb632e8-3a96-02ef-b217-2978804708df', N'ENAMEL', N'artifact-故琺000884N000000000', N'銅胎畫琺瑯芙蓉紋圓盒－縮小複製品', N'色彩是琺瑯最直接的吸引力，工序與細節則值得再三欣賞。以銅胎畫琺瑯芙蓉紋圓盒為靈感製作的縮小複製品，讓空間多一抹典藏氣息。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：琺瑯器' + NCHAR(10) + N'年代：清 乾隆' + NCHAR(10) + N'商品尺寸：高 2.15 公分、口徑 3.3 公分' + NCHAR(10) + N'原作尺寸：高 4.3 公分、口徑 6.6 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'銅胎畫琺瑯芙蓉紋圓盒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'銅胎，覆缽式蓋與器身對合成扁圓盒，圈足。盒內施淺藍釉。蓋頂繪飾一朵盛開之紅芙蓉，花瓣處有一圈白色同心圓，周圍繞之以纏枝花草；蓋面與器身分別以紅藍四朵折枝芙蓉飾之，間以五瓣折枝花卉。盒底色白並有一藍方框雙行「乾隆年製」楷款。', 910.00, 20, N'/media/catalog/enamel/故琺000884N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/61863?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1340000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 2.15 公分、口徑 3.3 公分', 'bc15179b-19b0-9ef3-bfa7-8c08fc09e2b8'),
    ('f31b9fcf-4a2a-4c9a-af6f-2a1e08b69867', N'BRONZE', N'artifact-中銅000606N000000000', N'蟠虺紋鼎－縮小複製品', N'青銅器迷人的地方，在於器物本身與漫長年代共同形成的質感。以蟠虺紋鼎為靈感製作的縮小複製品，值得從不同角度細看。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：銅器' + NCHAR(10) + N'年代：戰國' + NCHAR(10) + N'商品尺寸：徑 10.25 公分、高 13 公分' + NCHAR(10) + N'原作尺寸：徑 20.5 公分、高 26 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'蟠虺紋鼎 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'圓鼎，附耳微曲，圓腹，三瘦長蹄形足，帶子母口圓頂蓋，蓋上分飾三立環。圓腹中央帶一道凸弦紋，上方密布蟠虺紋，下方至足頂間亦布滿蟠虺蚊，器底無紋。器蓋中央為一蟠龍圖案，周圍另環繞兩到蟠虺紋。雙立耳側面滿飾雷紋。', 1450.00, 20, N'/media/catalog/bronze/中銅000606N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/53452?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1300000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'徑 10.25 公分、高 13 公分', '96b52adc-c6dc-e54a-e950-747f5abd8b69'),
    ('0a0d13fb-4605-b2a3-3234-2a801f2bb83d', N'COIN', N'artifact-購錢004712N000000000', N'元豐通寶－縮小複製品', N'一枚錢幣，連起的是制度與日常生活。這件「元豐通寶」縮小複製品，把龐大的時代故事收進容易細看的尺寸。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：錢幣' + NCHAR(10) + N'年代：北宋' + NCHAR(10) + N'商品尺寸：待測量' + NCHAR(10) + N'原作尺寸：待測量' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'元豐通寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'銅質。方孔圓錢，正面有楷書：「元豐通寶」四字，背面無文。', 780.00, 20, N'/media/catalog/coin/購錢004712N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/14050?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1330000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'待測量', 'cb23ac9b-848d-06e1-3ee9-7b36866d3a9a'),
    ('1427044b-3f87-2be7-3992-2b40bcc4c513', N'ENAMEL', N'artifact-故琺000883N000000000', N'銅胎畫琺瑯芙蓉紋圓盒－縮小複製品', N'琺瑯工藝把色彩、材質與火候交織在同一件作品裡。這件「銅胎畫琺瑯芙蓉紋圓盒」縮小複製品，適合近看其中豐富而有秩序的視覺層次。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：琺瑯器' + NCHAR(10) + N'年代：清 乾隆' + NCHAR(10) + N'商品尺寸：高 2.15 公分、口徑 3.25 公分' + NCHAR(10) + N'原作尺寸：高 4.3 公分、口徑 6.5 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'銅胎畫琺瑯芙蓉紋圓盒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'銅胎，扁圓盒，覆缽式蓋與器身對合而成。蓋頂中央飾一朵以俯視角度盛開之紅芙蓉，花瓣圍繞處露出一圈白色底釉；蓋面與器身以四朵紅藍顏色的折枝芙蓉飾之，間以五瓣折枝花。蓋與器身對合處，以及圈足各飾一圈白地藍色回紋。盒內施藍綠釉。盒底色白並有一藍方框雙行「乾隆年製」楷款。', 840.00, 20, N'/media/catalog/enamel/故琺000883N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/61862?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1340000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 2.15 公分、口徑 3.25 公分', '8c10be30-0c2c-f843-9c34-b443e12653e1'),
    ('23742919-dd11-064b-74a3-2e9a0b127c5d', N'COIN', N'artifact-贈錢001271N000000000', N'日本錢幣－縮小複製品', N'看錢幣，不只看名稱，也看文字、形制與時代背景。這件「日本錢幣」縮小複製品，適合作為一段歷史收藏的起點。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：錢幣' + NCHAR(10) + N'年代：日本 明治時代' + NCHAR(10) + N'商品尺寸：待測量' + NCHAR(10) + N'原作尺寸：待測量' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'日本錢幣 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'圓錢，正面楷書：「大日本明治九年」「1 SEN」；背面「一錢」「百枚換一圓」。正面中央有草葉紋飾，背面文字被圍繞在花草紋中。', 600.00, 20, N'/media/catalog/coin/贈錢001271N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/9094?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1330000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'待測量', 'dc0f1e71-9c7c-c4db-ad02-89a5cd124370'),
    ('2c662f7b-3f22-8cea-5617-2fcd3282d491', N'ENAMEL', N'artifact-故琺000968N000000000', N'銅胎掐絲琺瑯喜字三足爐－縮小複製品', N'色彩是琺瑯最直接的吸引力，工序與細節則值得再三欣賞。以銅胎掐絲琺瑯喜字三足爐為靈感製作的縮小複製品，讓空間多一抹典藏氣息。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：琺瑯器' + NCHAR(10) + N'年代：清 乾隆' + NCHAR(10) + N'商品尺寸：高 6.23 公分、口徑 5.3 公分' + NCHAR(10) + N'原作尺寸：高 12.45 公分、口徑 10.6 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'銅胎掐絲琺瑯喜字三足爐 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'鍍金圓口，深直壁微斂，作內捲式几式座，座下接四如意形足。全器為綠地，以掐絲技法於外壁飾滿各式纏枝花葉紋，其間平均飾四紅色「喜」字，字上飾金色曲線紋並帶金邊框。器底露金屬胎，雙方框內陰刻「乾隆年製」。', 810.00, 20, N'/media/catalog/enamel/故琺000968N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/61926?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1340000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 6.23 公分、口徑 5.3 公分', 'a2e3deef-e43f-d5b5-6abd-da057a566f95'),
    ('b5a83d16-9551-da12-35b1-3073b9ab65e4', N'CERAMIC', N'artifact-贈瓷000453N000000000', N'陶編鐘－縮小複製品', N'從日常器用到典藏珍品，陶瓷記錄了不同時代對生活之美的想像。這件「陶編鐘」縮小複製品，讓這段美感自然融入展示空間。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：陶瓷' + NCHAR(10) + N'年代：春秋' + NCHAR(10) + N'商品尺寸：待測量' + NCHAR(10) + N'原作尺寸：待測量' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'陶編鐘 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'陶鐘，器型仿青銅器編鐘，方鈕，鐘身有二十四枚，上下緣塗白陶衣。', 1330.00, 20, N'/media/catalog/ceramic/贈瓷000453N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/43483?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1330000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'待測量', 'd9ee3113-ed70-29ec-3019-d662b69cffb2'),
    ('ddcc2cca-a3e6-4283-ded7-320660fd0ffc', N'BRONZE', N'artifact-中銅001907N000000000', N'雲雷紋壺－縮小複製品', N'先看整體輪廓，再找製作與歲月留下的細節，銅器總能讓人多停留一會兒。這件「雲雷紋壺」縮小複製品，讓這份歷史感更貼近日常。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：銅器' + NCHAR(10) + N'年代：南宋至明' + NCHAR(10) + N'商品尺寸：通寬 15.6 公分、高 21.5 公分、口徑 8.75 公分、底徑 8.8 公分、腹深 20.5 公分、厚 0.15 公分' + NCHAR(10) + N'原作尺寸：通寬 31.2 公分、高 43.0 公分、口徑 17.5 公分、底徑 17.6 公分、腹深 41.0 公分、厚 0.3 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'雲雷紋壺 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'圓壺，鼓腹，圈足，肩上二方折耳。全器以異金屬鑲嵌雲雷紋。', 970.00, 20, N'/media/catalog/bronze/中銅001907N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/5936?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1310000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'通寬 15.6 公分、高 21.5 公分、口徑 8.75 公分、底徑 8.8 公分、腹深 20.5 公分、厚 0.15 公分', 'de515ef4-750e-1a83-9bce-5b5ec0910359'),
    ('b9de4d59-c765-ccbf-1662-321514d4b98d', N'BRONZE', N'artifact-中銅001130N000000000', N'蟠夔紋匜－縮小複製品', N'金屬與火塑成器物，歲月再替表面留下時間的痕跡。這件「蟠夔紋匜」縮小複製品，把銅器沉穩厚實的存在感帶進收藏空間。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：銅器' + NCHAR(10) + N'年代：春秋中期' + NCHAR(10) + N'商品尺寸：長 15.5 公分、寬 8.4 公分、高 8.9 公分' + NCHAR(10) + N'原作尺寸：長 31.0 公分、寬 16.8 公分、高 17.8 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'蟠夔紋匜 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'「匜」器身寬廣如水瓢，一側有流以便倒水，另一側有鋬方便持握。本器外型如一四足獸，器身口沿及腹部飾以兩排連續蟠夔紋，四夔各自踡身為四足，以躬起的身軀接於器腹側底。鋬作夔龍，張口銜住口沿，形象生動自然。敞流作獸首狀，獸口張大成流口，頗具巧思。', 1410.00, 20, N'/media/catalog/bronze/中銅001130N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/53455?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1300000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'長 15.5 公分、寬 8.4 公分、高 8.9 公分', '59e08e52-0c76-781a-d6dd-53772afa90b2'),
    ('bcb1f030-c458-1b6d-0248-34ab975850f2', N'COIN', N'artifact-購錢004740N000000000', N'紹聖元寶－縮小複製品', N'方寸之間，裝得下年代、制度與人們往來交易的痕跡。這件「紹聖元寶」縮小複製品，從一枚錢幣打開認識歷史的新角度。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：錢幣' + NCHAR(10) + N'年代：北宋' + NCHAR(10) + N'商品尺寸：待測量' + NCHAR(10) + N'原作尺寸：待測量' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'紹聖元寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'銅質。方孔圓錢，正面有楷書：「紹聖元寶」四字，背面無文。', 750.00, 20, N'/media/catalog/coin/購錢004740N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/14078?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1340000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'待測量', '525c7d30-18f1-09b3-9f94-f894cc7ea27c'),
    ('c3a54cd6-401e-7a1d-3fb6-38121325a04b', N'JADE', N'artifact-故玉004347N000000000', N'玉劍璏－縮小複製品', N'從光澤、質地到琢磨留下的細節，玉器總有值得反覆欣賞之處。玉劍璏縮小複製品，邀你用更親近的距離重新認識它。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：玉器' + NCHAR(10) + N'年代：西漢中期至東漢' + NCHAR(10) + N'商品尺寸：長 4.2 公分、寬 1.35 公分、高 0.55 公分' + NCHAR(10) + N'原作尺寸：長 8.4 公分、寬 2.7 公分、高 1.1 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'玉劍璏 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'本器為劍璏，玉質，有褐黑色沁，拋光細緻，溫潤光亮。正面上端有一獸面，獸眼及雙眉明顯，自獸面下方以相同的紋飾單元重複鋪列器身，勾勒出簡化獸身背脊，為西漢中期至東漢常見的紋飾模組。側面有呈矩形的貫穿方孔，孔內側遺留線具拉切去料所形成之平行線痕，為漢代玉器製作常用技巧。從紋飾題材風格、形制、玉質特徵與雕刻技巧來看，屬漢代作品。本器存放在院藏「紫檀雕蟠龍方盒百什件」（故雜877）中。', 1510.00, 20, N'/media/catalog/jade/故玉004347N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/71718?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1340000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'長 4.2 公分、寬 1.35 公分、高 0.55 公分', '3c0d0a91-08e3-3e74-e57d-055092d04e99'),
    ('5aeb3d8d-d199-ca29-5e47-3858ca8a53f4', N'CERAMIC', N'artifact-贈瓷000450N000000000', N'陶編鐘－縮小複製品', N'泥土經過塑形與窯火，才成為能被長久欣賞的器物。這件「陶編鐘」縮小複製品，把陶瓷溫雅耐看的氣質帶到眼前。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：陶瓷' + NCHAR(10) + N'年代：春秋' + NCHAR(10) + N'商品尺寸：待測量' + NCHAR(10) + N'原作尺寸：待測量' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'陶編鐘 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'陶鐘，器型仿青銅器編鐘，方鈕，鐘身有二十四枚，上下緣塗白陶衣，鉦部及鼓部有白陶衣紋飾，已漫渙不清，部分可能是動物類紋飾。', 1200.00, 20, N'/media/catalog/ceramic/贈瓷000450N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/43480?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1330000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'待測量', '68b48d9f-f586-883a-8aae-a913a4557efa'),
    ('ad051bc2-0764-c79f-8220-38c672d97586', N'COIN', N'artifact-購錢004741N000000000', N'熙寧元寶－縮小複製品', N'一枚錢幣，連起的是制度與日常生活。這件「熙寧元寶」縮小複製品，把龐大的時代故事收進容易細看的尺寸。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：錢幣' + NCHAR(10) + N'年代：北宋' + NCHAR(10) + N'商品尺寸：待測量' + NCHAR(10) + N'原作尺寸：待測量' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'熙寧元寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'銅質。方孔圓錢，正面有篆書：「熙寧元寶」四字，背面無文。', 660.00, 20, N'/media/catalog/coin/購錢004741N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/14079?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1340000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'待測量', '9bfaadd1-12b4-bbff-00b0-fa0d90b800ea'),
    ('7635761a-060d-57b5-eaea-39aadb36adf2', N'JADE', N'artifact-故玉005773N000000000', N'玉圓盒－縮小複製品', N'一件玉器，可以寄託品味，也能收藏一段時代記憶。以玉圓盒為靈感製作的縮小複製品，為展示空間添上一份沉靜氣質。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：玉器' + NCHAR(10) + N'年代：南宋至明' + NCHAR(10) + N'商品尺寸：高 1.45 公分、徑 1.95 公分' + NCHAR(10) + N'原作尺寸：高 2.9 公分、徑 3.9 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'玉圓盒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'玉質，器蓋帶大塊黑斑，器身有絲狀褐色玉璺。小圓盒，有蓋，直壁，近底部內收，無圈足。全器光素無紋，突顯了玉料原有的色澤與紋路，打磨不甚細膩，顯露出厚實古樸的味道，為明代玉器的特徵之一。尺寸小巧，現儲於多寶格中。', 1050.00, 20, N'/media/catalog/jade/故玉005773N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/71683?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 1.45 公分、徑 1.95 公分', 'cdffa0b9-5e02-1214-2f24-34017a42bc4f'),
    ('aecc31a6-81cb-b31c-7413-3a7c498fa9ff', N'COIN', N'artifact-購錢005404N000000000', N'元符通寶－縮小複製品', N'一枚錢幣，連起的是制度與日常生活。這件「元符通寶」縮小複製品，把龐大的時代故事收進容易細看的尺寸。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：錢幣' + NCHAR(10) + N'年代：北宋' + NCHAR(10) + N'商品尺寸：待測量' + NCHAR(10) + N'原作尺寸：待測量' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'元符通寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'銅質。方孔圓錢，正面有楷書：「元符通寶」四字，背面無文。', 750.00, 20, N'/media/catalog/coin/購錢005404N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/14742?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1330000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'待測量', '860a384d-d357-3410-f914-f28e9a1ef096'),
    ('e981a3b5-6c96-d2f7-fe01-3a8e6210a946', N'CARVING', N'artifact-故雕000248N000000000', N'沉香木雕牡丹花紋瓶－縮小複製品', N'不同材料有不同個性，好的雕刻懂得順勢而為。以沉香木雕牡丹花紋瓶為靈感製作的縮小複製品，保留一份因材施藝的工藝趣味。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：雕刻' + NCHAR(10) + N'年代：清 乾隆' + NCHAR(10) + N'商品尺寸：高 14.6 公分' + NCHAR(10) + N'原作尺寸：高 29.2 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'沉香木雕牡丹花紋瓶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'以整塊沉香，取材料本身的紋理雕做而成，僅於瓶身腰部淺浮雕纏枝牡丹紋，有舊錦袱，為乾清宮所收藏，見於光緒二年（1876）《時做上等次等陳設檔》，應為乾隆時所做。', 850.00, 20, N'/media/catalog/carving/故雕000248N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/62478?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1310000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 14.6 公分', '85367e8c-b13d-1a63-1a43-aa109f479b2d'),
    ('c0a642f0-d1aa-50ef-8989-3a9f844ef329', N'LACQUER', N'artifact-故漆000448N000000000', N'葫蘆壽字蓋盒－縮小複製品', N'漆器耐看的地方，在於表面質感與製作時間共同留下的韻味。以葫蘆壽字蓋盒為靈感製作的縮小複製品，適合在近處慢慢欣賞。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：漆器' + NCHAR(10) + N'年代：清 康熙' + NCHAR(10) + N'商品尺寸：高 6.25 公分' + NCHAR(10) + N'原作尺寸：高 12.5 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'葫蘆壽字蓋盒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'蓋罐形壺盧器。直口、碩肩、收腹、底略內凹，有一圈微微隆起之矮圈足。蓋與器身以子母口接合。器肩上有一圈如意雲頭紋，其下間相綴飾蔓草紋。圈足中心有「康熙賞玩」楷書四字陽文方框款，外有四出如意紋。蓋頂周邊及蓋沿飾以連續回文，其間則環繞一圈番蓮壽字紋。整體器形、凸起之陽線紋飾與款識均為模製成型，係將兩個幼瓜分別置於形狀已預作設計且陰刻紋飾的模子中，待其長成，摘取乾燥，蓋鈕及罐底尚可見爪蒂與花臍之痕跡。器表質地緻密光滑，色澤天然古樸，器身內腔髹塗黑漆並打磨光亮，口沿處鑲飾玳瑁，全器輕盈有若脫胎漆器。', 640.00, 20, N'/media/catalog/lacquer/故漆000448N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/62084?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 6.25 公分', 'dd9c719c-4a1d-dbba-b8d3-b30061f1a66a'),
    ('d45309e6-e4e1-c61d-d56e-3ae5558cf952', N'BRONZE', N'artifact-故銅002169N000000000', N'雲紋三犧鼎－縮小複製品', N'先看整體輪廓，再找製作與歲月留下的細節，銅器總能讓人多停留一會兒。這件「雲紋三犧鼎」縮小複製品，讓這份歷史感更貼近日常。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：銅器' + NCHAR(10) + N'年代：戰國' + NCHAR(10) + N'商品尺寸：高 6.95 公分' + NCHAR(10) + N'原作尺寸：高 13.9 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'雲紋三犧鼎 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'附蓋圓鼎，蓋上飾三隻跪臥羊，子母口，雙附耳，獸足，足上部飾一獸面。蓋、腹皆飾鉤連紋，器外底有範線。', 1460.00, 20, N'/media/catalog/bronze/故銅002169N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/53481?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1310000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 6.95 公分', '6e96c5a5-a31a-aa60-9da1-e85c3b7fba46'),
    ('7561646e-d4f2-eb8d-dedf-3c67d0339d06', N'CERAMIC', N'artifact-故瓷018098N000000000', N'霽青釉碟－縮小複製品', N'泥土經過塑形與窯火，才成為能被長久欣賞的器物。這件「霽青釉碟」縮小複製品，把陶瓷溫雅耐看的氣質帶到眼前。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：陶瓷' + NCHAR(10) + N'年代：明 嘉靖' + NCHAR(10) + N'商品尺寸：口徑 3.7 公分、底徑 2.15 公分、高 0.75 公分' + NCHAR(10) + N'原作尺寸：口徑 7.4 公分、底徑 4.3 公分、高 1.5 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'霽青釉碟 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'本器為小碟，圓口外侈，弧形壁，有圈足，外壁施霽青釉。底有「大明嘉靖年製」雙圓框陰刻楷書六字款。從器身的霽青釉色和器底的「大明嘉靖年製」款識來看，應屬明嘉靖時期作品。', 870.00, 20, N'/media/catalog/ceramic/故瓷018098N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/71739?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1330000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'口徑 3.7 公分、底徑 2.15 公分、高 0.75 公分', '3b5d7c1b-09f2-9591-4db4-fe26054038df'),
    ('a6f5de53-025a-f868-d402-41e525618b20', N'CERAMIC', N'artifact-贈瓷000461N000000000', N'布紋硬陶罐－縮小複製品', N'一件陶瓷，可以從遠處看整體，也值得靠近欣賞質感。這件「布紋硬陶罐」縮小複製品，為收藏角落留下一份安定而耐看的風景。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：陶瓷' + NCHAR(10) + N'年代：戰國' + NCHAR(10) + N'商品尺寸：高 4.5 公分' + NCHAR(10) + N'原作尺寸：高 9.0 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'布紋硬陶罐 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'罐，斂口，豐肩，肩部兩側各有一對小貫耳，圓腹，平底。本罐屬印紋硬陶，硬陶是一種介於陶器與瓷器之間的品種，以硬度高、黏性強胎土，經過較高（約攝氏1100度）的溫度燒成；器表紋飾是於胎體製成後，再以模具拍印上去，母題多為幾何、繩紋、布紋、方格紋等紋樣，本件為布紋，為戰國時代常用的紋飾之一。', 1250.00, 20, N'/media/catalog/ceramic/贈瓷000461N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/43491?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1320000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 4.5 公分', '1f249f55-4dd0-86ec-24b5-c8b5782fec49'),
    ('c6ee7071-42a7-83ce-06cd-426ddbc7a6b0', N'CARVING', N'artifact-贈雕000134N000000000', N'骨雕填彩雲氣紋柄－縮小複製品', N'從一塊材料到一件作品，中間藏著工匠無數次判斷。這件「骨雕填彩雲氣紋柄」縮小複製品，把這份手藝凝聚成耐看的收藏。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：雕刻' + NCHAR(10) + N'年代：西漢' + NCHAR(10) + N'商品尺寸：高 2.15 公分' + NCHAR(10) + N'原作尺寸：高 4.3 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'骨雕填彩雲氣紋柄 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'此器取一段骨磨製而成，一端平齊，一端略磨圓，近磨圓之端相對面各穿一孔。器表陰刻連續雲氣紋，陰線勾邊，內刻短陰線填補空間，平齊的一端邊緣飾以火燄式紋飾；勾輪廓之陰線內填黑彩，餘填紅彩。器呈暗綠色。此器紋飾與西漢漆器上的雲氣紋類似，或即為西漢之物。', 1200.00, 20, N'/media/catalog/carving/贈雕000134N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/45363?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1320000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 2.15 公分', 'd92fd266-dd0f-9b6f-0514-2a9329458407'),
    ('425cd869-ca0a-f56f-1807-428c75907d5b', N'BRONZE', N'artifact-故銅002425N000000000', N'素觶－縮小複製品', N'先看整體輪廓，再找製作與歲月留下的細節，銅器總能讓人多停留一會兒。這件「素觶」縮小複製品，讓這份歷史感更貼近日常。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：銅器' + NCHAR(10) + N'年代：西周早期' + NCHAR(10) + N'商品尺寸：高 6.1 公分、口徑長 3.45 公分、寬 3 公分' + NCHAR(10) + N'原作尺寸：高 12.2 公分、口徑長 6.9 公分、寬 6.0 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'素觶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'侈口，束頸，垂腹，圜底，圈足外撇，近底處起淺臺。器表素面無紋，局部施綠色琉璃狀假鏽。清宮配有木座，臺面篆書「乾隆御賞」，底部楷字「周素觶九」。', 1390.00, 20, N'/media/catalog/bronze/故銅002425N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/62141?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1300000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 6.1 公分、口徑長 3.45 公分、寬 3 公分', '5ecba0ad-5c9f-cbc8-b48b-22b894ad8d96'),
    ('de984c77-97d1-3822-25c2-439a4f301641', N'LACQUER', N'artifact-故漆000533N000000000', N'剔紅花卉圓盒－縮小複製品', N'光影落在漆面上，每個角度都有不同感受。這件「剔紅花卉圓盒」縮小複製品延續漆器含蓄而精緻的魅力，為展示空間添上一份古雅。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：漆器' + NCHAR(10) + N'年代：明 永樂' + NCHAR(10) + N'商品尺寸：高 3.5 公分、徑 10.75 公分' + NCHAR(10) + N'原作尺寸：高 7.0 公分、徑 21.5 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'剔紅花卉圓盒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'圓盒尺寸大，盒面三朵茶花平均居三角，花作側姿，花心微露，瓣緣猶如荷葉邊般摺飾，花形嫵媚，花瓣刻劃細膩，凹凸起伏，纖嫩可搯，技巧高超。盒面的構圖與佈局與圖版故漆557除了左右相反和尺寸略異之外，不論葉子的翻轉或花苞的大小，幾乎完全一模一樣，說明工匠以同一樣稿剔刻紋飾的精準度，反映明永樂官營手工業嚴謹而整齊的優良水準。盒內清宮原存放九件各式雕漆堆彩果實形小盒，小盒以小卡榫上下相扣合。漆層薄，做果實形，外雕錦地，其上以漆灰堆出花、葉或藤蔓，再以漆繪色，盒內飾金漆，精巧可愛。', 720.00, 20, N'/media/catalog/lacquer/故漆000533N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/18404?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 3.5 公分、徑 10.75 公分', '437f45ab-f3a8-8f49-d481-1f40fc2e7f48'),
    ('5853fd2f-e213-ffbf-9a73-4551a3f468b1', N'PAINTING', N'artifact-故畫00193700000', N'元趙孟頫觀泉圖　軸－縮小複製品', N'畫面不只記錄所見，也保存創作者觀看世界的方式。這件「元趙孟頫觀泉圖　軸」縮小複製品，邀你把這份想像帶進自己的空間。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：繪畫' + NCHAR(10) + N'年代：元武宗至大二年（1309）' + NCHAR(10) + N'商品尺寸：26.95 × 12.4 公分' + NCHAR(10) + N'原作尺寸：53.9 × 24.8 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'元趙孟頫觀泉圖　軸 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'趙孟頫（西元一二五四—一三二二年），字子昂，號松雪道人。本宋宗室，宋亡仕元，至翰林學士承旨，封魏國公，諡文敏。詩文清遠，工書善畫。所倡書法入畫觀念，影響後世甚鉅。' + NCHAR(13) + NCHAR(10) + NCHAR(13) + NCHAR(10) + N'青壁雙起，蒼松夾峙，半為雲掩，瀑水自石壁間出，數折而下，士人抱拳聽泉，狀甚悠閒。此圖筆法高逸，青綠設色亦極淳厚典雅，以明文徵明、仇英風格之筆墨，作此頗富趙氏青綠山水韻味之作品。', 840.00, 20, N'/media/catalog/painting/故畫00193700000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/1243?dep=P', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'26.95 × 12.4 公分', '60d54af1-2a63-9c3b-062a-49fe79e56dbc'),
    ('d2b15449-35fd-d629-114a-467451eb94c6', N'LACQUER', N'artifact-故漆000394N000000000', N'剔紅石榴式盒－縮小複製品', N'一道漆、一段等待，漆器的深度來自層層累積的工序。這件「剔紅石榴式盒」縮小複製品，把這份沉靜而講究的工藝氣質帶進日常。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：漆器' + NCHAR(10) + N'年代：清 乾隆' + NCHAR(10) + N'商品尺寸：長 6.7 公分、寬 5.65 公分、高 1.55 公分' + NCHAR(10) + N'原作尺寸：長 13.4 公分、寬 11.3 公分、高 3.1 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'剔紅石榴式盒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'器內作黑漆，器底髹紅漆。以石榴為造型，上側另加一個瓜形，襯以兩三葉片，造型巧妙。側面飾折枝石榴，兼具寫實與裝飾的美感。瓜形作雙錢形錦地，石榴左側開裂，邊緣灰漆斜現，露出粒粒分明的果實，石榴作龜形花式錦地，下側一燕回首，內容豐富。運用不同的錦地製造不同的質感，猶如精緻的絲綢織品。物象描寫精到細膩，是乾隆朝中的佳作。', 830.00, 20, N'/media/catalog/lacquer/故漆000394N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/62063?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'長 6.7 公分、寬 5.65 公分、高 1.55 公分', '6b25c928-d9a3-7eaf-5314-322c16885ebc'),
    ('a71337e9-4979-2c13-7f37-48f3bdfbaccd', N'PAINTING', N'artifact-故畫00354700012', N'名人畫扇 (甲)　冊　明陳嘉言畫花鳥－縮小複製品', N'畫面不只記錄所見，也保存創作者觀看世界的方式。這件「名人畫扇 (甲)　冊　明陳嘉言畫花鳥」縮小複製品，邀你把這份想像帶進自己的空間。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：繪畫' + NCHAR(10) + N'年代：明神宗萬曆十一年（1583）' + NCHAR(10) + N'商品尺寸：8.3 × 25.15 公分' + NCHAR(10) + N'原作尺寸：16.6 × 50.3 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'名人畫扇 (甲)　冊　明陳嘉言畫花鳥 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'陳嘉言，字孔彰，浙江嘉興人，生在世宗嘉靖十八（公元一五三九）年，死年不詳，光宗天啟三（公元一六二三）年尚在世，時年八十五歲。擅長花鳥畫。　本幅扇面，是他四十四歲壯年時的作品，畫淺水沙渚，一片迷濛，河傍老梅一棵，配上磐石雜花作伴，山茶水仙，各各含苞吐艷，引得兩隻喜鵲也流連不去，景物都不藉顏彩，而用水墨一一勾畫出，粗細有致的筆劃，遠近層次分明的墨色，使得畫中的情景形色活現眼前，予人感受就彷彿是一幅色調鮮艷的彩色畫一樣。', 650.00, 20, N'/media/catalog/painting/故畫00354700012/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/15459?dep=P', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'8.3 × 25.15 公分', 'ce043ec4-cedf-16df-ca6a-32c154c04efc'),
    ('b0dca5a9-54df-f23f-aeff-49de055f88b0', N'ENAMEL', N'artifact-故琺000940N000000000', N'銅胎畫琺瑯花鳥圖梅瓶－縮小複製品', N'色彩是琺瑯最直接的吸引力，工序與細節則值得再三欣賞。以銅胎畫琺瑯花鳥圖梅瓶為靈感製作的縮小複製品，讓空間多一抹典藏氣息。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：琺瑯器' + NCHAR(10) + N'年代：清 乾隆' + NCHAR(10) + N'商品尺寸：高 4.3 公分、口徑 1 公分' + NCHAR(10) + N'原作尺寸：高 8.6 公分、口徑 2.0 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'銅胎畫琺瑯花鳥圖梅瓶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'銅胎，微侈口，短頸，斜肩，腹上豐下斂，平底。以畫琺瑯為飾，全器淺綠地，口沿繪朵花紋，肩部繪如意雲紋，腹部前後分列二卵形開光，以花葉紋框邊，一面內繪白地牡丹喜鵲圖，意謂歡喜富貴；一面繪製立於壽石的授帶鳥與牡丹，意喻富貴長壽。開光隙地滿繪折枝四季花卉紋。口緣及足底露胎鍍金，底為白地，有紅書「乾隆年製」四字雙行楷書雙方框款。', 950.00, 20, N'/media/catalog/enamel/故琺000940N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/61901?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1340000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 4.3 公分、口徑 1 公分', '017b94aa-59dd-022b-0f33-6a5230aa9c20'),
    ('a2375bc4-6b77-309d-71bf-4a21e8957b86', N'CARVING', N'artifact-贈雕000099N000000000', N'骨雕飾件－縮小複製品', N'雕刻值得從多個角度觀看，輪廓、轉折與細部會逐一展開。這件「骨雕飾件」縮小複製品，適合擺在能讓人停下腳步的位置。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：雕刻' + NCHAR(10) + N'年代：東周至漢' + NCHAR(10) + N'商品尺寸：長 7.6-4.1 公分、寬 0.5 公分、厚 0.2 公分' + NCHAR(10) + N'原作尺寸：長 7.6-8.2 公分、寬 1.0 公分、厚 0.4 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'骨雕飾件 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'以骨磨製成長條形，兩端各鑿一小孔，以供繫掛，但器形並不規整，邊稜不平直，製作樸拙。為銅鏽染成綠色。與故雕98、100-101同儲於一錦盒中。此類器形之器曾見與牙骨管珠串連成串飾，也件此類長條形器，然無穿孔，乃博箸。此件牙器並無紋飾，但是鑽孔技術已相當成熟，可能是東周或漢代之物。', 1360.00, 20, N'/media/catalog/carving/贈雕000099N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/45325?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1320000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'長 7.6-4.1 公分、寬 0.5 公分、厚 0.2 公分', '7d4d6609-e6cf-58c2-41ea-97ff44f71e9d'),
    ('2770963f-64b3-9246-6b00-4abe7c1329a6', N'PAINTING', N'artifact-中畫00008300000', N'元趙孟頫湯王徵尹圖　軸－縮小複製品', N'畫面不只記錄所見，也保存創作者觀看世界的方式。這件「元趙孟頫湯王徵尹圖　軸」縮小複製品，邀你把這份想像帶進自己的空間。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：繪畫' + NCHAR(10) + N'年代：元武宗至大二年（1309）' + NCHAR(10) + N'商品尺寸：74.35 × 36.5 公分' + NCHAR(10) + N'原作尺寸：148.7 × 73 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'元趙孟頫湯王徵尹圖　軸 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'夏朝末年，意欲討伐夏桀的商湯，苦無賢士協助。他聽說當時莘國伊尹，雖然以農耕為生，但賢名遠播，非常有才能，因此數次請人前往徵聘。伊尹最後終於答應了，並在政治和軍事上輔佐湯王，成功地建立商朝。 圖上有元代趙孟頫（一二五四－一三二二）的款識，不過由人物樹石細膩多彩的敷色方式及格套式的構圖來看，應為十七世紀的擬古之作。', 710.00, 20, N'/media/catalog/painting/中畫00008300000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/1250?dep=P', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'74.35 × 36.5 公分', 'f21cbdca-171e-7291-7982-a8f79ee06964'),
    ('cd514c1d-d54e-0898-1ba5-4c1101504a24', N'ENAMEL', N'artifact-故琺000967N000000000', N'銅胎畫琺瑯花卉紋小瓶－縮小複製品', N'琺瑯以釉料與燒製換來鮮明而細緻的層次。這件「銅胎畫琺瑯花卉紋小瓶」縮小複製品，把這份講究工序的華美濃縮成展示亮點。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：琺瑯器' + NCHAR(10) + N'年代：清 乾隆' + NCHAR(10) + N'商品尺寸：高 3.8 公分' + NCHAR(10) + N'原作尺寸：高 7.6 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'銅胎畫琺瑯花卉紋小瓶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'撇口，長頸，橢圓腹，圈足。口緣及足底露胎。器內施淺藍釉。頸部卍字錦地上飾蓮紋。肩與腹底飾一圈如意雲紋，腹部為淺黃地密佈深色點紋，並飾各式花卉，競相爭妍。圈足內為白地，帶雙方框直向款「乾隆年製」。', 930.00, 20, N'/media/catalog/enamel/故琺000967N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/61925?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1340000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 3.8 公分', '657a9dc5-9e58-1a81-0ac9-24d9159750d1'),
    ('57aa6de6-ed7c-c137-ce00-4c9db93cde50', N'LACQUER', N'artifact-贈漆000007N000000000', N'黑漆方盤－縮小複製品', N'漆器耐看的地方，在於表面質感與製作時間共同留下的韻味。以黑漆方盤為靈感製作的縮小複製品，適合在近處慢慢欣賞。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：漆器' + NCHAR(10) + N'年代：宋至元' + NCHAR(10) + N'商品尺寸：長 7.25 公分、寬 7.15 公分、高 0.95 公分' + NCHAR(10) + N'原作尺寸：長 14.5 公分、寬 14.3 公分、高 1.9 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'黑漆方盤 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'盤，矮圈足，四壁斜弧侈張，四隅微凹。通身髹黑漆，盤底矮圈足內朱漆繪出長方框，內書「□公用」，入手甚輕，器壁甚薄。', 810.00, 20, N'/media/catalog/lacquer/贈漆000007N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/104?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'長 7.25 公分、寬 7.15 公分、高 0.95 公分', 'fe4195c8-2cf1-de67-661f-c337e65a902d'),
    ('8e4f40c1-fb41-8714-39fa-4e06f61bd15d', N'CERAMIC', N'artifact-贈瓷000135N000000000', N'綠釉灶－縮小複製品', N'陶瓷的樂趣，在於輪廓、表面與燒製效果彼此呼應。以綠釉灶為靈感製作的縮小複製品，適合留在身邊慢慢發現細節。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：陶瓷' + NCHAR(10) + N'年代：東漢' + NCHAR(10) + N'商品尺寸：長 17 公分、寬 12.25 公分、高 6.5 公分' + NCHAR(10) + N'原作尺寸：長 34.0 公分、寬 24.5 公分、高 13.0 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'綠釉灶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'陶灶，灶體呈長方形，轉角硬折明顯，整器略近一長立方體，內壁露胎無釉，外壁滿釉而色近土黃，或釉中有加鉛為助融劑，故見有綠色流淌痕。方形灶門。灶上設有三個火眼（釜孔），火眼直徑一大二小，另整器外壁也只有火眼所在的壁面才有裝飾，其中火眼略弧起，並見瓢、杈等廚具，周繞方格網紋一圈。無底。內壁尚殘留泥土。', 1080.00, 20, N'/media/catalog/ceramic/贈瓷000135N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/45543?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1320000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'長 17 公分、寬 12.25 公分、高 6.5 公分', '70dc21f6-74ea-c6c0-dcac-9001cf378925'),
    ('6f755fef-59d3-4c17-6548-4e862b8191ee', N'BRONZE', N'artifact-故銅000436N000000000', N'卷草龍紋銅鎏金鏤空圓盒－縮小複製品', N'青銅器迷人的地方，在於器物本身與漫長年代共同形成的質感。以卷草龍紋銅鎏金鏤空圓盒為靈感製作的縮小複製品，值得從不同角度細看。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：銅器' + NCHAR(10) + N'年代：清 乾隆' + NCHAR(10) + N'商品尺寸：高 3.65 公分、徑 11.6 公分' + NCHAR(10) + N'原作尺寸：高 7.3 公分、徑 23.2 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'卷草龍紋銅鎏金鏤空圓盒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'銅質圓盒，口略侈，深壁，雙耳，圈足。盒蓋與盒以銅構件相接，使蓋面附連器上又可方便開闔。器壁鏤空卷草地龍紋，器蓋鏤空卷草地八寶，中心圓開光，開光中一龍正面直視。整體雕作風格甚是繁麗豪華，器內襯黃綾，用於盛裝器物時的緩衝與保護。足內刻「大清乾隆年製」雙行六字款。', 830.00, 20, N'/media/catalog/bronze/故銅000436N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/62119?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1300000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 3.65 公分、徑 11.6 公分', '1c78911d-5621-2cc8-6746-8fe7c2616947'),
    ('4653281d-3f82-f46d-1d0d-4faab5dafe22', N'PAINTING', N'artifact-故畫00145400000', N'宋朱銳春社醉歸圖　卷－縮小複製品', N'畫面不只記錄所見，也保存創作者觀看世界的方式。這件「宋朱銳春社醉歸圖　卷」縮小複製品，邀你把這份想像帶進自己的空間。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：繪畫' + NCHAR(10) + N'年代：南宋理宗紹定二年(1229)' + NCHAR(10) + N'商品尺寸：15.85 × 163.15 公分' + NCHAR(10) + N'原作尺寸：31.7 × 326.3 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'宋朱銳春社醉歸圖　卷 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'朱銳（活動於十二世紀），河北人。北宋宣和初授畫院待詔。南宋紹興年間復職，授迪功郎，賜金帶。工畫人物山水，師法王為，尤好寫騾綱、雪獵、盤車等圖。古制，每歲立春後第五個戊日為春社，是日舉行土地祭祀，以祈豐收。本卷繪祭祀畢，宴飲後的橫斜醉態，饒富奇逸之趣。沿途萬木復甦，大地欣榮，正是唐人王駕社日詩「桑柘影斜春社散，家家扶得醉人歸。」的寫照。幅末紹定二年之款，疑為後人添加，而其風格筆墨亦近於明代。', 770.00, 20, N'/media/catalog/painting/故畫00145400000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/531?dep=P', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'15.85 × 163.15 公分', 'fdaaf858-d1da-b190-1d1e-244654c7ffa4'),
    ('00f8ad9c-8b54-61fe-83f1-4fde4537aea5', N'CARVING', N'artifact-贈雕000164N000000000', N'骨雕填彩斜口筒形器－縮小複製品', N'從一塊材料到一件作品，中間藏著工匠無數次判斷。這件「骨雕填彩斜口筒形器」縮小複製品，把這份手藝凝聚成耐看的收藏。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：雕刻' + NCHAR(10) + N'年代：東漢' + NCHAR(10) + N'商品尺寸：高 3.65 公分、徑 2.05 公分' + NCHAR(10) + N'原作尺寸：高 7.3 公分、徑 4.1 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'骨雕填彩斜口筒形器 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'全器取一段骨製成，剖面呈橢圓形，一端緣平齊，一端斜削，使全器呈斜口筒形。器表陰刻細線抽象鳥紋，或填紅，或填黑。在新石器時代晚期的紅山文化中曾一再出現斜口筒形玉器，其功能未定。在內蒙古漢代墓葬中也曾出土類似的斜口筒形骨管；此件骨器，器形規整，表面又滿刻陰線紋飾，或填紅彩，或填黑色，其製作時代或許晚至東漢。', 1260.00, 20, N'/media/catalog/carving/贈雕000164N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/45524?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1320000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 3.65 公分、徑 2.05 公分', 'd552b74a-5e4e-4df2-2159-7cd6befd5972'),
    ('f6df3931-00a1-f874-be00-4fe0f58841f4', N'ENAMEL', N'artifact-故琺000890N000000000', N'掐絲琺瑯香插－縮小複製品', N'琺瑯以釉料與燒製換來鮮明而細緻的層次。這件「掐絲琺瑯香插」縮小複製品，把這份講究工序的華美濃縮成展示亮點。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：琺瑯器' + NCHAR(10) + N'年代：清 乾隆' + NCHAR(10) + N'商品尺寸：高 1 公分、口徑 5.45 公分' + NCHAR(10) + N'原作尺寸：高 2.0 公分、口徑 10.9 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'掐絲琺瑯香插 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'淺圓盤，盤心安一小瓶，以供插香。全器施以淺藍釉，內外以掐絲琺瑯裝飾西番花、卷枝花卉。以小瓶為中心，圍繞著四枚如意形開光，內飾黃地回首夔龍紋。盤沿，銅邊鍍金。小瓶，口外侈，縮頸，扁鼓腹，撇足成一花瓣底座。口、頸及底座皆鍍金，瓶身飾以藍地五瓣花紋。器底飾四枚紅色番蓮花捲草紋。底心鏨以楷款「乾隆年製」。', 860.00, 20, N'/media/catalog/enamel/故琺000890N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/61868?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1340000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 1 公分、口徑 5.45 公分', '5551ac30-d066-c638-2241-0c7aba184e70'),
    ('25c2b7a8-85a1-940d-62be-501836d5e2ad', N'ENAMEL', N'artifact-故琺000873N000000000', N'銅胎畫琺瑯西洋母子圖鼻煙壺－縮小複製品', N'琺瑯以釉料與燒製換來鮮明而細緻的層次。這件「銅胎畫琺瑯西洋母子圖鼻煙壺」縮小複製品，把這份講究工序的華美濃縮成展示亮點。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：琺瑯器' + NCHAR(10) + N'年代：清 乾隆' + NCHAR(10) + N'商品尺寸：長 2.75 公分、寬 1.9 公分、高 1.2 公分；木座長 2.75 公分、寬 1.9 公分、高 0.4 公分、連座高 1.25 公分' + NCHAR(10) + N'原作尺寸：長 5.5 公分、寬 3.8 公分、高 2.4 公分；木座長 5.5 公分、寬 3.8 公分、高 0.8 公分、連座高 2.5 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'銅胎畫琺瑯西洋母子圖鼻煙壺 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'扁瓶，雙面開光繪母子圖，側以橄欖綠為地彩繪花草紋。底有楷書「乾隆年製」黑款，銅雕花蓋及匙。', 930.00, 20, N'/media/catalog/enamel/故琺000873N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/61855?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1340000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'長 2.75 公分、寬 1.9 公分、高 1.2 公分；木座長 2.75 公分、寬 1.9 公分、高 0.4 公分、連座高 1.25 公分', '81e514c9-98d2-2007-8b81-031b1f5ced48'),
    ('f3515655-00dd-5847-ad59-50b3cb04da74', N'CARVING', N'artifact-故雕000256N000000000', N'紫檀木雕四獸筆筒－縮小複製品', N'雕刻是在材料上不斷取捨，最後留下最想表達的形貌。這件「紫檀木雕四獸筆筒」縮小複製品，讓刀工與構思成為可以近距離欣賞的焦點。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：雕刻' + NCHAR(10) + N'年代：清 乾隆' + NCHAR(10) + N'商品尺寸：長 8.5 公分、寬 5 公分' + NCHAR(10) + N'原作尺寸：長 17.0 公分、寬 10.0 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'紫檀木雕四獸筆筒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'深棕色木製方形筆筒，四面以浮雕技法分飾四靈獸。上方嵌長方形白玉，玉面陰刻填金御製詩文。四面皆於詩文後落「臣敏中」、「敬書」印。于敏中（1714-1782），乾隆二年（1737）中狀元，工書法，歷官文華殿大學士，二十五年（1760）入懋勤殿奉敕寫華嚴經寶塔，廷論多出其手。', 710.00, 20, N'/media/catalog/carving/故雕000256N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/62483?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1320000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'長 8.5 公分、寬 5 公分', '82037a20-ab06-3ea1-496e-7a360f4722e3'),
    ('8cd5e201-2e10-b6a3-76c7-5375eeeabe71', N'PAINTING', N'artifact-故畫00352600003', N'舊畫扇面　冊　明孔貞一東坡朝雲－縮小複製品', N'從構圖、線條到題材安排，書畫總有值得慢慢閱讀之處。以舊畫扇面　冊　明孔貞一東坡朝雲為靈感製作的縮小複製品，讓欣賞不必受距離限制。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：繪畫' + NCHAR(10) + N'年代：明神宗萬曆七年（1579）' + NCHAR(10) + N'商品尺寸：8.2 × 25.5 公分' + NCHAR(10) + N'原作尺寸：16.4 × 51 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'舊畫扇面　冊　明孔貞一東坡朝雲 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'孔貞一，生平待考。' + NCHAR(13) + NCHAR(10) + N'　　畫中故事，或為東坡朝雲圖。畫東坡提筆書於蕉葉上，朝雲對坐侍筆硯，一婢提水前來。梧桐高聳，石則中空露洞，芭蕉葉雜列其間，蓋庭院之一角。金箋作畫，紙性不吸水，墨色淋漓之感猶在，梧桐、芭蕉之葉尖已微枯黃，夏末陰涼之感已生。' + NCHAR(13) + NCHAR(10) + N'　　本幅選自「明舊畫扇面」冊第三開。', 670.00, 20, N'/media/catalog/painting/故畫00352600003/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/18295?dep=P', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1360000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'8.2 × 25.5 公分', 'fe1270cc-ff27-c3ed-f50a-b06e795e7070'),
    ('45f9a467-ff7c-9040-b0da-55aa5b411d0a', N'BRONZE', N'artifact-中銅000774N000000000', N'夔鳳紋壺－縮小複製品', N'先看整體輪廓，再找製作與歲月留下的細節，銅器總能讓人多停留一會兒。這件「夔鳳紋壺」縮小複製品，讓這份歷史感更貼近日常。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：銅器' + NCHAR(10) + N'年代：春秋早期' + NCHAR(10) + N'商品尺寸：通高 17.45 公分、徑 6.15 公分' + NCHAR(10) + N'原作尺寸：通高 34.9 公分、徑 12.3 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'夔鳳紋壺 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'微撇口，短頸，鼓腹，矮圈足。腹兩側帶有獸首銜環。器身腹壁飾三道寬弦紋，弦紋間滿飾夔鳳紋。', 1340.00, 20, N'/media/catalog/bronze/中銅000774N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/53454?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1300000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'通高 17.45 公分、徑 6.15 公分', '09b5b842-6027-0042-8bea-77d655613bfb'),
    ('9b16ac1b-742c-4626-9faa-55b8bc0becdd', N'COIN', N'artifact-購錢004630N000000000', N'天聖元寶－縮小複製品', N'看錢幣，不只看名稱，也看文字、形制與時代背景。這件「天聖元寶」縮小複製品，適合作為一段歷史收藏的起點。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：錢幣' + NCHAR(10) + N'年代：北宋' + NCHAR(10) + N'商品尺寸：待測量' + NCHAR(10) + N'原作尺寸：待測量' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'天聖元寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'銅質。方孔圓錢，正面有楷書：「天聖元寶」四字，背面無文。', 660.00, 20, N'/media/catalog/coin/購錢004630N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/13968?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1330000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'待測量', '389435f5-4036-0d8a-6d37-76e9a1797922'),
    ('af00d2aa-2c73-fb97-82d8-58cc10a8efd2', N'JADE', N'artifact-故玉004343N000000000', N'玉龍佩－縮小複製品', N'一件玉器，可以寄託品味，也能收藏一段時代記憶。以玉龍佩為靈感製作的縮小複製品，為展示空間添上一份沉靜氣質。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：玉器' + NCHAR(10) + N'年代：戰國中期' + NCHAR(10) + N'商品尺寸：長 3.75 公分、寬 2.15 公分、厚 0.25 公分' + NCHAR(10) + N'原作尺寸：長 7.5 公分、寬 4.3 公分、厚 0.5 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'玉龍佩 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'本器為龍形佩，玉質，帶深褐色沁。器身彎曲呈Ｓ形，器表淺浮雕穀紋，龍尾分歧勾轉處陰刻似葉紋。從以上造形及紋飾特徵來看，屬戰國中期作品。本器存放在院藏「紫檀雕蟠龍方盒百什件」（故雜877）中。', 1410.00, 20, N'/media/catalog/jade/故玉004343N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/71714?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'長 3.75 公分、寬 2.15 公分、厚 0.25 公分', '9796d428-a0ec-ea63-b96f-14f6590ba79c'),
    ('4130a3ac-a866-abbe-d50b-5902baac1d93', N'JADE', N'artifact-故玉004367N000000000', N'玉劍璏－縮小複製品', N'欣賞玉器，不只看材質，也看工匠如何順著天然質地雕琢成形。玉劍璏縮小複製品，適合放在近處慢慢看、慢慢品味。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：玉器' + NCHAR(10) + N'年代：西漢中期至東漢' + NCHAR(10) + N'商品尺寸：長 3.25 公分、寬 1.35 公分、高 0.7 公分；木座長 3.45 公分、寬 1.65 公分、高 0.45 公分、連座高 0.8 公分' + NCHAR(10) + N'原作尺寸：長 6.5 公分、寬 2.7 公分、高 1.4 公分；木座長 6.9 公分、寬 3.3 公分、高 0.9 公分、連座高 1.6 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'玉劍璏 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'本器為劍璏，玉質，帶褐色沁，拋光細緻，溫潤光亮。正面上端有一獸面，獸眼及雙眉明顯，自獸面下方以相同的紋飾單元重複鋪列器身，勾勒出簡化獸身背脊，為西漢中期至東漢常見的紋飾模組。側面有呈矩形的貫穿方孔，孔內側遺留線具拉切去料所形成之平行線痕，為漢代玉器製作常用技巧。從紋飾題材風格、形制、玉質特徵與雕刻技巧來看，屬漢代作品。本器帶紫檀木座，存放在院藏「紫檀雕蟠龍方盒百什件」（故雜877）中。', 1420.00, 20, N'/media/catalog/jade/故玉004367N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/71734?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1340000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'長 3.25 公分、寬 1.35 公分、高 0.7 公分；木座長 3.45 公分、寬 1.65 公分、高 0.45 公分、連座高 0.8 公分', '33531918-0b9a-f282-b19d-d4182d1ef80b'),
    ('bfe5002f-c4df-5b6d-2fdc-59f448efbb0f', N'CARVING', N'artifact-故雕000267N000000000', N'葫蘆壽星鼻煙壺－縮小複製品', N'雕刻是在材料上不斷取捨，最後留下最想表達的形貌。這件「葫蘆壽星鼻煙壺」縮小複製品，讓刀工與構思成為可以近距離欣賞的焦點。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：雕刻' + NCHAR(10) + N'年代：清 乾隆' + NCHAR(10) + N'商品尺寸：長 2.65 公分、寬 1.3 公分、高 4 公分' + NCHAR(10) + N'原作尺寸：長 5.3 公分、寬 2.6 公分、高 8.0 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'葫蘆壽星鼻煙壺 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'口沿鑲木，兩腹陽紋壽星、仙鶴、靈芝、祥雲等，兩肩為獸首銜環紋，上下分列「乾、隆、賞、玩」四字，附長方形木圈足。帶雕雙獅木蓋與牙匙。', 730.00, 20, N'/media/catalog/carving/故雕000267N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/62494?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1320000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'長 2.65 公分、寬 1.3 公分、高 4 公分', '5bca49a1-1039-06a9-4ab2-c63872eecc5e'),
    ('38cb0706-a4f2-ea99-1624-5b5f5b792c47', N'LACQUER', N'artifact-故漆000477N000000000', N'剔黃山海雲龍紋圓盤－縮小複製品', N'漆藝講究耐心，也讓器物擁有難以取代的深沉質感。這件「剔黃山海雲龍紋圓盤」縮小複製品，是一件越看越能發現味道的收藏。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：漆器' + NCHAR(10) + N'年代：明 萬曆' + NCHAR(10) + N'商品尺寸：高 1.45 公分、徑 10.5 公分、足徑 8.6 公分' + NCHAR(10) + N'原作尺寸：高 2.9 公分、徑 21.0 公分、足徑 17.2 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'剔黃山海雲龍紋圓盤 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'圓盤，圓沿，圈足，足內髹紅漆，盤內外紅地剔黃。萬曆乙未年為萬曆廿三年，西元1595年。盤心下段，紅地刻波浪紋錦地，一片起伏的海水，前方矗立三座山峰，山石旁海水洶湧，激起浪花。盤心上段，紅漆米字形方格錦地一龍從天而降，龍身翻騰，身軀瘦長飛轉，龍首側視，前一火球，正居盤心，張口吐舌，四足外揚，龍鰭飛揚，形貌強悍威嚴。行龍外，間飾如意雲紋。漆層薄，漆色潤，佈局均衡，構圖穩定，刀法熟練俐落，陰刻線條拙重，黃、紅相映，莊嚴穩重而華麗，是官方雕漆的典型。', 830.00, 20, N'/media/catalog/lacquer/故漆000477N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/17572?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 1.45 公分、徑 10.5 公分、足徑 8.6 公分', '7fd52260-9e09-6ec3-0821-4be8df9d6b7d'),
    ('18a04ca0-1c82-29cb-654e-5b9dd5ed937c', N'CERAMIC', N'artifact-購瓷000086N000000000', N'琉璃珠－縮小複製品', N'從日常器用到典藏珍品，陶瓷記錄了不同時代對生活之美的想像。這件「琉璃珠」縮小複製品，讓這段美感自然融入展示空間。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：陶瓷' + NCHAR(10) + N'年代：戰國' + NCHAR(10) + N'商品尺寸：高 0.8 公分、外徑 0.8 公分、孔徑 0.25 公分' + NCHAR(10) + N'原作尺寸：高 1.6 公分、外徑 1.6 公分、孔徑 0.5 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'琉璃珠 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'綠色半透明球形珠，胎體薄，中有穿孔，外壁嵌同色澤半透明眼珠狀紋飾，外框呈米黃色。湖南長沙瀏城橋戰國墓曾出土類似綠地三十眼琉璃珠。', 1290.00, 20, N'/media/catalog/ceramic/購瓷000086N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/42967?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1320000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 0.8 公分、外徑 0.8 公分、孔徑 0.25 公分', 'eab8c5a9-2bdf-ce63-ef4d-0ba95bc42043'),
    ('652a9875-25d6-c7be-4ed2-5c36bec88b5a', N'COIN', N'artifact-購錢004636N000000000', N'熙寧元寶－縮小複製品', N'方寸之間，裝得下年代、制度與人們往來交易的痕跡。這件「熙寧元寶」縮小複製品，從一枚錢幣打開認識歷史的新角度。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：錢幣' + NCHAR(10) + N'年代：北宋' + NCHAR(10) + N'商品尺寸：待測量' + NCHAR(10) + N'原作尺寸：待測量' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'熙寧元寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'銅質。方孔圓錢，正面有楷書：「熙寧元寶」四字，背面無文。', 660.00, 20, N'/media/catalog/coin/購錢004636N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/13974?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1340000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'待測量', 'e6068a06-411c-1c1b-713a-c28ae59b2e78'),
    ('326c3ec7-24f9-6079-a70b-5cbff7ce644d', N'PAINTING', N'artifact-故畫00195300000', N'元管道昇竹溪攬勝　軸－縮小複製品', N'畫面不只記錄所見，也保存創作者觀看世界的方式。這件「元管道昇竹溪攬勝　軸」縮小複製品，邀你把這份想像帶進自己的空間。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：繪畫' + NCHAR(10) + N'年代：元武宗至大二年（1309）' + NCHAR(10) + N'商品尺寸：28.6 × 13.75 公分' + NCHAR(10) + N'原作尺寸：57.2 × 27.5 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'元管道昇竹溪攬勝　軸 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'管道昇（西元一二六二－一三一九年），吳興人。字仲姬，趙孟頫妻。延祐四年（西元一三一七年）封魏國夫人。翰墨辭章不學而能，篤信佛法，書牘行楷與乃夫趙孟頫幾不可辨異同，為我國書畫史上著名女性作家之一。' + NCHAR(13) + NCHAR(10) + NCHAR(13) + NCHAR(10) + N'本幅舊傳為管氏所作，畫山巒起伏，緣溪瓦屋數椽，叢竹錯落其間，溪邊泊舟，橋上行人，以水墨細緻之筆調，寫寧靜之村景，真得小橋、流水、人家之詩意。', 770.00, 20, N'/media/catalog/painting/故畫00195300000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/733?dep=P', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'28.6 × 13.75 公分', '432ef746-9d59-d7cd-a1c8-11a9fa8a6737'),
    ('a23d82ff-70a6-1a2f-faf3-5d39e559ff35', N'ENAMEL', N'artifact-故琺000889N000000000', N'掐絲琺瑯香插－縮小複製品', N'琺瑯工藝把色彩、材質與火候交織在同一件作品裡。這件「掐絲琺瑯香插」縮小複製品，適合近看其中豐富而有秩序的視覺層次。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：琺瑯器' + NCHAR(10) + N'年代：清 乾隆' + NCHAR(10) + N'商品尺寸：高 1.05 公分、口徑 5.4 公分' + NCHAR(10) + N'原作尺寸：高 2.1 公分、口徑 10.8 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'掐絲琺瑯香插 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'淺圓盤，盤心安一小瓶，以供插香。全器施以淺藍釉，內外以掐絲琺瑯裝飾西番花、卷枝花紋。以小瓶為中心，圍繞著四枚如意形開光，內飾黃地回首夔龍紋。盤沿，銅邊鍍金。小瓶，口外侈，縮頸，扁鼓腹，撇足成一花瓣底座。口、頸及底座皆鍍金，瓶身飾以藍地五瓣花草紋。器底飾四枚紅色番蓮花卷草紋。底心鏨以楷書款「乾隆年製」。', 790.00, 20, N'/media/catalog/enamel/故琺000889N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/61867?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1340000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 1.05 公分、口徑 5.4 公分', 'b81ec7d4-7f4f-a51d-bf0e-1f0ce486efb2'),
    ('f86b5952-39d7-6f4d-6e56-5d8bbac3533c', N'CARVING', N'artifact-贈雕000117N000000000', N'牙雕小豚－縮小複製品', N'不同材料有不同個性，好的雕刻懂得順勢而為。以牙雕小豚為靈感製作的縮小複製品，保留一份因材施藝的工藝趣味。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：雕刻' + NCHAR(10) + N'年代：戰國至六朝' + NCHAR(10) + N'商品尺寸：長 0.95 公分、高 0.6 公分' + NCHAR(10) + N'原作尺寸：長 1.9 公分、高 1.2 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'牙雕小豚 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'立雕小豚，體小而雕工圓熟，動物身軀與面龐較寫實，器呈黃色。類似雕工簡拙的小動物，從漢墓至六朝墓葬中皆曾見，其質材不限於牙或骨。從器物的雕刻風格看來，或可早至戰國。', 1210.00, 20, N'/media/catalog/carving/贈雕000117N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/45346?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1310000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'長 0.95 公分、高 0.6 公分', 'fd6c5acc-ebb7-b46a-7edf-c9fe33558ff1'),
    ('e7800535-f509-e16f-8b40-5e4ae460b9c7', N'PAINTING', N'artifact-故畫00098800000', N'宋王詵瀛山圖　卷－縮小複製品', N'畫面不只記錄所見，也保存創作者觀看世界的方式。這件「宋王詵瀛山圖　卷」縮小複製品，邀你把這份想像帶進自己的空間。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：繪畫' + NCHAR(10) + N'年代：北宋英宗治平元年（1064）' + NCHAR(10) + N'商品尺寸：12.25 × 72.55 公分' + NCHAR(10) + N'原作尺寸：24.5 × 145.1 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'宋王詵瀛山圖　卷 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'王詵（約一０四八—一一二二），字晉卿。幼善讀書，長能屬文，博雅該洽，以至奕棋，無不造妙。畫山水略師李成，著色略師李思訓，而能自成一格。畫竹師文湖州。本幅畫峻嶺迴溪，山村茅茨，遠水平沙，數艇隱隱。圖後一遠峰山題款云：「保寧賜第王晉卿瀛山既覺，因圖夢中所見。甲辰春四月，夢遊者。」細審圖中絕壑層巒，俱以青綠著色，用筆工細，氣韻古雅，良為一夢中山水矣。', 860.00, 20, N'/media/catalog/painting/故畫00098800000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/14434?dep=P', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'12.25 × 72.55 公分', '88ad38db-796d-2d94-5b38-933a8dd10793'),
    ('2d25fc62-b22f-28b2-0ad0-6092d93225d0', N'LACQUER', N'artifact-故漆000361N000000000', N'剔紅六瓣花式盒－縮小複製品', N'一道漆、一段等待，漆器的深度來自層層累積的工序。這件「剔紅六瓣花式盒」縮小複製品，把這份沉靜而講究的工藝氣質帶進日常。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：漆器' + NCHAR(10) + N'年代：清 乾隆' + NCHAR(10) + N'商品尺寸：徑 1.65 公分' + NCHAR(10) + N'原作尺寸：徑 3.3 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'剔紅六瓣花式盒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'剔紅小盒，色硃紅。六瓣葵花式，子母口，蓋與器約相等。蓋面雕花心與向外左旋出六枚花瓣，器身亦飾作花瓣。器裏髹黑漆，蓋內刻填金楷款「乾隆年製」。內有朵花小玉飾件一，附木座。本件收入乾隆時期製作多寶格「集瓊藻」中，據集瓊藻小冊所載原有二層七十三件，共儲於嵌飾獸骨螺甸的木箱中。', 800.00, 20, N'/media/catalog/lacquer/故漆000361N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/24256?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'徑 1.65 公分', '2ec43a92-b738-b38b-9e7d-0dc2524145c6'),
    ('6a40ab79-ae40-5458-f7cb-6114458c7950', N'PAINTING', N'artifact-故畫00150400000', N'元趙孟頫醉菊圖　卷－縮小複製品', N'遠看整體氣勢，近看筆墨細節，書畫能陪人反覆觀看。這件「元趙孟頫醉菊圖　卷」縮小複製品，為牆面或展示角落留下一段雅致風景。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：繪畫' + NCHAR(10) + N'年代：元武宗至大二年（1309）' + NCHAR(10) + N'商品尺寸：15.4 × 268 公分' + NCHAR(10) + N'原作尺寸：30.8 × 536 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'元趙孟頫醉菊圖　卷 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'白描畫陶淵明事蹟。陶淵明（西元三六五—四二七年），晉宋時期詩人、辭賦家、散文家。一名潛，字元亮。曾為州祭酒，後為彭澤令。因不能「為五斗米折腰」，棄官歸隱，躬耕自給，以詩酒自娛。晚年貧病交攻，卒後世稱靖節先生。其詩自然樸素，其人名行高潔，為文士的象徵。其嗜酒、賞菊等情狀，向為後世畫家所喜繪。卷末款趙孟頫，是元代文人畫壇領袖。本卷就筆墨來看，不類趙氏風格。', 710.00, 20, N'/media/catalog/painting/故畫00150400000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/15775?dep=P', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'15.4 × 268 公分', 'de1c1bf6-5c49-aadf-81a5-ba51eae2bd76'),
    ('03a1fc3a-6454-3033-e10b-61d31db8b824', N'LACQUER', N'artifact-故漆000373N000000000', N'剔紅雲龍紋圓盒－縮小複製品', N'光影落在漆面上，每個角度都有不同感受。這件「剔紅雲龍紋圓盒」縮小複製品延續漆器含蓄而精緻的魅力，為展示空間添上一份古雅。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：漆器' + NCHAR(10) + N'年代：明 宣德' + NCHAR(10) + N'商品尺寸：高 3.75 公分、口徑 11.8 公分、足徑 11.1 公分' + NCHAR(10) + N'原作尺寸：高 7.5 公分、口徑 23.6 公分、足徑 22.2 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'剔紅雲龍紋圓盒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'蔗段式圓盒，盒側刻雲紋，盒面刻雲龍紋。五爪行龍，縱身雲間，側身昂首，身形壯碩，姿態矯健，鬃毛風揚，黑漆點睛，神采奕奕，具有明顯的時代特徵。雲紋佈局滿，排列充滿秩序感。雲朵作如意形，內有豆芽形的雲頭三角排列，兩側各一拉長的雲尾，組成一雲紋的單元，也是永宣時期雲紋的典型樣式。龍紋作為皇帝的象徵，從元代就已開始，明代確立，皇帝的龍袍上就繡著五爪龍紋，並三令五申禁止民間使用，反映明代中央集權的政治體制。 明代內廷用器由官方監造，工匠需至京城服役，嘉興府志記載剔紅名匠張德剛、包亮，曾受召擔任營繕所副所長。這件剔紅雕漆以黃漆為地，髹漆厚實，龍紋與雲紋分佈的層次上下分明，顯示製漆工法的嚴謹；用刀圓熟，刻線流暢，隨物象變化得宜，漆面打磨講究，展現溫潤鮮活的漆質，可見剔雕工藝的精緻細膩，無疑是明代官方作器的最佳例證。', 910.00, 20, N'/media/catalog/lacquer/故漆000373N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/17716?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 3.75 公分、口徑 11.8 公分、足徑 11.1 公分', '2dac8dda-46b9-28ab-c144-3c84cb969da4'),
    ('90116bba-2750-e395-aa36-6240cbd50a7d', N'PAINTING', N'artifact-故畫003770N000000000', N'畫花卉 冊－縮小複製品', N'遠看整體氣勢，近看筆墨細節，書畫能陪人反覆觀看。這件「畫花卉 冊」縮小複製品，為牆面或展示角落留下一段雅致風景。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：繪畫' + NCHAR(10) + N'年代：清 乾隆' + NCHAR(10) + N'商品尺寸：長 10.8 公分、寬 6 公分' + NCHAR(10) + N'原作尺寸：長 21.6 公分、寬 12.0 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'畫花卉 冊 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'紙本冊頁，梵夾式，八開，前後空白各二開。內繪設色芙蓉、牡丹、牽牛、菊花等各式花卉。末款署「臣汪承霈恭繪」，並鈐「臣」、「霈」白文雙連章。汪為清乾隆時舉人，以繪人物、花卉見長。本件與十件玉飾共收於一雕波濤百獸剔紅漆盒。', 610.00, 20, N'/media/catalog/painting/故畫003770N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/50353?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1360000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'長 10.8 公分、寬 6 公分', 'da539ef7-9b85-a1b3-efcb-0566138fe085'),
    ('75eaac19-a4a1-92ff-86dd-6380c593d234', N'LACQUER', N'artifact-故漆000358N000000000', N'漆琴－縮小複製品', N'漆藝講究耐心，也讓器物擁有難以取代的深沉質感。這件「漆琴」縮小複製品，是一件越看越能發現味道的收藏。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：漆器' + NCHAR(10) + N'年代：清 乾隆' + NCHAR(10) + N'商品尺寸：長 10.5 公分、寬 1.5 公分、高 1.05 公分' + NCHAR(10) + N'原作尺寸：長 21.0 公分、寬 3.0 公分、高 2.1 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'漆琴 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'仲尼式琴，玉軫，玉足，黑漆面微有傷。琴內納音處中央凸起，龍池、鳳沼皆長方形，造形簡單素雅。琴底項部刻「乾隆年製」款，內填白料。', 730.00, 20, N'/media/catalog/lacquer/故漆000358N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/24254?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'長 10.5 公分、寬 1.5 公分、高 1.05 公分', '93aa4889-2d7c-2d28-a7b2-bbacf5f536f8'),
    ('8411ceb4-2151-2a6d-a524-64186dbfe1a1', N'BRONZE', N'artifact-故銅002538N000000000', N'銅夔龍奩－縮小複製品', N'有些文物不必鋪陳太多，安靜擺著就很有分量。這件「銅夔龍奩」縮小複製品延續銅器特有的沉著氣質，適合成為展示中的視覺焦點。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：銅器' + NCHAR(10) + N'年代：西周' + NCHAR(10) + N'商品尺寸：高 9.4 公分、徑 5.2 公分' + NCHAR(10) + N'原作尺寸：高 18.8 公分、徑 10.4 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'銅夔龍奩 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'明清時流行將殘破或斷失的銅器加以修補，成為完整的另一件器物。這件夔龍奩即是此背景之中，將西周馬車上的青銅配件，補鑄器身及器底後，成為筒狀的容器。', 1380.00, 20, N'/media/catalog/bronze/故銅002538N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/62227?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1300000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 9.4 公分、徑 5.2 公分', 'a7a789f5-1e12-6773-c616-2ba2b121a133'),
    ('792d118f-34ea-4c3b-3576-6446a278b1c0', N'COIN', N'artifact-購錢004793N000000000', N'元符通寶－縮小複製品', N'錢幣曾在人群之間流轉，如今也成為辨認時代的重要線索。以元符通寶為靈感製作的縮小複製品，小巧卻很有故事。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：錢幣' + NCHAR(10) + N'年代：北宋' + NCHAR(10) + N'商品尺寸：待測量' + NCHAR(10) + N'原作尺寸：待測量' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'元符通寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'銅質。方孔圓錢，正面有楷書：「元符通寶」四字，背面無文。', 850.00, 20, N'/media/catalog/coin/購錢004793N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/14131?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1330000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'待測量', 'bbbd5a22-69e2-1728-a5b9-069760a1cbcb'),
    ('f1a7f8d9-a675-445b-bb92-64c1d7c15ec1', N'COIN', N'artifact-購錢005425N000000000', N'熙寧元寶－縮小複製品', N'看錢幣，不只看名稱，也看文字、形制與時代背景。這件「熙寧元寶」縮小複製品，適合作為一段歷史收藏的起點。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：錢幣' + NCHAR(10) + N'年代：北宋' + NCHAR(10) + N'商品尺寸：待測量' + NCHAR(10) + N'原作尺寸：待測量' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'熙寧元寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'銅質。方孔圓錢，正面有楷書：「熙寧元寶」四字，背面無文。', 840.00, 20, N'/media/catalog/coin/購錢005425N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/14763?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1340000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'待測量', 'f5911751-ac21-670c-2891-2acd6fe948e0'),
    ('3f6bce23-0ab2-b1c6-35c8-6526dbc6f76a', N'COIN', N'artifact-購錢004784N000000000', N'熙寧元寶－縮小複製品', N'看錢幣，不只看名稱，也看文字、形制與時代背景。這件「熙寧元寶」縮小複製品，適合作為一段歷史收藏的起點。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：錢幣' + NCHAR(10) + N'年代：北宋' + NCHAR(10) + N'商品尺寸：待測量' + NCHAR(10) + N'原作尺寸：待測量' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'熙寧元寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'銅質。方孔圓錢，正面有篆書：「熙寧元寶」四字，背面無文。', 630.00, 20, N'/media/catalog/coin/購錢004784N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/14122?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1340000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'待測量', '1085d366-dd54-ad5f-aab3-efc57e912551'),
    ('779de10d-a620-7100-8350-6859a9ad60c3', N'ENAMEL', N'artifact-故琺000618N000000000', N'掐絲琺瑯雙龍盤－縮小複製品', N'想讓展示空間更有亮點，又保留古典工藝的細膩感，這件「掐絲琺瑯雙龍盤」縮小複製品會是一件很有存在感的收藏。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：琺瑯器' + NCHAR(10) + N'年代：明 萬曆' + NCHAR(10) + N'商品尺寸：高 3.45 公分、徑 24.15 公分' + NCHAR(10) + N'原作尺寸：高 6.9 公分、徑 48.3 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'掐絲琺瑯雙龍盤 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'菊瓣折沿平底圈足盤，銅胎鎏金，紋飾掐絲。淺綠色盤心滿飾五色祥雲，中央有紅、黃雙龍拱衛團壽字。斜壁與盤底以淺藍色掐絲雲紋為地，前者更飾八雜寶與八吉祥，底心則有綠地填紅「大明萬曆年造」（1573-1620）雙行楷書款。琺瑯釉層薄，色彩繽紛，是晚明掐絲琺瑯之重要標準器。', 880.00, 20, N'/media/catalog/enamel/故琺000618N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/1530?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1340000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 3.45 公分、徑 24.15 公分', '851b0c60-2f89-fbae-3088-24a19feb1486'),
    ('5463c167-2256-c3dc-f4cd-6a0f29214f83', N'JADE', N'artifact-故玉006399N000000000', N'玉魚形佩－縮小複製品', N'玉石經過琢磨才成器，也在流傳中留下不同時代的眼光。玉魚形佩化為縮小複製品，讓這份溫潤含蓄的玉器之美走進日常。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：玉器' + NCHAR(10) + N'年代：商晚期至西周早期' + NCHAR(10) + N'商品尺寸：寬 4.15 公分' + NCHAR(10) + N'原作尺寸：寬 8.3 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'玉魚形佩 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'玉質，青色沁褐。魚身彎弧，輪廓簡單。於器表以陰線刻琢眼嘴、鰭尾。', 1540.00, 20, N'/media/catalog/jade/故玉006399N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/57476?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'寬 4.15 公分', '06ff6729-6120-58d9-9713-d3762a9b1809'),
    ('4a6cc432-8b62-e759-e485-6a46b61caf95', N'JADE', N'artifact-故玉006232N000000000', N'玉勒－縮小複製品', N'玉石經過琢磨才成器，也在流傳中留下不同時代的眼光。玉勒化為縮小複製品，讓這份溫潤含蓄的玉器之美走進日常。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：玉器' + NCHAR(10) + N'年代：春秋晚期' + NCHAR(10) + N'商品尺寸：玉件長 3.15 公分、寬 1.15 公分' + NCHAR(10) + N'原作尺寸：玉件長 6.3 公分、寬 2.3 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'玉勒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'玉質，青灰色，雜赭斑。全器呈不規則長方形，器面滿飾雲紋。附木座。', 1500.00, 20, N'/media/catalog/jade/故玉006232N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/57354?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'玉件長 3.15 公分、寬 1.15 公分', '78cd47da-24f4-179c-bf05-946b61ecbfbe'),
    ('cd18b5cc-6d35-61c8-5604-6aba1cdf9bc2', N'CERAMIC', N'artifact-故瓷018109N000000000', N'瓷胎粉彩玉堂富貴鼻煙壺－縮小複製品', N'陶瓷的樂趣，在於輪廓、表面與燒製效果彼此呼應。以瓷胎粉彩玉堂富貴鼻煙壺為靈感製作的縮小複製品，適合留在身邊慢慢發現細節。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：陶瓷' + NCHAR(10) + N'年代：清 乾隆' + NCHAR(10) + N'商品尺寸：高 3.3 公分、最寬 2.15 公分、厚 1 公分' + NCHAR(10) + N'原作尺寸：高 6.6 公分、最寬 4.3 公分、厚 2.0 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'瓷胎粉彩玉堂富貴鼻煙壺 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'模製扁壺兩面開光彩繪玉蘭、海棠及牡丹，象徵「玉堂富貴」，其餘白地間飾番蓮纏枝紋。帶描金彩繪瓷蓋與牙匙。底有篆書「乾隆年製」紅款。原貯於華滋堂燕喜堂中，共41個鼻煙壺貯於一楠木箱中。', 730.00, 20, N'/media/catalog/ceramic/故瓷018109N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/61003?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1320000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 3.3 公分、最寬 2.15 公分、厚 1 公分', '667cbdec-8f7d-6c11-4279-53ce6a59524b'),
    ('e2f2f9c5-f13a-d22d-0b1c-6aea1ce0b758', N'JADE', N'artifact-故玉009114N000000000', N'〈般若波羅蜜多心經〉玉版－縮小複製品', N'欣賞玉器，不只看材質，也看工匠如何順著天然質地雕琢成形。〈般若波羅蜜多心經〉玉版縮小複製品，適合放在近處慢慢看、慢慢品味。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：玉器' + NCHAR(10) + N'年代：清 乾隆' + NCHAR(10) + N'商品尺寸：長 2.9 公分、寬 2.25 公分' + NCHAR(10) + N'原作尺寸：長 5.8 公分、寬 4.5 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'〈般若波羅蜜多心經〉玉版 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'長方形玉版，一式四件（故玉9113-9116），上刻錢汝誠（1722-1779）所書〈般若波羅蜜多心經〉填金楷字。本器為玉版中的第二片，續刻「般若波羅蜜多心經」之中段經文。', 920.00, 20, N'/media/catalog/jade/故玉009114N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/60156?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1340000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'長 2.9 公分、寬 2.25 公分', 'cac8b237-af01-5c74-e477-7c8509099d10'),
    ('334571a0-f2fc-48b3-4c32-6cb29f3ea7cc', N'CARVING', N'artifact-故雕000260N000000000', N'象牙鏤雕活紋連鏈圓盒－縮小複製品', N'從一塊材料到一件作品，中間藏著工匠無數次判斷。這件「象牙鏤雕活紋連鏈圓盒」縮小複製品，把這份手藝凝聚成耐看的收藏。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：雕刻' + NCHAR(10) + N'年代：清 乾隆三年' + NCHAR(10) + N'商品尺寸：高 0.9 公分、徑 1.1 公分' + NCHAR(10) + N'原作尺寸：高 1.8 公分、徑 2.2 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'象牙鏤雕活紋連鏈圓盒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'象牙鏤雕圓盒，盒身滿雕鏤空錦地紋，蓋面活紋勾連皆可上下靈活活動。盒內底部刻有獅子滾繡球，自繡球鏤空處有長鏈與蓋內中心相連，長鏈再有三小鏈分出，分別刻有犬、母子猴、鏤空葫蘆，盒底刻有「乾隆戊午（三年，1738）季夏，小臣蕭漢振恭製。」填黑楷款，可知此件出自乾隆年間著名牙匠蕭漢振之手。顯現連鏈、活紋技巧高超且精微之處。此件象牙小圓盒原為「戧金描漆龍鳳箱」（多寶格）中的一件小珍玩。', 740.00, 20, N'/media/catalog/carving/故雕000260N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/62487?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1320000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 0.9 公分、徑 1.1 公分', 'f6e61252-8306-0d07-3d00-23907e90fd83'),
    ('2dc2940f-c664-f71e-4ca4-6d29dc9ce74a', N'JADE', N'artifact-故玉004358N000000000', N'玉獸紋韘形佩－縮小複製品', N'玉石經過琢磨才成器，也在流傳中留下不同時代的眼光。玉獸紋韘形佩化為縮小複製品，讓這份溫潤含蓄的玉器之美走進日常。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：玉器' + NCHAR(10) + N'年代：東漢' + NCHAR(10) + N'商品尺寸：長 3.7 公分、寬 2.75 公分、厚 0.3 公分' + NCHAR(10) + N'原作尺寸：長 7.4 公分、寬 5.5 公分、厚 0.6 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'玉獸紋韘形佩 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'本器為韘形佩，玉質，局部受沁微呈褐色。器表拋光細緻，明亮有光澤。中孔上下方的三角形網格紋與為數頗多的回勾單元，均是戰國到西漢常見的玉器紋飾，獸頸上的圓圈紋則是西漢晚期才漸漸開始流行，並在東漢廣為應用的紋飾。本器從紋飾題材風格、形制、玉質特徵及雕刻技巧來看，屬東漢作品。本器存放在院藏「紫檀雕蟠龍方盒百什件」（故雜877）中。', 1290.00, 20, N'/media/catalog/jade/故玉004358N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/71726?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'長 3.7 公分、寬 2.75 公分、厚 0.3 公分', '7b2fd968-295c-c353-90ce-9d2aed572601'),
    ('37a66fcb-ace3-65cb-d446-6f544e190e35', N'CARVING', N'artifact-贈雕000118N000000000', N'牙雕小豚－縮小複製品', N'不同材料有不同個性，好的雕刻懂得順勢而為。以牙雕小豚為靈感製作的縮小複製品，保留一份因材施藝的工藝趣味。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：雕刻' + NCHAR(10) + N'年代：戰國至六朝' + NCHAR(10) + N'商品尺寸：長 0.95 公分、寬 0.6 公分' + NCHAR(10) + N'原作尺寸：長 1.9 公分、寬 1.2 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'牙雕小豚 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'立雕小豚，體小而雕工圓熟，動物身軀與面龐較寫實，器呈黃色。類似雕工簡拙的小動物，從漢墓至六朝墓葬中皆曾見，其質材不限於牙或骨。從器物的雕刻風格看來，或可早至戰國。', 1320.00, 20, N'/media/catalog/carving/贈雕000118N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/45347?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1310000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'長 0.95 公分、寬 0.6 公分', 'd014ce98-0450-f3a4-739e-0994d9d7627e'),
    ('f604e798-7d6a-2f71-7507-70d4fa1738a6', N'COIN', N'artifact-購錢004730N000000000', N'元祐通寶－縮小複製品', N'一枚錢幣，連起的是制度與日常生活。這件「元祐通寶」縮小複製品，把龐大的時代故事收進容易細看的尺寸。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：錢幣' + NCHAR(10) + N'年代：北宋' + NCHAR(10) + N'商品尺寸：待測量' + NCHAR(10) + N'原作尺寸：待測量' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'元祐通寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'銅質。方孔圓錢，正面有楷書：「元祐通寶」四字，背面無文。', 730.00, 20, N'/media/catalog/coin/購錢004730N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/14068?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1330000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'待測量', '527643af-045b-654f-5eef-f8bb4af912f6'),
    ('3c6ba2e1-a0fc-e4b6-ed0e-71369b1af1de', N'COIN', N'artifact-購錢004719N000000000', N'熙寧元寶－縮小複製品', N'方寸之間，裝得下年代、制度與人們往來交易的痕跡。這件「熙寧元寶」縮小複製品，從一枚錢幣打開認識歷史的新角度。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：錢幣' + NCHAR(10) + N'年代：北宋' + NCHAR(10) + N'商品尺寸：待測量' + NCHAR(10) + N'原作尺寸：待測量' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'熙寧元寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'銅質。方孔圓錢，正面有楷書：「熙寧元寶」四字，背面無文。', 610.00, 20, N'/media/catalog/coin/購錢004719N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/14057?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1340000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'待測量', 'ee8dc661-131b-9500-017e-ed04c7501286'),
    ('332aa48a-7265-dd2b-097d-715c3f8feb33', N'BRONZE', N'artifact-贈銅000346N000000000', N'辟邪形鐙座－縮小複製品', N'先看整體輪廓，再找製作與歲月留下的細節，銅器總能讓人多停留一會兒。這件「辟邪形鐙座」縮小複製品，讓這份歷史感更貼近日常。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：銅器' + NCHAR(10) + N'年代：東漢' + NCHAR(10) + N'商品尺寸：高 1.5 公分、寬 3.8 公分' + NCHAR(10) + N'原作尺寸：高 3.0 公分、寬 7.6 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'辟邪形鐙座 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'銅質辟邪，後雙足平行，前雙足一前一後，如正邁步前行，頭部微微抬起，張嘴露齒，神氣昂揚。背上毛髮、翅膀，多作幾何化的長弧形，弧形內再飾以並列的陰線紋，以表現辟邪的皮毛。又背上有一管狀孔，或可插物於上，以為燈座或座承。嘴啣之羽觴入藏已缺失。', 1380.00, 20, N'/media/catalog/bronze/贈銅000346N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/24744?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1300000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 1.5 公分、寬 3.8 公分', 'f2502223-edf9-bbba-13a7-07aed3071694'),
    ('20ab803d-dcdb-e139-8f55-719be0f3da3b', N'JADE', N'artifact-故玉006497N000000000', N'玉龍獸紋鼻煙壺－縮小複製品', N'玉石經過琢磨才成器，也在流傳中留下不同時代的眼光。玉龍獸紋鼻煙壺化為縮小複製品，讓這份溫潤含蓄的玉器之美走進日常。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：玉器' + NCHAR(10) + N'年代：春秋' + NCHAR(10) + N'商品尺寸：寬 1.3 公分、高 2.2 公分' + NCHAR(10) + N'原作尺寸：寬 2.6 公分、高 4.4 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'玉龍獸紋鼻煙壺 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'玉質，以春秋時期之龍獸紋劍摽改刀而成。底增刻「乾隆年製」雙行隸書款，配嵌貓眼石銅蓋及金屬匙，細節考究，是乾隆以古玉收藏新用於鼻煙壺之代表。存放於養心殿之華滋堂、燕喜堂中清乾隆〈二屜木匣〉百什件中。', 1640.00, 20, N'/media/catalog/jade/故玉006497N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/57569?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'寬 1.3 公分、高 2.2 公分', '8fcdf7f4-beaf-71ff-611f-cc14ad50b599'),
    ('05f73154-f71c-08e6-bc81-724fbb726787', N'JADE', N'artifact-故玉006607N000000000', N'玉鴛鴦－縮小複製品', N'玉石經過琢磨才成器，也在流傳中留下不同時代的眼光。玉鴛鴦化為縮小複製品，讓這份溫潤含蓄的玉器之美走進日常。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：玉器' + NCHAR(10) + N'年代：南宋' + NCHAR(10) + N'商品尺寸：高 1.55 公分' + NCHAR(10) + N'原作尺寸：高 3.1 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'玉鴛鴦 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'玉質，局部染褐沁。利用天然外形與顏色琢成一鴛鴦，首頂鑿一穿孔，鳥周身飾細膩之羽毛紋飾。', 1150.00, 20, N'/media/catalog/jade/故玉006607N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/57679?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 1.55 公分', 'a4cdff05-f863-5891-24a6-ffd70d7afaea'),
    ('05f82b92-c1f3-3ff9-0282-72dd6d2e570d', N'CARVING', N'artifact-贈雕000292N000000000', N'竹雕零件－縮小複製品', N'不同材料有不同個性，好的雕刻懂得順勢而為。以竹雕零件為靈感製作的縮小複製品，保留一份因材施藝的工藝趣味。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：雕刻' + NCHAR(10) + N'年代：西漢至六朝' + NCHAR(10) + N'商品尺寸：長 2.4 公分、徑 1.2-0.75 公分' + NCHAR(10) + N'原作尺寸：長 4.8 公分、徑 1.2-1.5 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'竹雕零件 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'竹雕零件，已殘。器呈長橢圓椎形，乃取竹近根部實心部份雕成。器之窄面淺刻一動物面與身軀，似一昆蟲，身軀陰刻點紋與弧線，並或填黑彩、或填紅彩為飾；頭之上方向上生出兩觸鬚。頭下方鑿一孔，器側穿一大方孔，尾端亦有一孔，與前方之孔相通。此器可能為某種器物之配件，目前功能不明，俟考。', 1150.00, 20, N'/media/catalog/carving/贈雕000292N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/45516?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1320000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'長 2.4 公分、徑 1.2-0.75 公分', 'ea7f5904-6875-d626-d623-18969a233355'),
    ('93ef903c-fec8-1505-9667-731f9008bd7e', N'CERAMIC', N'artifact-故瓷018220N000000000', N'銅胎畫琺瑯西洋母子圖鼻煙壺－縮小複製品', N'一件陶瓷，可以從遠處看整體，也值得靠近欣賞質感。這件「銅胎畫琺瑯西洋母子圖鼻煙壺」縮小複製品，為收藏角落留下一份安定而耐看的風景。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：陶瓷' + NCHAR(10) + N'年代：清 乾隆' + NCHAR(10) + N'商品尺寸：高 2.45 公分、寬 1.8 公分' + NCHAR(10) + N'原作尺寸：高 4.9 公分、寬 3.6 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'銅胎畫琺瑯西洋母子圖鼻煙壺 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'腹部開光彩繪西洋母子圖，側壁開光彩繪風景；開光之外彩繪花卉。帶雕花銅蓋與牙匙。足內白地藍色雙框內雙行楷書「乾隆年製」。', 610.00, 20, N'/media/catalog/ceramic/故瓷018220N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/71687?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1320000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 2.45 公分、寬 1.8 公分', '4221dbf1-eeb4-de0a-1434-30efe6e57162'),
    ('8a8624a3-e5cb-b672-f50b-7385836b2a1c', N'PAINTING', N'artifact-故畫00138200000', N'唐王維千岩萬壑　卷－縮小複製品', N'畫面不只記錄所見，也保存創作者觀看世界的方式。這件「唐王維千岩萬壑　卷」縮小複製品，邀你把這份想像帶進自己的空間。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：繪畫' + NCHAR(10) + N'年代：唐玄宗開元二十四年（736）' + NCHAR(10) + N'商品尺寸：15.75 × 352.95 公分' + NCHAR(10) + N'原作尺寸：31.5 × 705.9 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'唐王維千岩萬壑　卷 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'此長卷畫雲水飛動，山谷郁郁盤盤、江岸連綿千里，臺地、山澗、飛瀑流泉、崖亭水榭、長橋村落等各式景觀，俱現筆端。然通幅之山石樹木，相似造型往往重複出現；用筆雖工整，有提頓轉折之處，卻少變化，欠筆力，偏於平板，當是後人假託王維之作。王維（西元七○一—七六一年），字摩詰，山西祁縣人。以詩名盛於開元、天寶間，書畫特臻其妙。工草隸，尤工畫山水，筆墨宛麗，氣韻高清，畫中極富詩意。', 830.00, 20, N'/media/catalog/painting/故畫00138200000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/14893?dep=P', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'15.75 × 352.95 公分', '1209e192-27f1-92ab-41fe-07552dbc2fe0'),
    ('63d5c567-6b52-8b9c-c646-744c2f917407', N'LACQUER', N'artifact-故漆000473N000000000', N'剔彩漆九龍圓盤－縮小複製品', N'漆藝講究耐心，也讓器物擁有難以取代的深沉質感。這件「剔彩漆九龍圓盤」縮小複製品，是一件越看越能發現味道的收藏。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：漆器' + NCHAR(10) + N'年代：明 嘉靖' + NCHAR(10) + N'商品尺寸：高 1.7 公分、口徑 9.8 公分、足徑 7.1 公分' + NCHAR(10) + N'原作尺寸：高 3.4 公分、口徑 19.6 公分、足徑 14.2 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'剔彩漆九龍圓盤 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'圓盤，圓沿，圈足，足及足內髹紅漆，盤內外剔彩，漆層自底而上的漆色為三組黃、紅相間，然後綠、黃，綠、紅。盤沿紋飾刻雲龍紋，左右對稱，中間以如意雲紋分界，左側一回首的綠身紅鰭行龍，緊接一同形黃身紅鰭行龍，底露紅漆。盤心圓形空間底露黃漆，一紅身綠鰭的行龍，轉身面向圓心，瞪眼張口，四爪張揚，龍鬚發舞，姿態威武。行龍外，間飾如意雲紋，黃、紅、綠漆色交織，莊嚴中不失富麗。刀法熟練俐落，斜刀中露出漆層的顏色，使物象增加立體效果，漆層薄，漆色潤，是官方雕漆的典型。', 950.00, 20, N'/media/catalog/lacquer/故漆000473N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/17568?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 1.7 公分、口徑 9.8 公分、足徑 7.1 公分', 'f4913179-9050-fae1-c907-20ef2a959915'),
    ('a820f75b-13f3-01e9-788f-74874e5bb231', N'JADE', N'artifact-故玉006597N000000000', N'玉劍璏－縮小複製品', N'從光澤、質地到琢磨留下的細節，玉器總有值得反覆欣賞之處。玉劍璏縮小複製品，邀你用更親近的距離重新認識它。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：玉器' + NCHAR(10) + N'年代：南宋至明' + NCHAR(10) + N'商品尺寸：長 1.7 公分、寬 0.55 公分' + NCHAR(10) + N'原作尺寸：長 3.4 公分、寬 1.1 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'玉劍璏 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'玉質，全器琢成一玉劍璏，器表光素無紋。', 1090.00, 20, N'/media/catalog/jade/故玉006597N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/57669?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'長 1.7 公分、寬 0.55 公分', '9ad97a6c-f002-c4ca-0ab3-9daed07c470d'),
    ('23118d3e-7439-a25e-17af-76bc73a19bef', N'COIN', N'artifact-購錢004782N000000000', N'熙寧元寶－縮小複製品', N'一枚錢幣，連起的是制度與日常生活。這件「熙寧元寶」縮小複製品，把龐大的時代故事收進容易細看的尺寸。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：錢幣' + NCHAR(10) + N'年代：北宋' + NCHAR(10) + N'商品尺寸：待測量' + NCHAR(10) + N'原作尺寸：待測量' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'熙寧元寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'銅質。方孔圓錢，正面有篆書：「熙寧元寶」四字，背面無文。', 620.00, 20, N'/media/catalog/coin/購錢004782N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/14120?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1340000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'待測量', 'b5912aca-e64b-749d-a496-7775c47085d3'),
    ('605f9fe1-c761-624e-fd89-77149e0a6752', N'PAINTING', N'artifact-購畫00010900000', N'清居廉花卉草蟲四屏　軸－縮小複製品', N'從構圖、線條到題材安排，書畫總有值得慢慢閱讀之處。以清居廉花卉草蟲四屏　軸為靈感製作的縮小複製品，讓欣賞不必受距離限制。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：繪畫' + NCHAR(10) + N'年代：清德宗光緒十四年（1888）' + NCHAR(10) + N'商品尺寸：50.25 × 17.3 公分' + NCHAR(10) + N'原作尺寸：100.5 × 34.6 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'清居廉花卉草蟲四屏　軸 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'居廉（西元一八二八–一九０四年），廣東番禺人。字士剛，號古泉。從兄居巢授與花卉寫生之法，後又兼取惲壽平、宋光寶、孟覲乙等人的沒骨技法自成一家，時人以「居派」名之，又稱「隔山派」。　　四屏分寫牡丹、凌霄、繡球、紫薇等時卉，並配以湖石、蜂、蝶、知了、螳螂。於精密寫實之外，饒富沒骨花卉清新典麗的特質，雖因重裝顏色稍褪，猶可清晰得見居氏慣採的「撞水」與「撞粉」畫技。', 680.00, 20, N'/media/catalog/painting/購畫00010900000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/33965?dep=P', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1360000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'50.25 × 17.3 公分', '8cc1c6e4-c021-465c-2336-581c4a40354b'),
    ('224b8fb5-1d15-6d50-9bae-779847ed4883', N'LACQUER', N'artifact-故漆000308N000000000', N'剔紅雲龍紋碗－縮小複製品', N'漆藝講究耐心，也讓器物擁有難以取代的深沉質感。這件「剔紅雲龍紋碗」縮小複製品，是一件越看越能發現味道的收藏。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：漆器' + NCHAR(10) + N'年代：清 乾隆' + NCHAR(10) + N'商品尺寸：高 3.7 公分、口徑 10.4 公分、足徑 4.5 公分' + NCHAR(10) + N'原作尺寸：高 7.4 公分、口徑 20.8 公分、足徑 9.0 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'剔紅雲龍紋碗 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'雕漆碗，通體雕紅、綠色漆。敞口，弧形壁，圈足。器身雕龍三對穿梭雲氣之間，綠漆地雕天文錦地，口緣與圈足各飾弦紋、回紋。器內與底髹黑色光漆，碗底有填金楷款「大清乾隆年製」。與雕漆碗托(故漆307)成組。', 680.00, 20, N'/media/catalog/lacquer/故漆000308N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/18230?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 3.7 公分、口徑 10.4 公分、足徑 4.5 公分', '1bd4e875-d5e6-4bc6-d325-072521c79756'),
    ('6b49241c-1046-6239-c699-783f04cb75e3', N'LACQUER', N'artifact-購漆000003N000000000', N'戧金彩漆葵式盤－縮小複製品', N'漆藝講究耐心，也讓器物擁有難以取代的深沉質感。這件「戧金彩漆葵式盤」縮小複製品，是一件越看越能發現味道的收藏。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：漆器' + NCHAR(10) + N'年代：明 嘉靖' + NCHAR(10) + N'商品尺寸：高 2.1 公分、盤徑 17.1 公分、足徑 13.25 公分' + NCHAR(10) + N'原作尺寸：高 4.2 公分、盤徑 34.2 公分、足徑 26.5 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'戧金彩漆葵式盤 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'葵式盤，褐漆地，器底中央陰刻填金直書「大明嘉靖年製」楷書款，以戧金勾勒紋樣，紋飾內填彩漆，紅、綠、藍、褐、白、黑等，色澤沈穩，刻畫仔細，漆面打磨細膩。盤緣分八區，每一區中央為山石，兩側各延伸一折枝花卉，花上飾珊瑚、象牙、錢幣、等雜寶八種，共兩組。盤心則作三把展開的摺扇，黑、紅、褐色的扇骨上，飾鎗金梅枝，有如陳設真實的摺扇。三扇面分別以乾坤雙龍、萬壽雙鳳、松竹梅鶴為紋飾主題，運用乾、坤二卦，盤長、壽字結，或將樹枝轉折作福、壽字形，物象描寫細緻規整，是明代嘉靖典型紋樣的組合模式及母題。', 940.00, 20, N'/media/catalog/lacquer/購漆000003N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/47874?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 2.1 公分、盤徑 17.1 公分、足徑 13.25 公分', 'dcdaf8de-cae8-9170-52a9-b73b6cf6aaf4'),
    ('31588342-05be-c0b3-a8d7-7aaaa8ab0fac', N'LACQUER', N'artifact-故漆000411N000000000', N'剔紅讀書圖雙層套盒－縮小複製品', N'漆器耐看的地方，在於表面質感與製作時間共同留下的韻味。以剔紅讀書圖雙層套盒為靈感製作的縮小複製品，適合在近處慢慢欣賞。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：漆器' + NCHAR(10) + N'年代：清 乾隆' + NCHAR(10) + N'商品尺寸：徑 5.5 公分' + NCHAR(10) + N'原作尺寸：徑 11.0 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'剔紅讀書圖雙層套盒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'盒蓋在綠漆錦地上浮雕庭園教子讀書圖。兩側樹石環立，中央一張桌子上擺著筆筒和書冊，一女子倚桌而坐，旁有四童子或捧書或扛戟。對樹石及人物衣褶的起伏多所描寫，盒側作龍鳳花卉，漆質澀，下刀俐落，技術熟練。', 640.00, 20, N'/media/catalog/lacquer/故漆000411N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/62072?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'徑 5.5 公分', '45cb2d3e-bc43-56a0-7328-d7f8112cba0c'),
    ('ab9e6d73-cb4f-df53-a465-7ac83da5fcfa', N'BRONZE', N'artifact-故銅002168N000000000', N'蟠虺乳丁紋鼎－縮小複製品', N'青銅器迷人的地方，在於器物本身與漫長年代共同形成的質感。以蟠虺乳丁紋鼎為靈感製作的縮小複製品，值得從不同角度細看。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：銅器' + NCHAR(10) + N'年代：戰國' + NCHAR(10) + N'商品尺寸：通高 15.85 公分、徑 13.9 公分、蓋徑 14.5 公分' + NCHAR(10) + N'原作尺寸：通高 31.7 公分、徑 27.8 公分、蓋徑 29.0 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'蟠虺乳丁紋鼎 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'附蓋圓鼎，器蓋中心有一圓捉手。子母口，雙附耳，深腹，三蹄足。雙耳微外撇，蓋、腹、耳皆飾蟠虺紋與乳丁紋。器蓋捉手外緣及腹部中央有一圈繩紋，腹下近足處有一周淺刻三角紋。器底、器足有範線。', 1430.00, 20, N'/media/catalog/bronze/故銅002168N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/53446?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1300000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'通高 15.85 公分、徑 13.9 公分、蓋徑 14.5 公分', '9cb9e880-9ee8-b70f-b41e-b5e65e94c401'),
    ('0a6d2de0-93e3-24a4-997a-7acdbd1e98ff', N'LACQUER', N'artifact-故漆000313N000000000', N'剔紅螭紋方盒－縮小複製品', N'一道漆、一段等待，漆器的深度來自層層累積的工序。這件「剔紅螭紋方盒」縮小複製品，把這份沉靜而講究的工藝氣質帶進日常。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：漆器' + NCHAR(10) + N'年代：清 乾隆' + NCHAR(10) + N'商品尺寸：長 14.8 公分、寬 9.95 公分、高 5.05 公分' + NCHAR(10) + N'原作尺寸：長 29.6 公分、寬 19.9 公分、高 10.1 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'剔紅螭紋方盒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'剔紅盒，色暗紅。長方形盒，罩式蓋，淺直壁，平底下有四小足。蓋面與側面雕飾拐子龍，餘地滿飾斜方朵花錦地，每折邊為回紋一道。器內與底髹黑色光漆，蓋內有填金楷款「蟠龍寶盒」，底款「大清乾隆年製」現多剝落。', 750.00, 20, N'/media/catalog/lacquer/故漆000313N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/18274?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'長 14.8 公分、寬 9.95 公分、高 5.05 公分', '984e8e92-556b-8ded-32a1-a98c73639533'),
    ('410f19d5-23c2-bba8-0664-7b7e8ff46643', N'COIN', N'artifact-購錢005317N000000000', N'祥符通寶－縮小複製品', N'看錢幣，不只看名稱，也看文字、形制與時代背景。這件「祥符通寶」縮小複製品，適合作為一段歷史收藏的起點。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：錢幣' + NCHAR(10) + N'年代：北宋' + NCHAR(10) + N'商品尺寸：待測量' + NCHAR(10) + N'原作尺寸：待測量' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'祥符通寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'銅質。方孔圓錢，正面有楷書：「祥符通寶」四字，背面無文。', 730.00, 20, N'/media/catalog/coin/購錢005317N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/14655?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1340000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'待測量', '5889137a-681e-69af-b628-83872fdc9885'),
    ('1a10052f-4a90-ec3d-007b-7c27fdfe3848', N'JADE', N'artifact-故玉004345N000000000', N'玉龍佩－縮小複製品', N'一件玉器，可以寄託品味，也能收藏一段時代記憶。以玉龍佩為靈感製作的縮小複製品，為展示空間添上一份沉靜氣質。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：玉器' + NCHAR(10) + N'年代：戰國中期' + NCHAR(10) + N'商品尺寸：長 6 公分、寬 2.65 公分、厚 0.15 公分' + NCHAR(10) + N'原作尺寸：長 12.0 公分、寬 5.3 公分、厚 0.3 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'玉龍佩 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'本器為龍形佩，玉質，帶褐色沁。器身彎曲呈Ｓ形，器表淺浮雕穀紋。從器身中間外側線孔，與兩側的打孔痕推測，本器疑由玉珩改制成佩。從蜿蜒造形、排列有序的穀紋來看，屬戰國中期作品。本器存放在院藏「紫檀雕蟠龍方盒百什件」（故雜877）中。', 1390.00, 20, N'/media/catalog/jade/故玉004345N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/71716?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'長 6 公分、寬 2.65 公分、厚 0.15 公分', '79c091ca-eddc-37ee-5d24-b9ea8078b6b2'),
    ('132abe83-2bef-3a52-dfa6-7c6c8a07a7f9', N'CARVING', N'artifact-贈雕000195N000000000', N'骨雕鸞鳳綬帶板－縮小複製品', N'雕刻值得從多個角度觀看，輪廓、轉折與細部會逐一展開。這件「骨雕鸞鳳綬帶板」縮小複製品，適合擺在能讓人停下腳步的位置。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：雕刻' + NCHAR(10) + N'年代：宋至元' + NCHAR(10) + N'商品尺寸：長 7.65 公分、寬 3.1 公分、厚 0.95 公分' + NCHAR(10) + N'原作尺寸：長 15.3 公分、寬 6.2 公分、厚 1.9 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'骨雕鸞鳳綬帶板 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'長方形，四隅與中央凹入，每一邊亦內弧，兩面周邊皆起寬棱，一面中央浮雕壽石，左右各浮雕一鸞或一鳳翔於牡丹花叢中；另一面在中央分界成左右各一方形，各雕一綬帶鳥翔於牡丹花叢中，鸞鳳與綬帶鳥皆首尾相錯地面像器中央。此器兩面皆浮雕紋飾，原可能是他器之嵌件。', 850.00, 20, N'/media/catalog/carving/贈雕000195N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/45423?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1320000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'長 7.65 公分、寬 3.1 公分、厚 0.95 公分', 'f992545a-3a40-7132-bc2e-e9e9c2d06284'),
    ('378b8aea-0fb6-9e8b-a186-7d4f09a88c62', N'COIN', N'artifact-購錢004779N000000000', N'皇宋通寶－縮小複製品', N'一枚錢幣，連起的是制度與日常生活。這件「皇宋通寶」縮小複製品，把龐大的時代故事收進容易細看的尺寸。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：錢幣' + NCHAR(10) + N'年代：北宋' + NCHAR(10) + N'商品尺寸：待測量' + NCHAR(10) + N'原作尺寸：待測量' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'皇宋通寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'銅質。方孔圓錢，正面有篆書：「皇宋通寶」四字，背面無文。', 840.00, 20, N'/media/catalog/coin/購錢004779N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/14117?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1340000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'待測量', '263e50e1-989c-d8f8-cb31-48f641e34e80'),
    ('0c7e9f85-99d5-e0e2-9c1c-7d59df3321ed', N'LACQUER', N'artifact-故漆000415N000000000', N'剔紅松下高士圖圓盒－縮小複製品', N'漆器耐看的地方，在於表面質感與製作時間共同留下的韻味。以剔紅松下高士圖圓盒為靈感製作的縮小複製品，適合在近處慢慢欣賞。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：漆器' + NCHAR(10) + N'年代：清 乾隆' + NCHAR(10) + N'商品尺寸：漆盒徑 2 公分；鼻煙壺寬 0.5 公分、高 1.25 公分' + NCHAR(10) + N'原作尺寸：漆盒徑 4.0 公分；鼻煙壺寬 1.0 公分、高 2.5 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'剔紅松下高士圖圓盒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'鼻煙壺由極細小葫蘆製成，加上牙雕蒂頭蓋及匙，體積雖小在製作細節上卻一絲不茍，存放於乾隆年製雕漆小盒中。', 760.00, 20, N'/media/catalog/lacquer/故漆000415N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/62075?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'漆盒徑 2 公分；鼻煙壺寬 0.5 公分、高 1.25 公分', 'e3742c6c-1da5-f31d-ece4-996e000080c8'),
    ('759d1238-66fe-58fb-5ed0-7d6dfdadb278', N'PAINTING', N'artifact-故畫003780N000000000', N'御筆蘭花 卷－縮小複製品', N'畫面不只記錄所見，也保存創作者觀看世界的方式。這件「御筆蘭花 卷」縮小複製品，邀你把這份想像帶進自己的空間。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：繪畫' + NCHAR(10) + N'年代：清 道光1年' + NCHAR(10) + N'商品尺寸：畫心長寬 12.5*31.5 公分' + NCHAR(10) + N'原作尺寸：畫心長寬 12.5*63 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'御筆蘭花 卷 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'紙本小手卷，包首題簽「御筆蘭花」四楷字，卷內則為清宣宗於道光元年（1821）所繪之蘭花，其以淡墨簡筆寫石，濃墨點苔，並細線迴鉤以示水紋。蘭花花葉則以綠色為主調，蘭葉以較深之綠色描繪，花梗與蘭花則以較淡綠色繪寫，映襯出其鮮翠與活力。卷首有「道光辛巳（1821）秋」年款，並鈐「慎靜齋」白文印，卷末有「御筆」款識與「道光」朱文方印。本卷與其他九件書畫同儲於漆盒中。', 590.00, 20, N'/media/catalog/painting/故畫003780N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/61967?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'畫心長寬 12.5*31.5 公分', '9cd30175-f138-e32f-2fa0-eb31d043e802'),
    ('94ffcb5a-5d35-92ce-a5be-7da6b0d7cd1f', N'PAINTING', N'artifact-故畫00353600009', N'明人畫扇集冊　冊　明吳士冠後赤壁圖賦－縮小複製品', N'畫面不只記錄所見，也保存創作者觀看世界的方式。這件「明人畫扇集冊　冊　明吳士冠後赤壁圖賦」縮小複製品，邀你把這份想像帶進自己的空間。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：繪畫' + NCHAR(10) + N'年代：明神宗萬曆三十九年（1611）' + NCHAR(10) + N'商品尺寸：8.2 × 24.9 公分' + NCHAR(10) + N'原作尺寸：16.4 × 49.8 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'明人畫扇集冊　冊　明吳士冠後赤壁圖賦 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'吳士冠（生卒年待考），字相如，蘇州人。善書，曾為袁中郎書瓶花齋集刻行之。畫山水及墨花頗有別趣。天啟七年（一六二七）嘗典校胡正言十竹齋蘭譜。' + NCHAR(13) + NCHAR(10) + N'　　本幅畫蘇東坡後赤壁賦。右下角作人物三，中央一人，當是蘇軾，二客從其過黃泥之坂。畫中景選擇當時氣候「霜露既降，木葉盡脫。」但為強調畫面氣息，仍留有紅葉點點。整幅之筆調，因枯枝、苔點，均是禿筆聚成，又因泥金畫面，不吸水墨色彩，點點秋光益見蕭索意味。' + NCHAR(13) + NCHAR(10) + N'　　本幅為「明人便面集錦」冊第九開。', 710.00, 20, N'/media/catalog/painting/故畫00353600009/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/18371?dep=P', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1360000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'8.2 × 24.9 公分', '723aad91-7e13-a4a4-8453-8db5b336aef0'),
    ('5e5c209d-2cd0-56c2-b122-7de38df41bdb', N'JADE', N'artifact-故玉004344N000000000', N'春水玉飾－縮小複製品', N'玉石經過琢磨才成器，也在流傳中留下不同時代的眼光。春水玉飾化為縮小複製品，讓這份溫潤含蓄的玉器之美走進日常。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：玉器' + NCHAR(10) + N'年代：金至元' + NCHAR(10) + N'商品尺寸：長 3.7 公分、寬 2.5 公分、厚 0.6 公分' + NCHAR(10) + N'原作尺寸：長 7.4 公分、寬 5.0 公分、厚 1.2 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'春水玉飾 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'本器為橢圓形玉飾，玉質，玉質溫潤，器表局部黃斑。正面鏤雕「春水」主題之海東青鶻攫天鵝。海東青鶻身形大小如鵲，從上空以其爪擒抓自蓮塘水草間驚起之天鵝頭頂，天鵝表情生動，兩禽周圍密飾雲氣紋。從上述「春水」題材，與使用玉皮巧雕的特徵來看，屬金至元作品。本器存放在院藏「紫檀雕蟠龍方盒百什件」（故雜877）中。', 1090.00, 20, N'/media/catalog/jade/故玉004344N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/71715?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1340000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'長 3.7 公分、寬 2.5 公分、厚 0.6 公分', '136f39bf-08db-a14d-e6ae-707a799cea17'),
    ('9efdeeb8-16ef-0d0f-58d2-8046e46af48d', N'JADE', N'artifact-故玉005778N000000000', N'玉雙螭耳鼻煙壺－縮小複製品', N'玉石經過琢磨才成器，也在流傳中留下不同時代的眼光。玉雙螭耳鼻煙壺化為縮小複製品，讓這份溫潤含蓄的玉器之美走進日常。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：玉器' + NCHAR(10) + N'年代：清 乾隆' + NCHAR(10) + N'商品尺寸：寬 1.9 公分、高 2.6 公分' + NCHAR(10) + N'原作尺寸：寬 3.8 公分、高 5.2 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'玉雙螭耳鼻煙壺 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'肩部鏤雕螭耳，頸部以下依序浮雕如意雲首紋、回紋、蕉葉紋。帶銅嵌碧璽蓋與銅匙。底陰刻橫書隸款「乾隆年製」。', 1010.00, 20, N'/media/catalog/jade/故玉005778N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/71700?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'寬 1.9 公分、高 2.6 公分', '069ab698-be95-36c2-b0c6-6c2261c41e02'),
    ('9a0e72a5-1de9-d398-d65c-80fec7f6ffb3', N'ENAMEL', N'artifact-故琺000837N000000000', N'掐絲琺瑯梵文碟－縮小複製品', N'色彩是琺瑯最直接的吸引力，工序與細節則值得再三欣賞。以掐絲琺瑯梵文碟為靈感製作的縮小複製品，讓空間多一抹典藏氣息。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：琺瑯器' + NCHAR(10) + N'年代：清 乾隆' + NCHAR(10) + N'商品尺寸：口徑 7.5 公分' + NCHAR(10) + N'原作尺寸：口徑 15.0 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'掐絲琺瑯梵文碟 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'侈口，折沿，淺壁，平底，圈足。全器淺藍地，口沿寫有一圈梵文，內底有卷鬚錦，中心有一由七個梵文及三個符號組成的「十相自在」吉祥紋飾，盤內外壁為朵雲紋間飾佛教七珍、八寶。底部有陰刻「乾隆年製」四字雙行楷書雙方框款。', 810.00, 20, N'/media/catalog/enamel/故琺000837N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/61823?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1340000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'口徑 7.5 公分', '54fd96e9-012a-0ab7-82ea-f138243a4c0d'),
    ('a5b62057-f8f3-b3f4-8849-81128c9d422a', N'COIN', N'artifact-購錢005411N000000000', N'祥符元寶－縮小複製品', N'一枚錢幣，連起的是制度與日常生活。這件「祥符元寶」縮小複製品，把龐大的時代故事收進容易細看的尺寸。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：錢幣' + NCHAR(10) + N'年代：北宋' + NCHAR(10) + N'商品尺寸：待測量' + NCHAR(10) + N'原作尺寸：待測量' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'祥符元寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'銅質。方孔圓錢，正面有楷書：「祥符元寶」四字，背面無文。', 650.00, 20, N'/media/catalog/coin/購錢005411N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/14749?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1340000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'待測量', '33fbff91-7c21-bf81-0674-c59afbcd0696'),
    ('baa90bf9-cda5-4924-64dd-82105d7b61ec', N'JADE', N'artifact-故玉006586N000000000', N'玉蟬形佩－縮小複製品', N'欣賞玉器，不只看材質，也看工匠如何順著天然質地雕琢成形。玉蟬形佩縮小複製品，適合放在近處慢慢看、慢慢品味。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：玉器' + NCHAR(10) + N'年代：商至西周' + NCHAR(10) + N'商品尺寸：長 1.1 公分' + NCHAR(10) + N'原作尺寸：長 2.2 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'玉蟬形佩 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'玉質，夾褐、赭斑。全器琢成一扁平玉蟬形狀，雙面均雕刻紋飾，蟬腹、蟬首部位皆鑿有兩相互貫通之穿孔，蟬首繫帶有鈕扣結之黃絛。', 1680.00, 20, N'/media/catalog/jade/故玉006586N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/57658?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'長 1.1 公分', 'b4d0db9f-24f1-ae4e-2624-c05245c6a662'),
    ('63532690-b951-e3a6-b310-82b64fcbf643', N'CARVING', N'artifact-贈雕000119N000000000', N'牙雕小豚－縮小複製品', N'雕刻是在材料上不斷取捨，最後留下最想表達的形貌。這件「牙雕小豚」縮小複製品，讓刀工與構思成為可以近距離欣賞的焦點。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：雕刻' + NCHAR(10) + N'年代：戰國至六朝' + NCHAR(10) + N'商品尺寸：長 1.25 公分、高 0.7 公分' + NCHAR(10) + N'原作尺寸：長 2.5 公分、高 1.4 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'牙雕小豚 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'立雕小豚，身軀與面龐較方。類似雕工簡拙的小動物，從漢墓至六朝墓葬中皆曾見，其質材不限於牙或骨。從器物的雕刻風格看來，或可早至戰國。', 1360.00, 20, N'/media/catalog/carving/贈雕000119N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/45348?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1320000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'長 1.25 公分、高 0.7 公分', '9e962dc6-4cb9-c9df-1703-7e862e88a5e8'),
    ('e678b739-8b2d-5cc2-330f-837d3e03f920', N'COIN', N'artifact-購錢004736N000000000', N'祥符元寶－縮小複製品', N'方寸之間，裝得下年代、制度與人們往來交易的痕跡。這件「祥符元寶」縮小複製品，從一枚錢幣打開認識歷史的新角度。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：錢幣' + NCHAR(10) + N'年代：北宋' + NCHAR(10) + N'商品尺寸：待測量' + NCHAR(10) + N'原作尺寸：待測量' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'祥符元寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'銅質。方孔圓錢，正面有楷書：「祥符元寶」四字，背面無文。', 650.00, 20, N'/media/catalog/coin/購錢004736N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/14074?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1340000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'待測量', '21e96c0f-1a73-e475-0fdb-e65f6c3dcc7a'),
    ('00c8cfca-32ec-6b8d-7ea3-865d01f9a086', N'PAINTING', N'artifact-故畫003855N000000000', N'畫風花雪月 冊－縮小複製品', N'遠看整體氣勢，近看筆墨細節，書畫能陪人反覆觀看。這件「畫風花雪月 冊」縮小複製品，為牆面或展示角落留下一段雅致風景。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：繪畫' + NCHAR(10) + N'年代：清 乾隆' + NCHAR(10) + N'商品尺寸：長 3.65 公分、寬 2.45 公分、厚 0.25 公分' + NCHAR(10) + N'原作尺寸：長 7.3 公分、寬 4.9 公分、厚 0.5 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'畫風花雪月 冊 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'小冊頁，計五開，封面有「張鵬翀畫風花雪月」題籤，內頁作一圖一文的對頁形式。四組圖文皆為張鵬翀所做，分別以「風」、「花」、「雪」、「月」為題，繪圖作詩。圖皆以簡單的上下兩段式構圖，如「風」圖以設色輕抹遠山風柳表現，「花」圖則繪以遠山與滿林花發。若將「月」圖詩句「年年萬壽觴，滿酌中秋月」，與乾隆皇帝生於八月之事並觀，可知這件作品很可能是張鵬翀特別用心設計的祝壽邀賞之作。', 660.00, 20, N'/media/catalog/painting/故畫003855N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/62022?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1360000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'長 3.65 公分、寬 2.45 公分、厚 0.25 公分', 'add27635-e7a8-2904-d2e4-fd04ae9ba154'),
    ('de05a2e6-06ee-1223-4d34-86929bf40081', N'BRONZE', N'artifact-中銅001030N000000000', N'□容三鈁－縮小複製品', N'先看整體輪廓，再找製作與歲月留下的細節，銅器總能讓人多停留一會兒。這件「□容三鈁」縮小複製品，讓這份歷史感更貼近日常。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：銅器' + NCHAR(10) + N'年代：戰國' + NCHAR(10) + N'商品尺寸：高 17.8 公分、口徑 5.25 公分' + NCHAR(10) + N'原作尺寸：高 35.6 公分、口徑 10.5 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'□容三鈁 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'鈁，四面等邊的方壺，微侈口，直頸，溜肩，圓腹，方形圈足，兩側有獸首啣環耳。口沿飾卷雲紋，頸部飾三角獸面紋及勾雲紋，肩腹部有對夔鳳紋將畫面劃成六等分，地襯飾夔龍紋，圈足飾勾雲紋，有一面肩部中央有銘文「□容三」。', 1260.00, 20, N'/media/catalog/bronze/中銅001030N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/53444?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1250000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 17.8 公分、口徑 5.25 公分', '582f7dc4-25ca-0fce-c33e-d68d884d7af3'),
    ('71337085-50ed-385f-43c9-873647271f0c', N'BRONZE', N'artifact-中銅000414N000000000', N'蟠夔紋罍－縮小複製品', N'青銅器迷人的地方，在於器物本身與漫長年代共同形成的質感。以蟠夔紋罍為靈感製作的縮小複製品，值得從不同角度細看。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：銅器' + NCHAR(10) + N'年代：春秋' + NCHAR(10) + N'商品尺寸：高 12.6 公分、徑 8.4 公分' + NCHAR(10) + N'原作尺寸：高 25.2 公分、徑 16.8 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'蟠夔紋罍 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'圓口，短直頸，斜肩，兩獸首立耳，斂腹，平底。肩與腹部以粗弦紋區隔開來，上下各飾滿蟠夔紋，眼部突出作乳丁紋。', 1560.00, 20, N'/media/catalog/bronze/中銅000414N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/53451?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1300000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 12.6 公分、徑 8.4 公分', 'ab9ca855-5ce9-640b-8372-a3f2b289698d'),
    ('60728365-2976-e582-e2ea-876a0917f2fc', N'CARVING', N'artifact-贈雕000168N000000000', N'牙帶扣－縮小複製品', N'不同材料有不同個性，好的雕刻懂得順勢而為。以牙帶扣為靈感製作的縮小複製品，保留一份因材施藝的工藝趣味。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：雕刻' + NCHAR(10) + N'年代：東漢至六朝' + NCHAR(10) + N'商品尺寸：長 1.4 公分、寬 1.1 公分、厚 0.3 公分' + NCHAR(10) + N'原作尺寸：長 2.8 公分、寬 2.2 公分、厚 0.6 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'牙帶扣 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'長方形一端較寬而圓弧，中央較突而寬，左右各有一長形孔，突而寬的部位正中凹下，可容一活動扣針；側視之，左右可見二小孔，以容插榫。此件形似今日腰帶頭，器表除銜接腰帶部位外，餘皆陰刻短線紋，並填紅彩為飾。', 1140.00, 20, N'/media/catalog/carving/贈雕000168N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/45396?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1310000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'長 1.4 公分、寬 1.1 公分、厚 0.3 公分', '4e5b0daa-9f1b-9915-50a0-18d7e2edda40'),
    ('44159b08-2f0b-4eac-cd41-883af884798d', N'JADE', N'artifact-故玉009142N000000000', N'玉蠶－縮小複製品', N'玉石經過琢磨才成器，也在流傳中留下不同時代的眼光。玉蠶化為縮小複製品，讓這份溫潤含蓄的玉器之美走進日常。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：玉器' + NCHAR(10) + N'年代：商晚期至西周早期' + NCHAR(10) + N'商品尺寸：長 1.65 公分、徑 0.5 公分、珍珠徑 0.45 公分' + NCHAR(10) + N'原作尺寸：長 3.3 公分、徑 1.0 公分、珍珠徑 0.9 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'玉蠶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'本件玉件色澤呈深褐色，全器呈圓柱狀但近似蠶之軀體，表面分成許多凸起之「節」。本件一端有穿孔繫有線繩，下方繫有一粒珍珠，推測本件原本用途可能為整組佩飾之配件。', 1660.00, 20, N'/media/catalog/jade/故玉009142N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/60183?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'長 1.65 公分、徑 0.5 公分、珍珠徑 0.45 公分', 'dc8cdf9e-1358-5f99-427c-bcaef2922575'),
    ('66b20669-f673-d638-e8a6-88a697ac3e75', N'CERAMIC', N'artifact-故瓷018094N000000000', N'青花梵文杯－縮小複製品', N'從日常器用到典藏珍品，陶瓷記錄了不同時代對生活之美的想像。這件「青花梵文杯」縮小複製品，讓這段美感自然融入展示空間。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：陶瓷' + NCHAR(10) + N'年代：明 萬曆' + NCHAR(10) + N'商品尺寸：口徑 2.3 公分、底徑 1.3 公分、高 1.15 公分、連木托高 1.35 公分' + NCHAR(10) + N'原作尺寸：口徑 4.6 公分、底徑 2.6 公分、高 2.3 公分、連木托高 2.7 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'青花梵文杯 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'本器為小杯，斂口，壁呈弧形，淺圈足，外壁繪青花花鳥，內壁以青花書梵文，底有「大明萬曆年製」青花楷書六字款。從器底「大明萬曆年製」款識的寫法來看，可能屬清代仿製。', 740.00, 20, N'/media/catalog/ceramic/故瓷018094N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/71735?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1330000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'口徑 2.3 公分、底徑 1.3 公分、高 1.15 公分、連木托高 1.35 公分', '80b44f1d-c15e-30c8-d444-fcbc5596d7ed'),
    ('82d7b2ab-e291-b73e-46c2-88c01ebcecd1', N'BRONZE', N'artifact-中銅000039N000000000', N'蟠夔紋盆－縮小複製品', N'青銅器迷人的地方，在於器物本身與漫長年代共同形成的質感。以蟠夔紋盆為靈感製作的縮小複製品，值得從不同角度細看。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：銅器' + NCHAR(10) + N'年代：春秋' + NCHAR(10) + N'商品尺寸：高 5.25 公分、徑 11 公分' + NCHAR(10) + N'原作尺寸：高 10.5 公分、徑 22.0 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'蟠夔紋盆 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'敞口折沿，束頸，碩腹下收，圓弧底，帶角異獸雙耳。器頸與腹上半部滿布紋飾，腹部紋飾有如將夔龍相交成缺一角的「卍」字形，但是並不明確描繪夔龍的特徵，便讓這些紋飾既有幾何形的規整，也可連結到未規整前的夔龍樣式。腹外壁下半則裝飾蟬紋。', 1350.00, 20, N'/media/catalog/bronze/中銅000039N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/53449?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1300000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 5.25 公分、徑 11 公分', 'e7555488-93fc-1c32-6775-65bd36c3389a'),
    ('3c35a704-dfdb-3db7-7e5f-89022b546e20', N'BRONZE', N'artifact-中銅000051N000000000', N'嵌金銀雲紋壺－縮小複製品', N'金屬與火塑成器物，歲月再替表面留下時間的痕跡。這件「嵌金銀雲紋壺」縮小複製品，把銅器沉穩厚實的存在感帶進收藏空間。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：銅器' + NCHAR(10) + N'年代：南宋至明' + NCHAR(10) + N'商品尺寸：高 22.85 公分' + NCHAR(10) + N'原作尺寸：高 45.7 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'嵌金銀雲紋壺 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'本器紋飾以簡化的獸帶紋為主，填以回紋地。由上至下，第一道為三角紋，第二、三道為獸帶紋。三角紋及獸帶紋以紅銅片鑲嵌。口沿及圈足上也有銀絲嵌的心形紋、螺形紋及三角紋。兩側有鋪首銜環為飾。本件器物是乾隆三十四年(1769)頒賜國子監的「周笵十器」之一，名之為「周雷紋壺」。', 960.00, 20, N'/media/catalog/bronze/中銅000051N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/6553?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1300000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 22.85 公分', '8e051dc6-49f6-b31b-b24a-9cd7d1701367'),
    ('cee82eb4-adc8-ee88-92ad-89843dd61a16', N'BRONZE', N'artifact-中銅000120N000000000', N'召仲簠－縮小複製品', N'金屬與火塑成器物，歲月再替表面留下時間的痕跡。這件「召仲簠」縮小複製品，把銅器沉穩厚實的存在感帶進收藏空間。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：銅器' + NCHAR(10) + N'年代：南宋至明' + NCHAR(10) + N'商品尺寸：高 11.9 公分' + NCHAR(10) + N'原作尺寸：高 23.8 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'召仲簠 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'本器蓋器造型基本相同，長方形，腹斜收，圈足每邊有缺，兩側置獸耳一對，蓋沿與器合口處，每邊正中央有一牛首，可以固定器蓋不致滑落。全器裝飾吐舌蟠虺紋。器蓋對銘，銘文作：「唯六月初丁亥，冶仲考父自作壺，用祀用饗多福祿，用旂眉壽萬年無疆，子子孫永寶是尚。 」器銘泐蝕且輭弱無力，內容摹自宋代《宣和博古圖》的「周仲丁壺」。本件器物是乾隆三十四年(1769)頒賜國子監的「周笵十器」之一，名之為「周召仲簠」。', 1070.00, 20, N'/media/catalog/bronze/中銅000120N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/6701?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1300000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 11.9 公分', '7d008bba-d61e-eddf-eec7-dc5e7a4a190e'),
    ('b14970f5-1e00-2396-e3ee-8b27897c1ba3', N'CERAMIC', N'artifact-購瓷000089N000000000', N'陶珠－縮小複製品', N'泥土經過塑形與窯火，才成為能被長久欣賞的器物。這件「陶珠」縮小複製品，把陶瓷溫雅耐看的氣質帶到眼前。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：陶瓷' + NCHAR(10) + N'年代：戰國' + NCHAR(10) + N'商品尺寸：高 0.5 公分、外徑 0.7 公分、孔徑 0.5-0.3 公分' + NCHAR(10) + N'原作尺寸：高 1.0 公分、外徑 1.4 公分、孔徑 0.5-0.6 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'陶珠 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'灰白陶胎珠粒，中心穿孔，外壁有藍、白突起圓點狀燒結紋飾。浙江無錫鴻山戰國越墓層曾出土類似灰白泥質陶胎，施點狀彩飾物件。', 1190.00, 20, N'/media/catalog/ceramic/購瓷000089N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/42970?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1330000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 0.5 公分、外徑 0.7 公分、孔徑 0.5-0.3 公分', 'd3e831c4-76ca-c070-ebeb-1d55b845ab10'),
    ('5e8ace1f-f624-24cf-9c54-8b2ed33e21a5', N'PAINTING', N'artifact-贈畫00043800000', N'明文徵明蕉池積雪　軸－縮小複製品', N'畫面不只記錄所見，也保存創作者觀看世界的方式。這件「明文徵明蕉池積雪　軸」縮小複製品，邀你把這份想像帶進自己的空間。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：繪畫' + NCHAR(10) + N'年代：明世宗嘉靖十一年（1532）' + NCHAR(10) + N'商品尺寸：32.2 × 13.45 公分' + NCHAR(10) + N'原作尺寸：64.4 × 26.9 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'明文徵明蕉池積雪　軸 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'文徵明（西元年一四七○－一五五九）江蘇長洲人，文信公後裔。初名壁，字徵明，後以字行，更字徵仲，號停雲生、衡山。畫師沈周，書畫雙絕，為明四大家之一。文氏享年九十，高齡健碩，猶孜孜於書畫，故作品傳世頗多。本幅畫蕉石盆景，幅上題詠甚多，道出畫題來源。如就畫賞畫，綠蕉白石古盆，相映成趣，彌覺可愛。款署壬辰（一五三二）亦脫境之筆。本幅為黃君璧先生捐贈。', 720.00, 20, N'/media/catalog/painting/贈畫00043800000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/19596?dep=P', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1360000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'32.2 × 13.45 公分', 'b2450c9d-90a9-6b14-4c7c-d465f928383d'),
    ('443a9031-82b8-9757-77d7-8c4417c20bfb', N'BRONZE', N'artifact-故銅002575N000000000', N'銅方觚－縮小複製品', N'青銅器迷人的地方，在於器物本身與漫長年代共同形成的質感。以銅方觚為靈感製作的縮小複製品，值得從不同角度細看。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：銅器' + NCHAR(10) + N'年代：西周' + NCHAR(10) + N'商品尺寸：通高 4.15 公分' + NCHAR(10) + N'原作尺寸：通高 8.3 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'銅方觚 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'此件器物是明清時期用西周的鑾鈴改制而成。', 1370.00, 20, N'/media/catalog/bronze/故銅002575N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/62261?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1310000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'通高 4.15 公分', '31fc503b-b4b6-6a84-52d7-77f94b48b994'),
    ('2d3bafd0-e3c1-be59-0289-8ccde22357c9', N'CARVING', N'artifact-故雕000271N000000000', N'葫蘆普天鈞慶罐－縮小複製品', N'不同材料有不同個性，好的雕刻懂得順勢而為。以葫蘆普天鈞慶罐為靈感製作的縮小複製品，保留一份因材施藝的工藝趣味。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：雕刻' + NCHAR(10) + N'年代：清 康熙' + NCHAR(10) + N'商品尺寸：長 2.7 公分、寬 2.65 公分、高 3.75 公分' + NCHAR(10) + N'原作尺寸：長 5.4 公分、寬 5.3 公分、高 7.5 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'葫蘆普天鈞慶罐 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'方形壺盧器，短頸，緩斜式與肩相接，腹部平直，上方至肩與下方至底處內折呈階狀，底有方框式足。肩部有四出如意雲頭紋，兩側隱現兩道模製範線，腹部四面各有楷體陽文「普」、「天」、「鈞」、「慶」四字，均以連續回紋及數重平行之方框為邊飾，器腹內髹塗黑漆，器底方足內模製「康熙賞玩」雙行楷書款。此器在造形上將細頸與方腹加以結合，紋飾則以文字與幾何線條之規整對稱為主體，各處折沿及雲頭紋線條宛轉，有剛柔並濟，質樸方正的視覺效果。', 730.00, 20, N'/media/catalog/carving/故雕000271N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/62498?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1320000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'長 2.7 公分、寬 2.65 公分、高 3.75 公分', 'e62c0ff9-f69d-d0c5-6fdf-3816c86fcfed'),
    ('44342259-dce4-9e8a-42f3-8de249074844', N'ENAMEL', N'artifact-故琺000941N000000000', N'銅胎畫琺瑯番蓮紋瓶－縮小複製品', N'色彩是琺瑯最直接的吸引力，工序與細節則值得再三欣賞。以銅胎畫琺瑯番蓮紋瓶為靈感製作的縮小複製品，讓空間多一抹典藏氣息。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：琺瑯器' + NCHAR(10) + N'年代：清 雍正' + NCHAR(10) + N'商品尺寸：高 15.2 公分、口徑 6 公分' + NCHAR(10) + N'原作尺寸：高 30.4 公分、口徑 12.0 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'銅胎畫琺瑯番蓮紋瓶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'敞口，折沿，長頸，雙螭耳，圓腹，外撇圈足，平底。雙耳鑄造成螭形，器表以畫琺瑯繪製紋飾，折沿為白地紅色捲草紋，器內淺藍地，器表黃地，口外繪藍色如意雲紋，頸部繪纏枝五彩番蓮紋，頸部下緣有四如意形開光，內繪黑地五彩番蓮紋；腹部繪纏枝番蓮紋，下緣飾一全藍色如意雲紋，下接黑地。底部白地，中央有青花書「雍正年製」四字雙行宋體雙方框款。附圓形如意雲足座一只，與故琺942成一對。', 940.00, 20, N'/media/catalog/enamel/故琺000941N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/61902?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1340000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 15.2 公分、口徑 6 公分', '1eb1bb50-9bd4-08b2-4f65-7c29de74dd95'),
    ('59698c0d-ada9-c177-cfa3-92ebd0a3e392', N'CERAMIC', N'artifact-故瓷018036N000000000', N'青瓷花插－縮小複製品', N'從日常器用到典藏珍品，陶瓷記錄了不同時代對生活之美的想像。這件「青瓷花插」縮小複製品，讓這段美感自然融入展示空間。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：陶瓷' + NCHAR(10) + N'年代：南宋' + NCHAR(10) + N'商品尺寸：高 8.65 公分、口徑 4.5 公分' + NCHAR(10) + N'原作尺寸：高 17.3 公分、口徑 9.0 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'青瓷花插 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'圓筒形，口微內斂，器身微外鼓，腹部以下漸收，器表飾弦紋三道，平底，淺圈足。墊燒，內外施濃釉，呈粉青色，口沿釉薄現出灰色邊，底部有積釉痕。器表開棕色大紋片，間雜細小縮釉點。足端與外底塗黑褐色薄汁，周緣局部沾釉。', 780.00, 20, N'/media/catalog/ceramic/故瓷018036N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/60958?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1330000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 8.65 公分、口徑 4.5 公分', 'bdbcd884-ae7b-c52b-4667-95a3386dba35'),
    ('eec86b56-b6e4-60ee-10ff-9532551a36da', N'CARVING', N'artifact-故雕000309N000000000', N'葫蘆番蓮紋瓶－縮小複製品', N'從一塊材料到一件作品，中間藏著工匠無數次判斷。這件「葫蘆番蓮紋瓶」縮小複製品，把這份手藝凝聚成耐看的收藏。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：雕刻' + NCHAR(10) + N'年代：清 康熙' + NCHAR(10) + N'商品尺寸：高 11.75 公分、外徑 5.75 公分' + NCHAR(10) + N'原作尺寸：高 23.5 公分、外徑 11.5 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'葫蘆番蓮紋瓶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'此件康熙年間模製葫蘆長頸瓶，口沿鑲玳瑁邊，瓶身四股模製稜線隱約可見，紋飾由上而下分層環繞，包括口沿下方環繞一圈回紋，頸部飾以如意雲紋，肩部為朵花卷草紋，腹部為纏枝番蓮紋，器腹下方飾一圈如意雲頭紋。圈足中央有模製單線方框「康熙賞玩」楷款，圈足上有楷書陰刻填綠乾隆四十六年（1781）御題詩，盛讚葫蘆器渾然天成之美，並刻有陽文填朱地「古香」印。此瓶整體造形典雅，線條圓轉，深雕淺刻層次井然，足見雕模技藝與範製過程之精審，結合葫蘆樸質與造化巧妙，是康熙御製葫蘆器之經典，亦反映出康熙皇帝在藝術品鑒創製中所注入格物研精的實驗精神。', 700.00, 20, N'/media/catalog/carving/故雕000309N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/62528?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1320000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 11.75 公分、外徑 5.75 公分', '4a4c92a6-c9df-24fc-e9db-57e5dcd3ceb5'),
    ('6418f690-6638-517c-b2fa-9748c10e46ec', N'CERAMIC', N'artifact-故瓷018151N000000000', N'蠔山瓷碗－縮小複製品', N'從日常器用到典藏珍品，陶瓷記錄了不同時代對生活之美的想像。這件「蠔山瓷碗」縮小複製品，讓這段美感自然融入展示空間。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：陶瓷' + NCHAR(10) + N'年代：南宋' + NCHAR(10) + N'商品尺寸：碗徑 7.75 公分' + NCHAR(10) + N'原作尺寸：碗徑 15.5 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'蠔山瓷碗 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'由生蠔殼與一侈口平底碗組成，碗全器施青釉，內壁有流釉痕跡，嵌於蠔殼口上，利用蠔殼的不規則邊緣固定；附有三足木座一只，以樹根雕琢而成，保留原有外形，僅於足部有明顯定形修飾的痕跡。蠔殼可以側邊方向置於木座上。', 1000.00, 20, N'/media/catalog/ceramic/故瓷018151N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/61042?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1320000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'碗徑 7.75 公分', '327eeab1-bbb1-e08d-f5fd-d9696bb2b062'),
    ('327ab03d-a4b4-ccf4-3919-97fb42b8077f', N'PAINTING', N'artifact-故畫003768N000000000', N'御筆寫生 冊－縮小複製品', N'從構圖、線條到題材安排，書畫總有值得慢慢閱讀之處。以御筆寫生 冊為靈感製作的縮小複製品，讓欣賞不必受距離限制。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：繪畫' + NCHAR(10) + N'年代：清 乾隆' + NCHAR(10) + N'商品尺寸：長 7.35 公分、寬 3.3 公分' + NCHAR(10) + N'原作尺寸：長 14.7 公分、寬 6.6 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'御筆寫生 冊 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'紙本冊頁，梵夾式。頁首尾托底面蓋有「五福五代堂古稀天子寶」、「八徵耄念之寶」朱文印，內頁四幅水墨小品，老幹，有「垂露」、「乾隆宸翰」朱文章；野芳，有「日監在玆」、「用筆在心」朱白文各一；勁節，「寓意于物」、「寫竹學心虛」朱白文各一；幽香，「卍有同春」、「乾隆」朱文章。本件有「御筆寫生」填金款木托盤。', 790.00, 20, N'/media/catalog/painting/故畫003768N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/49808?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'長 7.35 公分、寬 3.3 公分', '90c22ea1-79d8-6139-f2b8-f0d6ef137f5a'),
    ('40aa4deb-2b02-f634-7c91-99a04a0b54c0', N'JADE', N'artifact-故玉005770N000000000', N'玉穀紋璧－縮小複製品', N'一件玉器，可以寄託品味，也能收藏一段時代記憶。以玉穀紋璧為靈感製作的縮小複製品，為展示空間添上一份沉靜氣質。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：玉器' + NCHAR(10) + N'年代：戰國中晚期' + NCHAR(10) + N'商品尺寸：徑 2.35 公分' + NCHAR(10) + N'原作尺寸：徑 4.7 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'玉穀紋璧 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'玉質，邊緣局部有深褐色沁，部份帶絲狀褐斑。圓整，有廓，器面浮雕穀紋。穀紋左、右旋皆有，排列隨意，且大小不一。現收儲於多寶格中。', 1470.00, 20, N'/media/catalog/jade/故玉005770N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/71680?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'徑 2.35 公分', '9614cea7-2a9e-6c28-a26e-a61bef7c2c4a'),
    ('0386d3e7-9eeb-20b2-39b9-99b324abe6f9', N'CARVING', N'artifact-贈雕000122N000000000', N'牙雕鳥－縮小複製品', N'雕刻是在材料上不斷取捨，最後留下最想表達的形貌。這件「牙雕鳥」縮小複製品，讓刀工與構思成為可以近距離欣賞的焦點。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：雕刻' + NCHAR(10) + N'年代：戰國至漢' + NCHAR(10) + N'商品尺寸：長 0.85 公分、高 0.55 公分' + NCHAR(10) + N'原作尺寸：長 1.7 公分、高 1.1 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'牙雕鳥 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'圓雕立鳥，刀法簡率；身軀正中豎穿一小孔，可供繫掛。此器可能是串飾之一。', 1430.00, 20, N'/media/catalog/carving/贈雕000122N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/45351?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1320000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'長 0.85 公分、高 0.55 公分', 'ada28f6a-d432-28fe-948f-e5ea39ee5727'),
    ('de9882a2-c8fe-3dff-904f-9aad26cc5f05', N'CERAMIC', N'artifact-贈瓷000470N000000000', N'昇天圖畫像磚－縮小複製品', N'從日常器用到典藏珍品，陶瓷記錄了不同時代對生活之美的想像。這件「昇天圖畫像磚」縮小複製品，讓這段美感自然融入展示空間。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：陶瓷' + NCHAR(10) + N'年代：西漢' + NCHAR(10) + N'商品尺寸：長 80.5 公分、寬 27 公分、高 8.75 公分' + NCHAR(10) + N'原作尺寸：長 161.0 公分、寬 54.0 公分、高 17.5 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'昇天圖畫像磚 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'畫像磚為嵌砌墓室或祠堂的圖像磚，最晚在戰國時期已出現，並流行各地。本件灰陶空心畫像磚，紋飾分兩層：上層等距分佈三隻朱雀及二隻仙鶴，雀鳥單腳佇立，雙翅平展，回眸，後尾上揚，體態優美；仙鶴仰首，作鳴狀。下層，一樹居中，樹枝對稱，勾連交叉，果似茄型，樹上朱雀一隻。樹的兩側各有渾厚雄壯的帶翼天馬及長腿鶴鳥。畫像磚的上下兩側各有一組菱形紋，整體紋飾佈局疏朗對稱。紋飾輪廓線內凹，為陰刻畫像磚，線條簡練流暢，呈現莊嚴肅穆的氛圍。此類畫像磚出現在西漢早期河南洛陽一帶，河南省博物館及加拿大安大略博物館皆有類似收藏。', 1130.00, 20, N'/media/catalog/ceramic/贈瓷000470N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/43500?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1320000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'長 80.5 公分、寬 27 公分、高 8.75 公分', '484e0014-4d36-4fd6-2d3a-61fdd7594229'),
    ('9439ae96-da6a-cda3-5715-9b3792280512', N'PAINTING', N'artifact-故畫00026200000', N'元戴淳匡廬圖　軸－縮小複製品', N'遠看整體氣勢，近看筆墨細節，書畫能陪人反覆觀看。這件「元戴淳匡廬圖　軸」縮小複製品，為牆面或展示角落留下一段雅致風景。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：繪畫' + NCHAR(10) + N'年代：元仁宗延祐五年（1318）' + NCHAR(10) + N'商品尺寸：58.55 × 25.45 公分' + NCHAR(10) + N'原作尺寸：117.1 × 50.9 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'元戴淳匡廬圖　軸 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'戴淳（活動於西元十四世紀初），字厚夫，錢塘（今浙江杭州）人，擅長山水畫。老樹挺拔，山石險峻，高崖一層一層相疊著。峰頂築有古寺樓閣，建築物的描繪，方勁穩重，山石的形狀，也近乎方形。石紋多用枯筆皴擦，頗有蒼老而穩健的感覺。明末清初的龔賢，在畫 風上與這幅畫有極相近之處。', 840.00, 20, N'/media/catalog/painting/故畫00026200000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/730?dep=P', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'58.55 × 25.45 公分', '754c28eb-791f-b051-d3fd-2375ba7819e4'),
    ('ac2e39ef-5949-54d4-3a5e-9bf82c584b68', N'CARVING', N'artifact-贈雕000132N000000000', N'骨雕填彩管－縮小複製品', N'不同材料有不同個性，好的雕刻懂得順勢而為。以骨雕填彩管為靈感製作的縮小複製品，保留一份因材施藝的工藝趣味。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：雕刻' + NCHAR(10) + N'年代：西漢' + NCHAR(10) + N'商品尺寸：高 1.5 公分、徑 1.05 公分' + NCHAR(10) + N'原作尺寸：高 3.0 公分、徑 2.1 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'骨雕填彩管 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'截取一段獸骨，器表細線陰刻紋飾，中央下方飾向左奔行之四獸馳於地，上方飾兩組飛禽翔於天，山與雲錯落其間；器之上下緣各飾兩道三角形紋，一道為正三角形，另一道則為倒三角形；下緣又飾一圈菱形紋。三角形、菱形、走獸、飛禽等紋飾輪廓內皆滿刻斜陰線，並填紅或黑彩。此器紋飾刻工流暢，紋樣與西漢漆器上陰刻或彩繪紋飾相類。其功能或與車馬有關。', 1120.00, 20, N'/media/catalog/carving/贈雕000132N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/45361?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1320000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 1.5 公分、徑 1.05 公分', 'd177ebf2-0dab-43be-66e8-b8cb15e3e1db'),
    ('462be78a-c679-adcd-a316-9d71fad5609a', N'COIN', N'artifact-購錢005243N000000000', N'祥符元寶－縮小複製品', N'方寸之間，裝得下年代、制度與人們往來交易的痕跡。這件「祥符元寶」縮小複製品，從一枚錢幣打開認識歷史的新角度。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：錢幣' + NCHAR(10) + N'年代：北宋' + NCHAR(10) + N'商品尺寸：待測量' + NCHAR(10) + N'原作尺寸：待測量' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'祥符元寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'銅質。方孔圓錢，正面有楷書：「祥符元寶」四字，背面無文。', 710.00, 20, N'/media/catalog/coin/購錢005243N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/14581?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1340000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'待測量', '0ae033cc-2984-45bf-89f6-f583493220bb'),
    ('85fe1355-876f-1aeb-4fe6-9de5fc1b0217', N'PAINTING', N'artifact-故畫00353800015', N'明人便面畫冊（二）　冊　明項德裕山水－縮小複製品', N'畫面不只記錄所見，也保存創作者觀看世界的方式。這件「明人便面畫冊（二）　冊　明項德裕山水」縮小複製品，邀你把這份想像帶進自己的空間。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：繪畫' + NCHAR(10) + N'年代：明神宗萬曆十二年（1584）' + NCHAR(10) + N'商品尺寸：8.2 × 24.9 公分' + NCHAR(10) + N'原作尺寸：16.4 × 49.8 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'明人便面畫冊（二）　冊　明項德裕山水 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'項德裕（生卒年不詳，活躍於十六世紀後半），為項元汴之姪。其父元淇為元汴長兄，與陳淳交往甚密，亦為風雅人物。德裕長於書香世家，亦能書畫藝事。然作品流傳甚少，難得一見。' + NCHAR(13) + NCHAR(10) + N'　景作江畔高山，雲光樹影。雖寥寥幾筆，含蓄有韻，別有意趣。款識為「甲申（一五八四）夏仲。項德裕倣米南宮筆意」。本幅選自「明人便面畫冊」第二冊第十五開。', 640.00, 20, N'/media/catalog/painting/故畫00353800015/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/18434?dep=P', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1360000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'8.2 × 24.9 公分', '24164dce-e9b2-8f15-7ef9-6c8184c39803'),
    ('48adb77d-e8b3-f7bf-cc7a-a02e9c017dc2', N'CERAMIC', N'artifact-贈瓷000466N000000000', N'昇天圖畫象磚－縮小複製品', N'一件陶瓷，可以從遠處看整體，也值得靠近欣賞質感。這件「昇天圖畫象磚」縮小複製品，為收藏角落留下一份安定而耐看的風景。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：陶瓷' + NCHAR(10) + N'年代：東漢' + NCHAR(10) + N'商品尺寸：長 46.5 公分、寬 17.1 公分、高 6 公分' + NCHAR(10) + N'原作尺寸：長 93.0 公分、寬 34.2 公分、高 12.0 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'昇天圖畫象磚 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'直立型空心畫像磚，兩面紋飾類似。中間段方格紋五行，內飾圓形釘紋。磚的上下兩端有獸面紋、重簷單闕及山林狩獵紋各一行，每行以同一印模嵌印三次成列。獸面，大眼、梨形鼻、皺紋面容，嘴成一銜環，內有「夫」字；手掌置兩側，模樣駭人，應為守衛陰宅的辟邪型像。重簷單闕為天門，簷上仙鶴佇立。闕頂左右兩側排成三角型的牽牛星座。闕前置水桶或井；柱上栓天馬，頸掛食袋。帶翼天馬為墓主入天門的載具，在此或描繪墓主人已入天門，昇天成仙。闕的兩側種植三角錐型的靈木柏樹，有長生不老，子孫興旺的意涵。山林騎射，勇士回首，奮力張弓射鳥，並有「十八」、「百」、「圼」嵌字；「圼」為讖緯說中天上二十八星宿之一。 漢人崇尚星宿卜掛，天文圖像常作為河南地區畫像磚的紋飾，是漢代天文學的記實。是否與墓葬儀禮或墓主的天命有直接關係，尚有待檢視。畫像磚上紋飾密集，共以四種方型小模重複在磚坏上密集排印。紋飾輪廓線內凹，為陰刻印紋；同時在陰刻的輪廓內凸出陽線的細部，是東漢時期畫像磚紋飾工藝特點。河南鄭州、新鄭一帶常見出土。河南省博物館即藏有鄭州市出土，類似院藏的作品。', 1230.00, 20, N'/media/catalog/ceramic/贈瓷000466N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/43496?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1320000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'長 46.5 公分、寬 17.1 公分、高 6 公分', '347ca33e-c7c5-4165-a58c-17d8237b210c'),
    ('10f46334-595c-4d05-faf4-a3b69b2ae383', N'BRONZE', N'artifact-故銅002423N000000000', N'史觶－縮小複製品', N'金屬與火塑成器物，歲月再替表面留下時間的痕跡。這件「史觶」縮小複製品，把銅器沉穩厚實的存在感帶進收藏空間。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：銅器' + NCHAR(10) + N'年代：西周早期' + NCHAR(10) + N'商品尺寸：高 6.7 公分、口徑長 4.3 公分、寬 3.8 公分' + NCHAR(10) + N'原作尺寸：高 13.4 公分、口徑長 8.6 公分、寬 7.6 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'史觶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'截面呈橢圓形，侈口，束頸，鼓腹，圜底，圈足外撇，近底處起臺。口沿下及器腹飾高浮雕獸面紋，兩側夾飾倒夔紋，頸部及圈足各飾對首夔紋。此器紋飾及高圈足的特點，亦見於安陽殷墟郭家莊出土〈亞址觶〉（M160：126）以及陝西寶雞戴家灣出土〈守父辛觶〉。銘文在器內壁。此族氏銘文青銅器散見於河南鄭州、山東泗水等地墓葬出土青銅器，亦多見於山東前掌大墓地。清宮配有木座，臺面篆書「乾隆御賞」，底部楷書題名「周史觶」。另貼有清宮黃籤「養心殿」、「五元 三十六號」。', 1400.00, 20, N'/media/catalog/bronze/故銅002423N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/62139?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1300000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 6.7 公分、口徑長 4.3 公分、寬 3.8 公分', 'c44b6c3e-340e-0b34-1af5-2f4209b66c1d'),
    ('75cd3b41-7e00-c177-a4f2-a4cf6bdf1536', N'CERAMIC', N'artifact-故瓷018326N000000000', N'青花西廂記鼻煙壺－縮小複製品', N'泥土經過塑形與窯火，才成為能被長久欣賞的器物。這件「青花西廂記鼻煙壺」縮小複製品，把陶瓷溫雅耐看的氣質帶到眼前。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：陶瓷' + NCHAR(10) + N'年代：清 雍正' + NCHAR(10) + N'商品尺寸：高 2.4 公分、寬 2.05 公分' + NCHAR(10) + N'原作尺寸：高 4.8 公分、寬 4.1 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'青花西廂記鼻煙壺 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'青花人物雙繫扁壺式鼻煙壺，獸首雙繫扁壺，雙面繪西廂人物故事，底有楷書「雍正年製」，帶銅嵌珍珠蓋，附有寶藍繡菱格錦囊。', 750.00, 20, N'/media/catalog/ceramic/故瓷018326N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/61185?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1330000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 2.4 公分、寬 2.05 公分', '9bc03dde-df7c-e6dc-b5cc-e5c74d62a71b'),
    ('1e560a5c-3505-3066-91b0-a63852d20b68', N'JADE', N'artifact-故玉006244N000000000', N'玉雲紋管－縮小複製品', N'玉石經過琢磨才成器，也在流傳中留下不同時代的眼光。玉雲紋管化為縮小複製品，讓這份溫潤含蓄的玉器之美走進日常。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：玉器' + NCHAR(10) + N'年代：春秋早期' + NCHAR(10) + N'商品尺寸：高 2.95 公分' + NCHAR(10) + N'原作尺寸：高 5.9 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'玉雲紋管 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'上下的回紋為後代所加。', 1460.00, 20, N'/media/catalog/jade/故玉006244N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/57366?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 2.95 公分', '41189571-1b7a-78e8-bf35-68f91177df38'),
    ('5142da42-1d75-0b64-7702-a75a1308466c', N'CARVING', N'artifact-贈雕000165N000000000', N'骨雕填彩斜口筒形器－縮小複製品', N'從一塊材料到一件作品，中間藏著工匠無數次判斷。這件「骨雕填彩斜口筒形器」縮小複製品，把這份手藝凝聚成耐看的收藏。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：雕刻' + NCHAR(10) + N'年代：東漢' + NCHAR(10) + N'商品尺寸：高 3.6 公分、徑 2 公分' + NCHAR(10) + N'原作尺寸：高 7.2 公分、徑 4.0 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'骨雕填彩斜口筒形器 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'全器取一段骨製成，剖面呈橢圓形，一端緣平齊，一端斜削，使全器呈斜口筒形。器表陰刻細線抽象鳥紋或填紅或填黑。在新石器時代晚期的紅山文化中曾一再出現斜口筒形玉器，其功能未定。在內蒙古漢代墓葬中也曾出土類似的斜口筒形骨管；此件骨器，器形規整，表面又滿刻陰線紋飾，或填紅彩，或填黑色，其製作時代或許晚至東漢。', 1160.00, 20, N'/media/catalog/carving/贈雕000165N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/45393?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1320000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 3.6 公分、徑 2 公分', '7a9c0146-d4ee-81d9-c39e-a2abf667e599'),
    ('b59ed916-7749-f320-bbde-a8124211a089', N'ENAMEL', N'artifact-故琺000996N000000000', N'銅胎畫琺瑯花草五毒盒－縮小複製品', N'琺瑯以釉料與燒製換來鮮明而細緻的層次。這件「銅胎畫琺瑯花草五毒盒」縮小複製品，把這份講究工序的華美濃縮成展示亮點。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：琺瑯器' + NCHAR(10) + N'年代：清 乾隆' + NCHAR(10) + N'商品尺寸：長 3.3 公分、寬 4.35 公分、高 1.7 公分；盒蓋高 0.6 公分' + NCHAR(10) + N'原作尺寸：長 6.6 公分、寬 8.7 公分、高 3.4 公分；盒蓋高 1.2 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'銅胎畫琺瑯花草五毒盒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'花形小盒，子母口，全器呈花形，蓋頂、器底和口沿處皆鑲金邊。全器畫琺瑯為飾，粉藍色底，蓋面繪五個由粉、黃、藍、綠構成的幾何稜格紋，及蠍、蛇、蜈蚣、蟾蜍、蜘蛛五毒，間飾各式花草。蓋沿及盒身繪有黃褐色幾何稜紋，飾桃實、荷花等花草果實。器內壁施藍綠釉。白底朱色雙方框書「乾隆年製」四字楷款。', 900.00, 20, N'/media/catalog/enamel/故琺000996N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/61938?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1340000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'長 3.3 公分、寬 4.35 公分、高 1.7 公分；盒蓋高 0.6 公分', '51c217fa-b4f4-34c8-b44e-fa7026619f29'),
    ('ac256002-e32c-aa8a-90ae-a8261b0f50ae', N'COIN', N'artifact-購錢004789N000000000', N'熙寧元寶－縮小複製品', N'錢幣曾在人群之間流轉，如今也成為辨認時代的重要線索。以熙寧元寶為靈感製作的縮小複製品，小巧卻很有故事。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：錢幣' + NCHAR(10) + N'年代：北宋' + NCHAR(10) + N'商品尺寸：待測量' + NCHAR(10) + N'原作尺寸：待測量' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'熙寧元寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'銅質。方孔圓錢，正面有楷書：「熙寧元寶」四字，背面無文。', 610.00, 20, N'/media/catalog/coin/購錢004789N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/14127?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1340000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'待測量', 'a2daa79a-cd43-3060-cad3-abaa1db4da19'),
    ('264ba794-84e8-e166-0416-a9a6306bfb0b', N'ENAMEL', N'artifact-故琺000882N000000000', N'銅胎畫琺瑯芙蓉紋圓盒－縮小複製品', N'琺瑯以釉料與燒製換來鮮明而細緻的層次。這件「銅胎畫琺瑯芙蓉紋圓盒」縮小複製品，把這份講究工序的華美濃縮成展示亮點。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：琺瑯器' + NCHAR(10) + N'年代：清 乾隆' + NCHAR(10) + N'商品尺寸：高 2.15 公分、口徑 3.3 公分' + NCHAR(10) + N'原作尺寸：高 4.3 公分、口徑 6.6 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'銅胎畫琺瑯芙蓉紋圓盒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'銅胎，覆缽式蓋與器身對合成扁圓盒。蓋與器身對合處，以及圈足各飾一圈白地藍色回紋。盒內施淺藍釉；蓋頂繪白色線圈，飾以盛開之紅芙蓉；蓋面與器身各飾四朵紅藍顏色的折枝芙蓉，間以折枝花卉。盒底色白並有一藍方框雙行「乾隆年製」楷款。', 890.00, 20, N'/media/catalog/enamel/故琺000882N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/61861?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1340000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 2.15 公分、口徑 3.3 公分', '46e7cf98-7eda-c06e-3269-fb7d92e00937'),
    ('34287d56-ad6d-e7a8-65ca-a9b45ee3df75', N'LACQUER', N'artifact-故漆000309N000000000', N'剔紅雲龍紋碗托－縮小複製品', N'漆藝講究耐心，也讓器物擁有難以取代的深沉質感。這件「剔紅雲龍紋碗托」縮小複製品，是一件越看越能發現味道的收藏。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：漆器' + NCHAR(10) + N'年代：清 乾隆' + NCHAR(10) + N'商品尺寸：高 8.05 公分、口徑 10.4 公分、足徑 4.5 公分' + NCHAR(10) + N'原作尺寸：高 16.1 公分、口徑 20.8 公分、足徑 9.0 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'剔紅雲龍紋碗托 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'雕漆碗托，色硃紅。器作高圈足葵花式六瓣托盤，上接中空無底圓形碗。碗以天文錦地為地，上雕穿雲龍紋，托座內外與圈足則滿飾雲紋，碗與托盤口緣、圈足皆飾回紋一周。圈足內有填金楷款「大清乾隆年製」、「仁」。碗托與雕漆碗(故漆306)成組。', 770.00, 20, N'/media/catalog/lacquer/故漆000309N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/18231?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 8.05 公分、口徑 10.4 公分、足徑 4.5 公分', '36af0548-9550-f01e-6ef4-225669b2c943'),
    ('c6993e55-176b-6cde-af94-aa027114f0da', N'BRONZE', N'artifact-故銅000443N000000000', N'錢引庫檢察印－縮小複製品', N'先看整體輪廓，再找製作與歲月留下的細節，銅器總能讓人多停留一會兒。這件「錢引庫檢察印」縮小複製品，讓這份歷史感更貼近日常。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：銅器' + NCHAR(10) + N'年代：西夏' + NCHAR(10) + N'商品尺寸：高 2.85 公分、長 2.25 公分、寬 2.25 公分' + NCHAR(10) + N'原作尺寸：高 5.7 公分、長 4.5 公分、寬 4.5 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'錢引庫檢察印 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'方形，板狀，橛鈕，印面作陽文，篆體六字：「錢引庫檢察印」。配有素淨的木方盒，盒內另裝盛呈文一紙，考訂該印源流。此印得自烏魯木齊屯田墾地出土，收於《西清續鑑‧甲編》附錄，圖說內容較呈文精簡。據考，《宋史‧食貨志》載北宋崇寧以前使用「錢引」紙幣，對照〈職官志〉說明交引庫負責給印出納，以及左藏庫設有「提轄檢察官」，可知此印是用於錢鈔發行的認證。然而，宋代疆域未及烏魯木齊，與歷代官印相比，形制粗率，遂認為此印乃西夏學習宋制之遺存。 現就此印用朱文、印鈕無穿孔的形式，與西夏官印使用白文，且保留古印鈕穿孔的特色不同。宋制銅印在烏魯木齊出土，或有其他傳世緣由，現已不得而知。', 1090.00, 20, N'/media/catalog/bronze/故銅000443N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/62120?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1310000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 2.85 公分、長 2.25 公分、寬 2.25 公分', '8c3dbed1-f29c-c1e3-dbcf-43a45baa94dd'),
    ('0b0882ae-f601-be50-84fc-aac1764ba2a7', N'BRONZE', N'artifact-購銅000038N000000000', N'提梁銗鏤－縮小複製品', N'金屬與火塑成器物，歲月再替表面留下時間的痕跡。這件「提梁銗鏤」縮小複製品，把銅器沉穩厚實的存在感帶進收藏空間。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：銅器' + NCHAR(10) + N'年代：西漢' + NCHAR(10) + N'商品尺寸：通高 18.8 口徑 4.1 公分' + NCHAR(10) + N'原作尺寸：通高 18.8 口徑 8.2 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'提梁銗鏤 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'器身圓鼓，圜底，三足作熊形，有提樑，呈雙龍形。器蓋有三獸形紐，取下倒置，可作容器使用。器內有殘存碎骨，與器身朽聯一塊。', 1200.00, 20, N'/media/catalog/bronze/購銅000038N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/71945?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1300000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'通高 18.8 口徑 4.1 公分', 'bcd2c835-b050-c74b-9a7f-5ae8dc7de0c6'),
    ('794734d9-bf60-487a-548a-aaca70e17f9b', N'ENAMEL', N'artifact-故琺000838N000000000', N'掐絲琺瑯梵文碟－縮小複製品', N'琺瑯以釉料與燒製換來鮮明而細緻的層次。這件「掐絲琺瑯梵文碟」縮小複製品，把這份講究工序的華美濃縮成展示亮點。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：琺瑯器' + NCHAR(10) + N'年代：清 乾隆' + NCHAR(10) + N'商品尺寸：口徑 7.5 公分' + NCHAR(10) + N'原作尺寸：口徑 15.0 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'掐絲琺瑯梵文碟 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'侈口，折沿，淺壁，平底，圈足。全器淺藍地，口沿寫有一圈梵文，內底有卷鬚錦，中心有一由七個梵文及三個符號組成的「十相自在」吉祥紋飾，盤內外壁為朵雲紋間飾佛教七珍、八寶。底部有陰刻「乾隆年製」四字雙行楷書雙方框款。', 770.00, 20, N'/media/catalog/enamel/故琺000838N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/61824?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1340000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'口徑 7.5 公分', 'adcb67ae-a8e0-7446-6a0f-2cff913173eb'),
    ('52c9c146-3fcc-9405-6ff3-aadea5f183f1', N'JADE', N'artifact-故玉004342N000000000', N'玉獸紋劍璏－縮小複製品', N'欣賞玉器，不只看材質，也看工匠如何順著天然質地雕琢成形。玉獸紋劍璏縮小複製品，適合放在近處慢慢看、慢慢品味。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：玉器' + NCHAR(10) + N'年代：西漢中晚期' + NCHAR(10) + N'商品尺寸：長 4.1 公分、寬 1.2 公分、高 0.95 公分' + NCHAR(10) + N'原作尺寸：長 8.2 公分、寬 2.4 公分、高 1.9 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'玉獸紋劍璏 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'本器為劍璏，玉質，局部有黃褐斑，拋光細緻，溫潤光亮。正面隱隱有扭轉爬行神獸。側面有呈矩形的貫穿方孔，孔內側遺留線具拉切去料所形成之平行線痕，為漢代玉器製作常用技巧。西漢中晚期之際海昏侯墓也出土過與本器相似的玉劍璏。從紋飾題材、風格、形制、玉質特徵與雕刻技巧來看，屬西漢中晚期作品。本器存放在院藏「紫檀雕蟠龍方盒百什件」（故雜877）中。', 1290.00, 20, N'/media/catalog/jade/故玉004342N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/71713?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'長 4.1 公分、寬 1.2 公分、高 0.95 公分', '3bbdb8f0-32c2-362c-fbb5-7481ea4ee461'),
    ('fb2e60d4-2a6d-7ef8-9713-ac029f995925', N'PAINTING', N'artifact-故畫003856N000000000', N'御筆墨梅 卷－縮小複製品', N'從構圖、線條到題材安排，書畫總有值得慢慢閱讀之處。以御筆墨梅 卷為靈感製作的縮小複製品，讓欣賞不必受距離限制。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：繪畫' + NCHAR(10) + N'年代：清 乾隆' + NCHAR(10) + N'商品尺寸：長 24 公分、高 4.2 公分' + NCHAR(10) + N'原作尺寸：長 48.0 公分、高 8.4 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'御筆墨梅 卷 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'小手卷，卷外楷字題籤：「御筆墨梅」。引首「花信先春」四楷字，本幅為清高宗在乾隆三十三年（1768）所繪折枝梅花一枝，空白的背景中，簡單地繪出含苞與盛開的梅花，的確傳達了冬日生機潛伏的寂靜中，一朵盛開梅花所帶來的春消息。', 630.00, 20, N'/media/catalog/painting/故畫003856N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/62023?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'長 24 公分、高 4.2 公分', '3bd35178-a0b3-3405-9899-a697f4e5277d'),
    ('917a8261-4555-ad20-a218-accc3818ecb8', N'PAINTING', N'artifact-故畫003772N000000000', N'御筆寫生 冊－縮小複製品', N'一幅畫最迷人的地方，是每次觀看都可能發現不同線索。這件「御筆寫生 冊」縮小複製品，把畫面的節奏與意境帶進日常空間。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：繪畫' + NCHAR(10) + N'年代：清 乾隆' + NCHAR(10) + N'商品尺寸：長 5 公分、寬 3.4 公分、厚 0.55 公分' + NCHAR(10) + N'原作尺寸：長 10 公分、寬 6.8 公分、厚 1.1 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'御筆寫生 冊 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'紙本水墨，冊頁，梵夾式，四開，木質封皮楷刻填綠彩「御筆寫生」四字。內有清高宗水墨畫作四幅，其繪寫對象依次為松樹、竹子、梅花、蘭花，或就景寫生，或取法元代畫家倪瓚而創作，更有清高宗於三希堂中的乘興之作。幅上除了清高宗自題外，尚有蔣溥、介福、汪由敦、觀保等當朝臣宦之題記。', 660.00, 20, N'/media/catalog/painting/故畫003772N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/48308?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'長 5 公分、寬 3.4 公分、厚 0.55 公分', '3178c807-c247-0c06-1946-19753255cc0c'),
    ('0da11587-01bb-671f-bcbf-acf977fd6cb2', N'LACQUER', N'artifact-故漆000340N000000000', N'剔紅天馬紋長方盒－縮小複製品', N'一道漆、一段等待，漆器的深度來自層層累積的工序。這件「剔紅天馬紋長方盒」縮小複製品，把這份沉靜而講究的工藝氣質帶進日常。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：漆器' + NCHAR(10) + N'年代：清 乾隆' + NCHAR(10) + N'商品尺寸：長 12.85 公分、寬 8 公分、高 3.5 公分' + NCHAR(10) + N'原作尺寸：長 25.7 公分、寬 16.0 公分、高 7.0 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'剔紅天馬紋長方盒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'剔紅，長方形。盒面雕波濤紋，上有龍馬五，四周亦雕波濤紋。底刻「大清乾隆年製」楷款。底裡均漆黑光。', 860.00, 20, N'/media/catalog/lacquer/故漆000340N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/48315?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'長 12.85 公分、寬 8 公分、高 3.5 公分', '7c95371b-5d9c-a5c3-5e1c-0355f611e1bd'),
    ('2d767fd8-5e4d-7b53-575c-ad1247e1bb25', N'JADE', N'artifact-故玉006596N000000000', N'玉帶飾－縮小複製品', N'欣賞玉器，不只看材質，也看工匠如何順著天然質地雕琢成形。玉帶飾縮小複製品，適合放在近處慢慢看、慢慢品味。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：玉器' + NCHAR(10) + N'年代：金至元' + NCHAR(10) + N'商品尺寸：長 1.65 公分、寬 0.7 公分' + NCHAR(10) + N'原作尺寸：長 3.3 公分、寬 1.4 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'玉帶飾 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'玉質，局部帶赭斑。全器琢成一帶飾，琢有橫向扁平方孔。玉正面飾有花卉紋。', 990.00, 20, N'/media/catalog/jade/故玉006596N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/57668?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'長 1.65 公分、寬 0.7 公分', '8188a4f2-c82f-49a8-38b0-8c56139c23e1'),
    ('6db4464f-7de5-3ad6-8292-aecd3d4e8abb', N'COIN', N'artifact-購錢004711N000000000', N'祥符元寶－縮小複製品', N'錢幣曾在人群之間流轉，如今也成為辨認時代的重要線索。以祥符元寶為靈感製作的縮小複製品，小巧卻很有故事。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：錢幣' + NCHAR(10) + N'年代：北宋' + NCHAR(10) + N'商品尺寸：待測量' + NCHAR(10) + N'原作尺寸：待測量' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'祥符元寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'銅質。方孔圓錢，正面有楷書：「祥符元寶」四字，背面無文。', 760.00, 20, N'/media/catalog/coin/購錢004711N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/14049?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1340000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'待測量', '7ca40530-4244-f2cb-df49-46a36e6f9675'),
    ('6768ffc1-aba8-b518-6fa4-aee64947937b', N'CERAMIC', N'artifact-故瓷007719N000000000', N'白瓷印花獅戲圖蔗段式洗－縮小複製品', N'陶瓷的樂趣，在於輪廓、表面與燒製效果彼此呼應。以白瓷印花獅戲圖蔗段式洗為靈感製作的縮小複製品，適合留在身邊慢慢發現細節。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：陶瓷' + NCHAR(10) + N'年代：金至元' + NCHAR(10) + N'商品尺寸：高 2.4 公分、口徑 11.5 公分、底徑 9 公分' + NCHAR(10) + N'原作尺寸：高 4.8 公分、口徑 23.0 公分、底徑 18.0 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'白瓷印花獅戲圖蔗段式洗 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'侈口深壁洗，斜壁微弧，腹下以陰弦紋一道斜收為平底，口沿露胎；釉汁濃稠偏黃，外壁飾凸弦紋一道，作蔗段式。器裡以印花為飾。內壁作六瓣格，以細凸線為框界，分印折枝桃、菊、牡丹花叢。盤底面印雄獅一隻，巨眼、大鼻，雙眉間作一「王」字，髮鬣、尾作綣毫如球狀堆疊雜以細線鬚毛，身軀肌理雄健。口銜綬帶，帶端繫一繡球，縧帶繁麗。韓國新安沉船（約 1323 年）有相似作品。', 870.00, 20, N'/media/catalog/ceramic/故瓷007719N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/34757?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1320000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 2.4 公分、口徑 11.5 公分、底徑 9 公分', 'eb3d79b7-0009-6e91-d173-113badf28224'),
    ('e5e7c817-ec14-dfe9-8e80-b12fc52ebcd7', N'JADE', N'artifact-故玉005934N000000000', N'柄形器－縮小複製品', N'從光澤、質地到琢磨留下的細節，玉器總有值得反覆欣賞之處。柄形器縮小複製品，邀你用更親近的距離重新認識它。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：玉器' + NCHAR(10) + N'年代：商至西周' + NCHAR(10) + N'商品尺寸：長 4.45 公分' + NCHAR(10) + N'原作尺寸：長 8.9 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'柄形器 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'紋飾和器形是明代後改。', 1660.00, 20, N'/media/catalog/jade/故玉005934N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/57075?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1340000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'長 4.45 公分', 'c14982eb-80b2-3232-4562-385782c1ae13'),
    ('7b2acaa0-6e81-b28d-4a8d-b15d54c54b80', N'CERAMIC', N'artifact-贈瓷000134N000000000', N'灰陶加彩灶－縮小複製品', N'陶瓷的樂趣，在於輪廓、表面與燒製效果彼此呼應。以灰陶加彩灶為靈感製作的縮小複製品，適合留在身邊慢慢發現細節。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：陶瓷' + NCHAR(10) + N'年代：東漢' + NCHAR(10) + N'商品尺寸：長 10.25 公分、寬 8.5 公分、高 3.25 公分' + NCHAR(10) + N'原作尺寸：長 20.5 公分、寬 17.0 公分、高 6.5 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'灰陶加彩灶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'陶灶，灶體略近梯形，短底作弧角，使整器類於風字硯樣式。灶上設有三個火眼（釜孔），火眼大致等大。無底。外壁施青釉，色調偏黃，多見剝落，外壁釉上筆繪類雲氣之流線紋為飾，由於多處剝落，已無法窺得紋飾全貌', 1040.00, 20, N'/media/catalog/ceramic/贈瓷000134N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/45542?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1320000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'長 10.25 公分、寬 8.5 公分、高 3.25 公分', '042e23e0-d474-5873-b384-36dc67e28caf'),
    ('40d01f0d-d087-43ed-d906-b22b44c949d4', N'CARVING', N'artifact-贈雕000186N000000000', N'牙簪－縮小複製品', N'從一塊材料到一件作品，中間藏著工匠無數次判斷。這件「牙簪」縮小複製品，把這份手藝凝聚成耐看的收藏。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：雕刻' + NCHAR(10) + N'年代：宋至元' + NCHAR(10) + N'商品尺寸：長 5.05 公分' + NCHAR(10) + N'原作尺寸：長 10.1 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'牙簪 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'細長條形，剖面呈圓形，一端成鈍尖針形，另一端中腰細縮，後段呈長橢圓形，末端鈍尖。此器依稀可見紅彩遺痕，原或曾施紅彩，今則通體呈褐色。', 1030.00, 20, N'/media/catalog/carving/贈雕000186N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/45414?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1310000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'長 5.05 公分', '2a689efb-861d-4660-deef-13a8073ad058'),
    ('67a787c2-cea3-1665-6afc-b4c64818c40b', N'CARVING', N'artifact-贈雕000291N000000000', N'竹雕零件－縮小複製品', N'雕刻是在材料上不斷取捨，最後留下最想表達的形貌。這件「竹雕零件」縮小複製品，讓刀工與構思成為可以近距離欣賞的焦點。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：雕刻' + NCHAR(10) + N'年代：西漢至六朝' + NCHAR(10) + N'商品尺寸：長 2.4 公分、徑 1.2-0.75 公分' + NCHAR(10) + N'原作尺寸：長 4.8 公分、徑 1.2-1.5 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'竹雕零件 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'竹雕零件，器呈長橢圓椎形，乃取竹近根部實心部份雕成。器之窄面淺刻一動物面與身軀，似一昆蟲，身軀陰刻點紋與弧線，並或填黑彩、或填紅彩為飾；頭之上方向上生出兩觸鬚。頭下方鑿一孔，器側穿一大方孔，尾端亦有一孔，又用一小塊竹材填塞。此器可能為某種器物之配件，目前功能不明，俟考。', 1240.00, 20, N'/media/catalog/carving/贈雕000291N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/45515?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1320000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'長 2.4 公分、徑 1.2-0.75 公分', 'd3370eec-d084-62ce-2cc9-b13e1fb5f77c'),
    ('0aa69454-685c-5009-84ec-b5554aa903e0', N'CERAMIC', N'artifact-故瓷012485N000000000', N'定窯 白瓷印花穿花雁紋盤－縮小複製品', N'從日常器用到典藏珍品，陶瓷記錄了不同時代對生活之美的想像。這件「定窯 白瓷印花穿花雁紋盤」縮小複製品，讓這段美感自然融入展示空間。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：陶瓷' + NCHAR(10) + N'年代：金至元' + NCHAR(10) + N'商品尺寸：高 2.75 公分、口徑 13.9 公分、底徑 5.9 公分' + NCHAR(10) + N'原作尺寸：高 5.5 公分、口徑 27.8 公分、底徑 11.8 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'定窯 白瓷印花穿花雁紋盤 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'大盤，侈口，淺弧壁，平底，矮圈足，口沿鑲銅釦。全器施白釉，釉色泛灰。器內印花為飾，口沿下兩道弦紋，內壁滿印蓮花孔雀紋。底心印蓮花鳧鵝紋飾，邊印回紋一周。', 920.00, 20, N'/media/catalog/ceramic/故瓷012485N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/27692?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1320000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 2.75 公分、口徑 13.9 公分、底徑 5.9 公分', 'c3c8be2d-f73a-54b9-052b-e0eb4e8451c3'),
    ('b98d3662-3ce6-25eb-d990-b6fc5efc70b0', N'PAINTING', N'artifact-故畫00353800019', N'明人便面畫冊（二）　冊　明宋旭雪景－縮小複製品', N'遠看整體氣勢，近看筆墨細節，書畫能陪人反覆觀看。這件「明人便面畫冊（二）　冊　明宋旭雪景」縮小複製品，為牆面或展示角落留下一段雅致風景。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：繪畫' + NCHAR(10) + N'年代：明神宗萬曆十年（1582）' + NCHAR(10) + N'商品尺寸：9.05 × 26.35 公分' + NCHAR(10) + N'原作尺寸：18.1 × 52.7 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'明人便面畫冊（二）　冊　明宋旭雪景 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'宋旭（西元一五二五－至一六○七年後），浙江嘉興人。字初暘，號石門，又號天池髮僧，法名祖玄。早年身世不詳，約五十歲時至松江，與當地詩人、畫家有來往。善山水，師沈周，兼長人物畫。' + NCHAR(13) + NCHAR(10) + N'　　江岸枯林樓閣，朱檻長廊，一人坐閣中對談，一人著朱衣乘篷舟而至，江水遼闊，遠山坡坨低平，著墨甚淡，用筆亦簡，略以濃墨點苔，朱砂染牆壁和廊柱，提醒全畫。畫有壬午款，作於西元一五八二年。' + NCHAR(13) + NCHAR(10) + N'　　本幅為「明人便面畫冊」第十九開。', 860.00, 20, N'/media/catalog/painting/故畫00353800019/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/18440?dep=P', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'9.05 × 26.35 公分', 'dd5312b4-1d37-2a88-f563-2d06dbb19099'),
    ('4a03cfb6-c1eb-1f9c-d648-ba56ca97b0e5', N'JADE', N'artifact-贈玉000003N000000000', N'禪地祇玉冊－縮小複製品', N'一件玉器，可以寄託品味，也能收藏一段時代記憶。以禪地祇玉冊為靈感製作的縮小複製品，為展示空間添上一份沉靜氣質。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：玉器' + NCHAR(10) + N'年代：唐玄宗開元十三年' + NCHAR(10) + N'商品尺寸：單簡長 14.95 公分、寬 1.4 公分；全寬 22.65 公分' + NCHAR(10) + N'原作尺寸：單簡長 29.9 公分、寬 2.8 公分；全寬 45.3 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'禪地祇玉冊 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'唐玄宗禪地玉冊共十五簡，長短不一。簡與簡之間以金屬線串聯。冊文係以斜刀鐫刻後塗金，但金粉現在多已剝落。其中，除玄宗署名「隆基」二字為楷體外，餘為隸書，字跡清晰，保留了原來書寫的筆意，端整豐勻，經研究與玄宗的書風相符，應該是他親筆御書之作。', 1320.00, 20, N'/media/catalog/jade/贈玉000003N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/1819?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'單簡長 14.95 公分、寬 1.4 公分；全寬 22.65 公分', '1a4b32ac-92d2-1ac4-c281-f9cd0e9e44c2'),
    ('4ab9be17-1119-7672-16e6-bb4d5cae32e7', N'BRONZE', N'artifact-故銅002187N000000000', N'異獸硯滴－縮小複製品', N'青銅器迷人的地方，在於器物本身與漫長年代共同形成的質感。以異獸硯滴為靈感製作的縮小複製品，值得從不同角度細看。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：銅器' + NCHAR(10) + N'年代：宋至元' + NCHAR(10) + N'商品尺寸：長 8.95 公分、寬 4.4 公分、高 3.9 公分' + NCHAR(10) + N'原作尺寸：長 17.9 公分、寬 8.8 公分、高 7.8 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'異獸硯滴 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'文房用具中的硯滴，是將水滴入硯台的一種工具，《長物志》認為古銅或玉做的辟邪、蟾蜍等動物為最適合。此異獸硯滴，蹲坐的異獸有獨角、偶蹄，背上有注水處，口部則有出水孔。將之置於桌案，其姿態雍容不迫，彷彿看著寫字作畫的文人，是極俱動態且精好的文房用具。', 1040.00, 20, N'/media/catalog/bronze/故銅002187N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/9?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1300000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'長 8.95 公分、寬 4.4 公分、高 3.9 公分', 'a671aa43-596a-a69b-66d6-a2661253f1f7'),
    ('9bb5eaba-2e9f-1956-6022-bc89fa03befa', N'CARVING', N'artifact-贈雕000120N000000000', N'牙雕小豚－縮小複製品', N'雕刻是在材料上不斷取捨，最後留下最想表達的形貌。這件「牙雕小豚」縮小複製品，讓刀工與構思成為可以近距離欣賞的焦點。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：雕刻' + NCHAR(10) + N'年代：戰國至六朝' + NCHAR(10) + N'商品尺寸：長 1.2 公分、高 0.75 公分' + NCHAR(10) + N'原作尺寸：長 2.4 公分、高 1.5 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'牙雕小豚 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'立雕小豚，身軀與面龐較方。類似雕工簡拙的小動物，從漢墓至六朝墓葬中皆曾見，其質材不限於牙或骨。從器物的雕刻風格看來，或可早至戰國。', 1450.00, 20, N'/media/catalog/carving/贈雕000120N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/45349?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1320000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'長 1.2 公分、高 0.75 公分', '77ea3645-eb0c-6c95-34a6-45b6d58ea0b3'),
    ('6883bdf6-8d7e-2674-d97c-c27503ccefec', N'COIN', N'artifact-購錢005070N000000000', N'聖宋元寶－縮小複製品', N'錢幣曾在人群之間流轉，如今也成為辨認時代的重要線索。以聖宋元寶為靈感製作的縮小複製品，小巧卻很有故事。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：錢幣' + NCHAR(10) + N'年代：北宋' + NCHAR(10) + N'商品尺寸：待測量' + NCHAR(10) + N'原作尺寸：待測量' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'聖宋元寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'銅質。方孔圓錢，正面有篆書：「聖宋元寶」四字，背面無文。', 670.00, 20, N'/media/catalog/coin/購錢005070N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/14408?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1340000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'待測量', 'ffab97fa-5eac-c895-dd2d-92a3216ecf5b'),
    ('e1dec1fa-2b3d-41b3-dfe2-c283c2c1655d', N'CARVING', N'artifact-贈雕000052N000000000', N'牙韘－縮小複製品', N'從一塊材料到一件作品，中間藏著工匠無數次判斷。這件「牙韘」縮小複製品，把這份手藝凝聚成耐看的收藏。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：雕刻' + NCHAR(10) + N'年代：東周' + NCHAR(10) + N'商品尺寸：長 2.15 公分、寬 1.45 公分' + NCHAR(10) + N'原作尺寸：長 4.3 公分、寬 2.9 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'牙韘 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'橢圓形，一端向外斜出而較尖，另一端陰刻數道直紋為飾，左右各有一鈕向兩側伸出，一作方形，一作螺旋形；器之上緣有齒狀裝飾，底緣平齊。器之大部分已呈綠色。洛陽中州路東周墓葬中曾出土一件骨韘，一端外緣即歧出一方形鈕；而曲阜魯故城一座春秋墓中亦曾出土一件牙韘，其一端側緣也有一方鈕。', 1520.00, 20, N'/media/catalog/carving/贈雕000052N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/45278?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1320000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'長 2.15 公分、寬 1.45 公分', '521ca3d9-35c6-7ae0-ef5b-499bcb72648d'),
    ('e7b4eec2-4430-853a-734d-c2ec5a4689cf', N'JADE', N'artifact-故玉004349N000000000', N'玉獸佩－縮小複製品', N'一件玉器，可以寄託品味，也能收藏一段時代記憶。以玉獸佩為靈感製作的縮小複製品，為展示空間添上一份沉靜氣質。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：玉器' + NCHAR(10) + N'年代：戰國晚期' + NCHAR(10) + N'商品尺寸：長 7.7 公分、寬 3.65 公分、厚 0.2 公分' + NCHAR(10) + N'原作尺寸：長 15.4 公分、寬 7.3 公分、厚 0.4 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'玉獸佩 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'本器為獸形佩，玉質，有深褐色沁，局部白化。本器正反兩面紋飾並不相同，一面獸身飾戰國中期以來傳統的穀紋；另一面獸身勾勒各種戰國晚期到西漢早期流行的紋飾單元，包括：似葉紋與花卉紋，是討論紋飾風格變化的重要例證。本器從紋飾題材風格、形制、玉質特徵及雕刻技巧來看，屬戰國晚期作品。本器存放在院藏「紫檀雕蟠龍方盒百什件」（故雜877）中。', 1570.00, 20, N'/media/catalog/jade/故玉004349N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/71753?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'長 7.7 公分、寬 3.65 公分、厚 0.2 公分', 'cecb154b-0996-be55-ff74-9dc28d145420'),
    ('ca120692-0921-ea2c-df3e-c3a48c507ece', N'BRONZE', N'artifact-中銅002015N000000000', N'銅鍍金嵌綠松石香爐－縮小複製品', N'先看整體輪廓，再找製作與歲月留下的細節，銅器總能讓人多停留一會兒。這件「銅鍍金嵌綠松石香爐」縮小複製品，讓這份歷史感更貼近日常。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：銅器' + NCHAR(10) + N'年代：清 乾隆' + NCHAR(10) + N'商品尺寸：寬 6.05 公分、高 9.5 公分' + NCHAR(10) + N'原作尺寸：寬 12.1 公分、高 19.0 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'銅鍍金嵌綠松石香爐 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'圓形鼎式香爐，器上飾雲紋及回紋，器腹下方及圓柱形足上飾蕉葉紋，紋間嵌以綠松石，口沿下橫列「大清乾隆年敬造」七字陽文款識。', 810.00, 20, N'/media/catalog/bronze/中銅002015N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/2658?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1310000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'寬 6.05 公分、高 9.5 公分', '4aa37d74-7d1d-c9ec-7525-d6271b33ea34'),
    ('cd4ba065-7e4d-df9b-ae1f-c59c38110845', N'CERAMIC', N'artifact-故瓷004115N000000000', N'定窯 白瓷印花牡丹犀牛望月圖盤－縮小複製品', N'一件陶瓷，可以從遠處看整體，也值得靠近欣賞質感。這件「定窯 白瓷印花牡丹犀牛望月圖盤」縮小複製品，為收藏角落留下一份安定而耐看的風景。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：陶瓷' + NCHAR(10) + N'年代：金至元' + NCHAR(10) + N'商品尺寸：高 2.55 公分、口徑 12.8 公分、底徑 5.3 公分' + NCHAR(10) + N'原作尺寸：高 5.1 公分、口徑 25.6 公分、底徑 10.6 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'定窯 白瓷印花牡丹犀牛望月圖盤 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'侈口大盤，淺弧壁，矮圈足，口鑲銅稜釦。盤內口沿下弦紋二道。盤壁印纏枝牡丹花，花葉繁密無隙地。底心寬圓，以回紋為邊，中印犀牛望月圖，水波洶湧，犀臥坐水渚，星月爭輝。', 880.00, 20, N'/media/catalog/ceramic/故瓷004115N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/29861?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1320000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 2.55 公分、口徑 12.8 公分、底徑 5.3 公分', '7d23aa54-a0fd-2467-7c3c-3141cb5ef82f'),
    ('838fe611-7ec7-2bc0-d8e5-c5a214c31413', N'ENAMEL', N'artifact-故琺000835N000000000', N'掐絲琺瑯梵文碟－縮小複製品', N'色彩是琺瑯最直接的吸引力，工序與細節則值得再三欣賞。以掐絲琺瑯梵文碟為靈感製作的縮小複製品，讓空間多一抹典藏氣息。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：琺瑯器' + NCHAR(10) + N'年代：清 乾隆' + NCHAR(10) + N'商品尺寸：口徑 7.5 公分' + NCHAR(10) + N'原作尺寸：口徑 15.0 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'掐絲琺瑯梵文碟 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'侈口，折沿，淺壁，平底，圈足。全器淺藍地，口沿寫有一圈梵文，內底有卷鬚錦，中心有一由七個梵文及三個符號組成的「十相自在」吉祥紋飾，盤內外壁為朵雲紋間飾佛教七珍、八寶。底部有陰刻「乾隆年製」四字雙行楷書雙方框款。', 810.00, 20, N'/media/catalog/enamel/故琺000835N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/61821?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1340000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'口徑 7.5 公分', 'ccb7d1a3-fbe9-4342-e887-4dea74418a33'),
    ('a394c5fc-b3e2-dc8a-8bee-c619f53259dc', N'ENAMEL', N'artifact-故琺000881N000000000', N'銅胎畫琺瑯芙蓉紋圓盒－縮小複製品', N'色彩是琺瑯最直接的吸引力，工序與細節則值得再三欣賞。以銅胎畫琺瑯芙蓉紋圓盒為靈感製作的縮小複製品，讓空間多一抹典藏氣息。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：琺瑯器' + NCHAR(10) + N'年代：清 乾隆' + NCHAR(10) + N'商品尺寸：高 2.18 公分、口徑 8.3 公分' + NCHAR(10) + N'原作尺寸：高 4.35 公分、口徑 16.6 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'銅胎畫琺瑯芙蓉紋圓盒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'銅胎，覆缽式蓋與器身對合成扁圓盒。蓋與器身對合處，以及圈足各飾一圈白地藍色回紋。盒內施淺藍釉；蓋頂繪白色線圈，飾以盛開之紅芙蓉；蓋面與器身各飾四朵紅藍顏色的折枝芙蓉，間以折枝花卉。盒底色白並有一藍方框雙行「乾隆年製」楷款。', 960.00, 20, N'/media/catalog/enamel/故琺000881N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/61860?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1340000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 2.18 公分、口徑 8.3 公分', '94beb377-a5a4-9da5-62d9-62ad04da2496'),
    ('77f7744e-0920-b26f-bb9a-c631a0218684', N'CARVING', N'artifact-贈雕000034N000000000', N'角雕人首紋錐－縮小複製品', N'雕刻值得從多個角度觀看，輪廓、轉折與細部會逐一展開。這件「角雕人首紋錐」縮小複製品，適合擺在能讓人停下腳步的位置。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：雕刻' + NCHAR(10) + N'年代：西夏' + NCHAR(10) + N'商品尺寸：長 6 公分' + NCHAR(10) + N'原作尺寸：長 12.0 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'角雕人首紋錐 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'此件取獸角製成，尖端朝下，正面上端浮雕出一人面，頂端陰刻短斜紋為頭髮，並陰刻圈點紋為眼紋(雙圈為眼形，中央深鑽一圓心為眼瞳)，斜凹雕出面頰，留出鼻部，陰刻一短線為鼻頭，再陰刻一長線為唇部。人面下方陰刻一道凹槽為頸部，頸部下方左右各斜刻兩道直線以示衣領，頷部下方(即衣領上方)陰刻一單圈圈點紋為飾。器之中段部位繞器陰刻兩道凹槽以間隔出身軀，身軀部位左右各陰刻四圈點紋，近中央部位者為雙圈，餘為單圈；凹槽上方兩側各刻一》紋，其紋正中下方而為凹槽上方部位刻一單圈圈點紋為飾。凹槽下方陰刻二道弦紋為飾，並於其下方正中部位依上下左右四方排列方式各刻一單圈圈點紋為飾。上端人面兩側於同一部位各穿一圓孔，可繫掛，亦示其雙耳。《遼史》記載當時西夏人的服御乃「冠用金縷......佩蹀躞、解錐、短刀、弓矢，......」。近人曾在寧夏回族自治區海原縣原西夏開國皇帝李元昊的行宮遺址中發掘一件人頭形鹿角質製成的解錐，長12公分，錐角直徑1.8-2.0公分，一端用作解錐的尖，角根部則雕飾人頭像，雙耳部位穿有繫繩的孔。因此，這件磋角人首紋器用或亦為當時角錐之實例。', 920.00, 20, N'/media/catalog/carving/贈雕000034N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/45260?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1320000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'長 6 公分', 'b5300a1e-74a4-f523-eb37-fc8d20bec0e8');
INSERT INTO [store].[Products] ([Id], [CategoryCode], [ExternalRef], [Name], [Description], [Price], [Stock], [PrimaryImagePath], [SourceUrl], [IsActive], [CreatedAt], [UpdatedAt], [SizeText], [ArtifactId]) VALUES
    ('5fc05fc9-3ed6-078f-ae5d-c781d5997ab0', N'BRONZE', N'artifact-故銅002522N000000000', N'弦紋觶－縮小複製品', N'有些文物不必鋪陳太多，安靜擺著就很有分量。這件「弦紋觶」縮小複製品延續銅器特有的沉著氣質，適合成為展示中的視覺焦點。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：銅器' + NCHAR(10) + N'年代：西周' + NCHAR(10) + N'商品尺寸：高 6.45 公分、連座高 7.25 公分、口徑 3.45 公分、底徑 3.05 公分；木座寬 1.05 公分、高 1 公分' + NCHAR(10) + N'原作尺寸：高 12.9 公分、連座高 14.5 公分、口徑 6.9 公分、底徑 6.1 公分；木座寬 2.1 公分、高 2.0 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'弦紋觶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'侈口，束頸，鼓腹，圜底，圈足外撇。頸部及圈足飾凸弦紋。清宮配有木座，正面為篆字「乾隆御賞」，底銘楷書「周素觶八」。', 1560.00, 20, N'/media/catalog/bronze/故銅002522N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/62215?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1300000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 6.45 公分、連座高 7.25 公分、口徑 3.45 公分、底徑 3.05 公分；木座寬 1.05 公分、高 1 公分', '233bba1e-d89c-d4a2-0878-abae43b4b4e5'),
    ('23234a53-e9b8-00ed-39b7-c7a4df22d871', N'CERAMIC', N'artifact-贈瓷000473N000000000', N'加彩灰陶馬－縮小複製品', N'一件陶瓷，可以從遠處看整體，也值得靠近欣賞質感。這件「加彩灰陶馬」縮小複製品，為收藏角落留下一份安定而耐看的風景。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：陶瓷' + NCHAR(10) + N'年代：東漢' + NCHAR(10) + N'商品尺寸：長 51.5 公分、高 42.5 公分' + NCHAR(10) + N'原作尺寸：長 103.0 公分、高 85.0 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'加彩灰陶馬 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'陶馬，體型短小。長臉，骨棱分明，眉脊高聳，鼻翼奮張，圓目，張嘴吐舌作喘息狀。粗頸寬胸，平背圓臀，腕粗蹄闊，雙耳高聳。額前鬃毛成束，後腦馬鬃披頸，剪短豎起。尾作弧形上翹，末端打結。四足穩立，矯健有力。肌肉結實，呈現漢代駿馬的體態。塑者捕捉馬在停歇喘息的瞬間，活潑生動。馬匹原為赭紅色，局部尚留白色粉底及朱彩。 陶馬為漢代事死如事生概念下的陪葬品，大量出現在四川、河南、河北等地。本作品與四川樂山崖墓東漢墓出土的陶馬造型類似。由墓葬出現狀態觀察，此類體態優美的馬匹可為坐騎、軺車乘馬，也盛裝作儀隊用馬。據說是健步如飛的汗血馬，西漢武帝（西元前157-87年）為獲取此類馬匹曾兩次西征大宛國（今土庫曼斯坦阿什喀巴城）。', 1280.00, 20, N'/media/catalog/ceramic/贈瓷000473N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/43503?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1320000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'長 51.5 公分、高 42.5 公分', '89e97f27-85ff-f9a3-aa05-ade9834a0b28'),
    ('70187b27-fe69-3cc0-1398-c90dce271d9c', N'JADE', N'artifact-故玉009113N000000000', N'〈般若波羅蜜多心經〉玉版－縮小複製品', N'一件玉器，可以寄託品味，也能收藏一段時代記憶。以〈般若波羅蜜多心經〉玉版為靈感製作的縮小複製品，為展示空間添上一份沉靜氣質。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：玉器' + NCHAR(10) + N'年代：清 乾隆' + NCHAR(10) + N'商品尺寸：長 2.9 公分、寬 2.25 公分' + NCHAR(10) + N'原作尺寸：長 5.8 公分、寬 4.5 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'〈般若波羅蜜多心經〉玉版 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'長方形玉版，一式四件（故玉9113-9116），上刻錢汝誠（1722-1779）所書〈般若波羅蜜多心經〉填金楷字。本器為玉版中的第一片，正面刻「心經」二字，餘刻卷枝番蓮紋。背面刻「般若波羅蜜多心經」開頭至「色即是空，空即是」。', 920.00, 20, N'/media/catalog/jade/故玉009113N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/60155?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1340000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'長 2.9 公分、寬 2.25 公分', 'a5e3a537-5c6d-6637-ad9c-27f0a8cd9c4b'),
    ('89ab3664-abcb-1d7f-ea7c-cb457257693a', N'CARVING', N'artifact-贈雕000035N000000000', N'角雕人首紋錐－縮小複製品', N'雕刻值得從多個角度觀看，輪廓、轉折與細部會逐一展開。這件「角雕人首紋錐」縮小複製品，適合擺在能讓人停下腳步的位置。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：雕刻' + NCHAR(10) + N'年代：西夏' + NCHAR(10) + N'商品尺寸：長 5.7 公分' + NCHAR(10) + N'原作尺寸：長 11.4 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'角雕人首紋錐 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'此件取獸角製成，尖端朝下，正面上端浮雕出一人面，以圈點紋為眼紋(陰刻單圈為眼形，中央深鑽一圓心為眼瞳)，眼下方中央並陰刻一短橫線與一長橫線為鼻與口。人面下方陰刻一道為頸部，器之中段部位繞器陰刻三道橫線以間隔出身軀，身軀部位依上下左右中各陰刻一圈點紋(單圈中鑽一圓心)。同樣的圈點紋亦飾於器側三道橫線之上方與下方，以及器背三道橫線下方。器之上端人面兩側於同一部位各穿一圓孔，可繫掛。這件磋角人首紋錐與西夏開國皇帝李元昊的行宮遺址中發掘一件人頭形鹿角質製成的解錐相似，但後者更形儉樸。', 960.00, 20, N'/media/catalog/carving/贈雕000035N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/45261?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1320000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'長 5.7 公分', 'e719e755-917b-377c-766a-c4ef6b7fcae5'),
    ('88c47ad6-b791-0196-733e-cd7dd7456ac3', N'LACQUER', N'artifact-故漆000474N000000000', N'鎗金填漆牡丹龍紋菊瓣盤－縮小複製品', N'漆藝講究耐心，也讓器物擁有難以取代的深沉質感。這件「鎗金填漆牡丹龍紋菊瓣盤」縮小複製品，是一件越看越能發現味道的收藏。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：漆器' + NCHAR(10) + N'年代：明 嘉靖' + NCHAR(10) + N'商品尺寸：高 1.9 公分、深 1 公分、口徑 9.1 公分、足徑 5.95 公分' + NCHAR(10) + N'原作尺寸：高 3.8 公分、深 2.0 公分、口徑 18.2 公分、足徑 11.9 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'鎗金填漆牡丹龍紋菊瓣盤 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'菊瓣形圓盤，圈足，足內髹黑漆。盤沿內外作菊瓣形，每一瓣刻似孔雀羽毛的圓眼，宛如孔雀開屏。盤心一龍盤旋，中央一折枝牡丹，以鎗金勾勒輪廓及紋理，再填髹綠漆，枝葉扶疏，花形圓滿，姿態婉約。龍身脩長飛舞環繞，龍首在左下露出，雲紋散佈，構圖疏密有致，氣勢雍容靈動。紅漆地上綠葉襯托，金彩燦爛耀眼，襯以沉穩的綠葉與暈染的花瓣，華麗中不失穩重。', 810.00, 20, N'/media/catalog/lacquer/故漆000474N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/17569?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 1.9 公分、深 1 公分、口徑 9.1 公分、足徑 5.95 公分', 'f3d17a2e-4829-e874-ba5a-21c10611bbab'),
    ('dd24927f-f5fa-cad1-6c95-ce0e4cdb5cbc', N'COIN', N'artifact-購錢004645N000000000', N'祥符元寶－縮小複製品', N'方寸之間，裝得下年代、制度與人們往來交易的痕跡。這件「祥符元寶」縮小複製品，從一枚錢幣打開認識歷史的新角度。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：錢幣' + NCHAR(10) + N'年代：北宋' + NCHAR(10) + N'商品尺寸：待測量' + NCHAR(10) + N'原作尺寸：待測量' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'祥符元寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'銅質。方孔圓錢，正面有楷書：「祥符元寶」四字，背面無文。', 790.00, 20, N'/media/catalog/coin/購錢004645N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/13983?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1340000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'待測量', '4aff0a71-a14e-12ee-915a-0bf21874ff1a'),
    ('221d925c-e038-4456-4fb2-ceab4fd50321', N'CARVING', N'artifact-贈雕000189N000000000', N'牙雕鏤空描金白彩花卉紋梳－縮小複製品', N'雕刻值得從多個角度觀看，輪廓、轉折與細部會逐一展開。這件「牙雕鏤空描金白彩花卉紋梳」縮小複製品，適合擺在能讓人停下腳步的位置。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：雕刻' + NCHAR(10) + N'年代：宋金至元' + NCHAR(10) + N'商品尺寸：殘長 4.25 公分、寬 1.8 公分、背厚 0.15 公分' + NCHAR(10) + N'原作尺寸：殘長 8.5 公分、寬 3.6 公分、背厚 0.3 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'牙雕鏤空描金白彩花卉紋梳 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'全器呈半月形，一端銳尖，另一端已殘，原應仍成尖銳形。因紋飾所需，器之背寬中央稍大，梳齒長度由中央向兩側依序遞減，梳背雕飾鏤空花卉紋，間描金為飾，花瓣部位尚填白彩。', 880.00, 20, N'/media/catalog/carving/贈雕000189N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/45417?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1320000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'殘長 4.25 公分、寬 1.8 公分、背厚 0.15 公分', '420aa075-673c-8299-93ab-3d35ecf58233'),
    ('8b93e0d2-b6d0-ea15-eaf2-cf2a90f29725', N'CERAMIC', N'artifact-故瓷018325N000000000', N'龍泉釉器底改件鼻煙碟－縮小複製品', N'從日常器用到典藏珍品，陶瓷記錄了不同時代對生活之美的想像。這件「龍泉釉器底改件鼻煙碟」縮小複製品，讓這段美感自然融入展示空間。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：陶瓷' + NCHAR(10) + N'年代：明 宣德' + NCHAR(10) + N'商品尺寸：高 0.65 公分、徑 2.5 公分' + NCHAR(10) + N'原作尺寸：高 1.3 公分、徑 5.0 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'龍泉釉器底改件鼻煙碟 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'瓷煙碟，碟面以青花書「大明宣德年製」二行六字楷書，外施青釉，碟緣露胎，應是取本院藏〈明 宣德 仿龍泉蓮瓣形折腰碟〉一類器心書款之器改製而成，附編織袋方便攜用。原貯於永壽宮，經比對可能是《宣統二年二月十四日立  鼻煙壺帳》中的一批。', 890.00, 20, N'/media/catalog/ceramic/故瓷018325N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/61184?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1330000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 0.65 公分、徑 2.5 公分', '40f99a83-202e-2c62-d602-41a096079040'),
    ('1748a948-4a34-ed48-2a73-cfda94e9fb14', N'COIN', N'artifact-贈錢001272N000000000', N'日本錢幣－縮小複製品', N'一枚錢幣，連起的是制度與日常生活。這件「日本錢幣」縮小複製品，把龐大的時代故事收進容易細看的尺寸。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：錢幣' + NCHAR(10) + N'年代：日本 明治時代' + NCHAR(10) + N'商品尺寸：待測量' + NCHAR(10) + N'原作尺寸：待測量' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'日本錢幣 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'圓錢，正面楷書：「大日本明治九年」「1 SEN」；背面「一錢」「百枚換一圓」。正面中央有草葉紋飾，背面文字被圍繞在花草紋中。', 620.00, 20, N'/media/catalog/coin/贈錢001272N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/9095?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1330000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'待測量', 'acfdce2f-4128-f720-ca18-e8d62f1e90bf'),
    ('1be8a06a-3417-4224-ccd2-d17f0612bd16', N'PAINTING', N'artifact-南購畫00010500000', N'日本 20世紀富岡鐵齋牧童騎牛圖 軸－縮小複製品', N'畫面不只記錄所見，也保存創作者觀看世界的方式。這件「日本 20世紀富岡鐵齋牧童騎牛圖 軸」縮小複製品，邀你把這份想像帶進自己的空間。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：繪畫' + NCHAR(10) + N'年代：日本大正時代14年（1925）1月' + NCHAR(10) + N'商品尺寸：官方資料未提供' + NCHAR(10) + N'原作尺寸：官方資料未提供' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'日本 20世紀富岡鐵齋牧童騎牛圖 軸 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'富岡鉄斎死後的作品被記載為「大正十四年一月/九十叟鐵齋」。橋本独山在外箱墨書「遺墨」、書寫的時間則是「時過初夏」，表示箱書是在鉄斎死後寫的，從緣由書可得知寸紅堂主委託独山寫了箱書。富岡鉄斎近年的研究顯示，大正13年(1924)起，初秋左右的作品開始用九十歲的落款。鉄斎死於12月31日除夕，12月上旬左右痼疾的膽石症發病，中旬一度轉好，年底卻又複發。31日中午，病床上雖可談話但下午突然去世。本作品的紀年「大正十四年一月九十叟」，推估為大正13年9月到12月上旬左右製作，可視為鉄斎最晚年的作品。相較於其他畫作，本作品雖略感無力，但是作為煎茶器套組的掛軸，佈置在和室壁龕中依然是非常合適。', 760.00, 20, N'/media/catalog/painting/南購畫00010500000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/36551?dep=P', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'官方資料未提供', 'cf210e63-ba5d-484e-0fa7-4406fef50f0a'),
    ('944295d7-297a-8d41-0ba4-d2405d557fdb', N'LACQUER', N'artifact-故漆000540N000000000', N'剔彩春壽寶盒－縮小複製品', N'光影落在漆面上，每個角度都有不同感受。這件「剔彩春壽寶盒」縮小複製品延續漆器含蓄而精緻的魅力，為展示空間添上一份古雅。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：漆器' + NCHAR(10) + N'年代：明 嘉靖' + NCHAR(10) + N'商品尺寸：口徑約 17.8 公分' + NCHAR(10) + N'原作尺寸：口徑約 35.6 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'剔彩春壽寶盒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'圓盒，圓頂，圈足，盒內及足內髹黑漆，盒外剔彩，漆層自下而上的漆色為黃、紅相間三組，然後綠、黃，綠、紅。盒面中央一大圓，圓框為帶狀唐草紋，圓內下方一個大聚寶盆，放滿各式珊瑚、犀角等珍寶，並放射出光芒，聚寶盆正上方一大大的楷體「春」字，春字中央又一圓框，圓內有壽星與鹿在松樹前，春字兩側雲龍飛舞，處處充滿吉祥象徵符號。大圓之外的盒緣為方格錦地，四開光，內為人物山水，開光之間飾八寶之四寶，口沿為如意雲紋帶。盒身亦飾如意雲紋帶與錦地山水人物開光，足側飾連續回紋。構圖層次分明，壽、春、寶主題突顯，佈局緊湊。漆質硬，刀法嚴整，莊嚴中不失富麗，惜漆層薄而不堅，是官方雕漆的典型。', 900.00, 20, N'/media/catalog/lacquer/故漆000540N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/18268?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'口徑約 17.8 公分', '7f6f07d2-7d25-1565-5017-c8fb2f1a105a'),
    ('e889d390-37e4-836f-9824-d26c000d4ef6', N'CERAMIC', N'artifact-故瓷018148N000000000', N'天藍釉尊－縮小複製品', N'一件陶瓷，可以從遠處看整體，也值得靠近欣賞質感。這件「天藍釉尊」縮小複製品，為收藏角落留下一份安定而耐看的風景。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：陶瓷' + NCHAR(10) + N'年代：清 康熙' + NCHAR(10) + N'商品尺寸：高 12.65 公分' + NCHAR(10) + N'原作尺寸：高 25.3 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'天藍釉尊 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'菊瓣形尊，長頸，圓肩，扁球形腹，外撇圈足。全器內外施藍釉，流淌不勻。菊瓣接縫處內陷，積釉呈寶藍色。造型大方具清康熙時期瓷器的風範。', 840.00, 20, N'/media/catalog/ceramic/故瓷018148N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/61039?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1320000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 12.65 公分', 'd94926f5-2f37-3e4b-20b4-1af21af02557'),
    ('10f28c11-3922-ab2d-48e8-d29a2681db19', N'LACQUER', N'artifact-贈漆000006N000000000', N'褐漆葵花式盤－縮小複製品', N'漆器耐看的地方，在於表面質感與製作時間共同留下的韻味。以褐漆葵花式盤為靈感製作的縮小複製品，適合在近處慢慢欣賞。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：漆器' + NCHAR(10) + N'年代：宋至元' + NCHAR(10) + N'商品尺寸：高 1.35 公分、口徑 7.85 公分' + NCHAR(10) + N'原作尺寸：高 2.7 公分、口徑 15.7 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'褐漆葵花式盤 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'盤，木胎，七瓣葵花式口，矮圈足，通身髹醬褐色漆，口緣包鑲一圈細窄銅邊，圈足內中央朱漆繪一橢圓印，印文漫渙不識。', 840.00, 20, N'/media/catalog/lacquer/贈漆000006N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/103?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 1.35 公分、口徑 7.85 公分', 'ab0fd8e3-04ed-c5b8-51be-040763090373'),
    ('4e884280-8ddd-76fd-d360-d432b841323e', N'BRONZE', N'artifact-故銅000452N000000000', N'銅嵌金星玻璃八角鼻煙盒－縮小複製品', N'先看整體輪廓，再找製作與歲月留下的細節，銅器總能讓人多停留一會兒。這件「銅嵌金星玻璃八角鼻煙盒」縮小複製品，讓這份歷史感更貼近日常。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：銅器' + NCHAR(10) + N'年代：清 乾隆' + NCHAR(10) + N'商品尺寸：長 2.75 公分、寬 2.15 公分' + NCHAR(10) + N'原作尺寸：長 5.5 公分、寬 4.3 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'銅嵌金星玻璃八角鼻煙盒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'銅質，扁八方形小盒。子母口，淺直壁，蓋緣與足鏨飾斜階式凸棱多道，蓋面嵌八方形金星玻璃石一塊。內收小螺蛤四枚。本件收入乾隆時期製作多寶格「集瓊藻」中，據集瓊藻小冊所載原有二層七十三件，共儲於嵌飾獸骨螺甸的木箱中。', 830.00, 20, N'/media/catalog/bronze/故銅000452N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/24260?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1310000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'長 2.75 公分、寬 2.15 公分', '16cd5d7b-27db-4ce6-9c70-101063761f30'),
    ('5abd84c3-409e-7a4b-5be5-d52bae4a9240', N'LACQUER', N'artifact-故漆000342N000000000', N'剔紅尋詩寶盒－縮小複製品', N'漆藝講究耐心，也讓器物擁有難以取代的深沉質感。這件「剔紅尋詩寶盒」縮小複製品，是一件越看越能發現味道的收藏。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：漆器' + NCHAR(10) + N'年代：清 乾隆' + NCHAR(10) + N'商品尺寸：長 8.15 公分、寬 8.15 公分、高 3.25 公分' + NCHAR(10) + N'原作尺寸：長 16.3 公分、寬 16.3 公分、高 6.5 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'剔紅尋詩寶盒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'方盒，平頂蓋、子母口、平底、圈足，內附承盤，以置數件器物。蓋飾人物、山水，蓋緣與腹開光內填花卉。器內及外底均為黑漆，外底戧金「大清乾隆年製」，蓋內為「尋詩寶盒」款。', 850.00, 20, N'/media/catalog/lacquer/故漆000342N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/48317?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'長 8.15 公分、寬 8.15 公分、高 3.25 公分', '31d48ea6-6ed4-c51e-5d6f-53c88d54f1ac'),
    ('3f879408-5054-cf00-2008-d52bf93b6312', N'CARVING', N'artifact-贈雕000097N000000000', N'雙拼牙零件－縮小複製品', N'雕刻是在材料上不斷取捨，最後留下最想表達的形貌。這件「雙拼牙零件」縮小複製品，讓刀工與構思成為可以近距離欣賞的焦點。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：雕刻' + NCHAR(10) + N'年代：東周至漢' + NCHAR(10) + N'商品尺寸：高 1.95 公分、最大徑 0.9 公分' + NCHAR(10) + N'原作尺寸：高 3.9 公分、最大徑 1.8 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'雙拼牙零件 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'全器剖面呈長工字形，略偏一側縱向剖分成二塊，上下各鑿一小孔，並磨小棒穿拼。全器光素無紋，但傷蝕嚴重。', 1320.00, 20, N'/media/catalog/carving/贈雕000097N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/45323?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1320000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 1.95 公分、最大徑 0.9 公分', '0268940a-7aa1-1193-f0e7-88f35be3434a'),
    ('68c846f5-d856-88b2-8e97-d52edb75b462', N'BRONZE', N'artifact-中銅000409N000000000', N'獸面紋方觚－縮小複製品', N'有些文物不必鋪陳太多，安靜擺著就很有分量。這件「獸面紋方觚」縮小複製品延續銅器特有的沉著氣質，適合成為展示中的視覺焦點。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：銅器' + NCHAR(10) + N'年代：南宋至明' + NCHAR(10) + N'商品尺寸：高 16.2 公分' + NCHAR(10) + N'原作尺寸：高 32.4 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'獸面紋方觚 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'方觚，四方形口、方腹、方圈足，脰、腹、足皆有棱脊。脰、腹、足皆飾獸面紋、雲雷紋為地。足底外有銘二字。', 950.00, 20, N'/media/catalog/bronze/中銅000409N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/6839?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1300000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 16.2 公分', 'f89e802f-5fb9-9289-3bca-b2d5de8ae1ed'),
    ('64561e87-6705-95b8-47f7-d5cc1eb0a4ff', N'BRONZE', N'artifact-中銅000150N000000000', N'獸面紋觚－縮小複製品', N'金屬與火塑成器物，歲月再替表面留下時間的痕跡。這件「獸面紋觚」縮小複製品，把銅器沉穩厚實的存在感帶進收藏空間。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：銅器' + NCHAR(10) + N'年代：南宋至明' + NCHAR(10) + N'商品尺寸：高 17.2 公分' + NCHAR(10) + N'原作尺寸：高 34.4 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'獸面紋觚 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'觚口極度外張，直筒腹，圈足起臺。頸部飾蕉葉紋，內填解體獸面紋，下頸處則有一小周渦紋與四瓣花紋相間紋飾帶。腹部、圈足飾解體獸面紋。下頸處、腹部、圈足皆有四條扉稜。此器仿自商晚期觚的造型，但渦紋、四瓣花紋、地紋的雲雷紋等細節多有訛舛。器表紅、綠作鏽，局部紋飾覆蓋瘤狀物彷彿堆疊的鏽層，以上特徵均為晚期仿古器常見的作舊方式。本件器物是乾隆三十四年(1769)頒賜國子監的「周笵十器」之一，名之為「周雷紋觚」。', 980.00, 20, N'/media/catalog/bronze/中銅000150N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/6841?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1300000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 17.2 公分', 'b542a8d0-eac9-3882-2aa2-8c27c71bae23'),
    ('9cbc18b3-0fb9-394d-27a1-d80967bc0185', N'JADE', N'artifact-故玉007653N000000000', N'玉鳧佩－縮小複製品', N'一件玉器，可以寄託品味，也能收藏一段時代記憶。以玉鳧佩為靈感製作的縮小複製品，為展示空間添上一份沉靜氣質。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：玉器' + NCHAR(10) + N'年代：南宋至明' + NCHAR(10) + N'商品尺寸：全長 5.75 公分' + NCHAR(10) + N'原作尺寸：全長 11.5 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'玉鳧佩 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'色青白，帶赭色玉皮，有璺。雕一野鳧立於荷葉上，作回首狀，陰線細刻五官、羽翼、荷葉脈等部位，並巧留玉皮為荷葉色，造型生趣可愛。野鳧頸處有一穿，繫繩及絲穗以作佩飾。', 1150.00, 20, N'/media/catalog/jade/故玉007653N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/58698?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'全長 5.75 公分', '90a42404-0462-74d4-6b8b-7436c994d1e4'),
    ('f0b20d24-39df-8a07-696b-d84eacacc282', N'PAINTING', N'artifact-故畫00353800003', N'明人便面畫冊（二）　冊　明錢穀春山－縮小複製品', N'畫面不只記錄所見，也保存創作者觀看世界的方式。這件「明人便面畫冊（二）　冊　明錢穀春山」縮小複製品，邀你把這份想像帶進自己的空間。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：繪畫' + NCHAR(10) + N'年代：明神宗萬曆五年（1577）' + NCHAR(10) + N'商品尺寸：8 × 23.65 公分' + NCHAR(10) + N'原作尺寸：16 × 47.3 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'明人便面畫冊（二）　冊　明錢穀春山 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'錢穀（西元一五０八─一五七八年），江蘇吳縣人。字叔寶，號磐室。少孤貧失學，及長，遊文徵明門下，讀書之餘，兼習繪畫。山水、人物、花鳥俱擅長。山水以筆墨爽朗見長，放縱之處甚於文徵明。' + NCHAR(13) + NCHAR(10) + N'　春山白雲，溪岸人家。前景叢樹濃蔭，間有房舍，林後山腰為雲帶隔斷，遠峰橫列，以橫筆「米點」疊繪而成。其中樹、山皆先用墨筆橫畫，再點汁綠，後罩石青。層層點染乃學米氏雲山法，而鮮麗的石青設色，則於墨點堆砌外，另有一番異趣。本幅為「明人便面畫冊」第三開。', 830.00, 20, N'/media/catalog/painting/故畫00353800003/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/18404?dep=P', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1360000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'8 × 23.65 公分', '8ea9fdfe-fe23-10b8-26d8-a59d3e6ece84'),
    ('4ee6aba4-f1a7-ffd4-d16b-da6d310d1bd2', N'PAINTING', N'artifact-故畫00194700000', N'元趙孟頫達摩像　軸－縮小複製品', N'一幅畫最迷人的地方，是每次觀看都可能發現不同線索。這件「元趙孟頫達摩像　軸」縮小複製品，把畫面的節奏與意境帶進日常空間。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：繪畫' + NCHAR(10) + N'年代：元世祖至元二十九年（1292）' + NCHAR(10) + N'商品尺寸：55.55 × 17.5 公分' + NCHAR(10) + N'原作尺寸：111.1 × 35 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'元趙孟頫達摩像　軸 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'據傳達摩為中國禪宗始祖，本為印度王子，南北朝時泛海至中國傳法，曾於嵩山少林寺面壁十年，深受國人崇仰。' + NCHAR(13) + NCHAR(10) + NCHAR(13) + NCHAR(10) + N'松蔭下，達摩身披紅色袈裟，手捻白花，趺坐於石上，神情怡然。年款雖為至元二十九年（一二九二），然畫法細碎，近於吳門畫派末流，當是後人仿本。' + NCHAR(13) + NCHAR(10) + NCHAR(13) + NCHAR(10) + N'趙孟頫（一二五四—一三二二），字子昂，號松雪道人。詩文清遠，書畫為後世所宗。', 730.00, 20, N'/media/catalog/painting/故畫00194700000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/1239?dep=P', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'55.55 × 17.5 公分', '7c6eb723-3a45-02c4-7295-96c85e37a5cd'),
    ('ac0935f8-a89e-7e0c-7eda-dbb76162f1d9', N'LACQUER', N'artifact-故漆000355N000000000', N'剔紅錦荔寶盒－縮小複製品', N'漆器耐看的地方，在於表面質感與製作時間共同留下的韻味。以剔紅錦荔寶盒為靈感製作的縮小複製品，適合在近處慢慢欣賞。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：漆器' + NCHAR(10) + N'年代：清 乾隆' + NCHAR(10) + N'商品尺寸：高 1.2 公分、徑 2.35 公分；木座徑 2.2 公分、高 0.45 公分；連木座高 1.55 公分' + NCHAR(10) + N'原作尺寸：高 2.4 公分、徑 4.7 公分；木座徑 4.4 公分、高 0.9 公分；連木座高 3.1 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'剔紅錦荔寶盒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'圓盒，子母口。整器以回紋為地，雕刻荔枝果實花葉滿覆器表，果葉交疊曲折，又能顯出彼此的相對空間，在靜態中寓以生意，是此器值得品味之處。其蓋內刻「錦荔寶盒」填金楷字，底內則刻「大清乾隆年製」填金楷字。附木座。', 830.00, 20, N'/media/catalog/lacquer/故漆000355N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/24253?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 1.2 公分、徑 2.35 公分；木座徑 2.2 公分、高 0.45 公分；連木座高 1.55 公分', '2e50d880-50a6-ee88-e7ad-91e77358d1ec'),
    ('be48895b-e942-bf62-9cde-dd068b7b1c5b', N'CARVING', N'artifact-贈雕000101N000000000', N'骨雕飾件－縮小複製品', N'不同材料有不同個性，好的雕刻懂得順勢而為。以骨雕飾件為靈感製作的縮小複製品，保留一份因材施藝的工藝趣味。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：雕刻' + NCHAR(10) + N'年代：東周至漢' + NCHAR(10) + N'商品尺寸：長 7.6-4.1 公分、寬 0.5 公分、厚 0.2 公分' + NCHAR(10) + N'原作尺寸：長 7.6-8.2 公分、寬 1.0 公分、厚 0.4 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'骨雕飾件 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'以骨磨製成長條形，兩端及中央部位各鑿一小孔，以供繫掛，但器形並不規整，邊稜不平直，製作樸拙。為銅鏽染成綠色。與故雕98-100同儲於一錦盒中。此類器形之器曾見與牙骨管珠串連成串飾，也件此類長條形器，然無穿孔，乃博箸。此件牙器並無紋飾，但是鑽孔技術已相當成熟，可能是東周或漢代之物。', 1350.00, 20, N'/media/catalog/carving/贈雕000101N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/45327?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1320000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'長 7.6-4.1 公分、寬 0.5 公分、厚 0.2 公分', 'adf62237-2d6e-cfb4-0d0b-bb46ca747b38'),
    ('390322fe-97d0-39d3-da87-dd39889318ca', N'COIN', N'artifact-購錢004738N000000000', N'元祐通寶－縮小複製品', N'一枚錢幣，連起的是制度與日常生活。這件「元祐通寶」縮小複製品，把龐大的時代故事收進容易細看的尺寸。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：錢幣' + NCHAR(10) + N'年代：北宋' + NCHAR(10) + N'商品尺寸：待測量' + NCHAR(10) + N'原作尺寸：待測量' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'元祐通寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'銅質。方孔圓錢，正面有楷書：「元祐通寶」四字，背面無文。', 780.00, 20, N'/media/catalog/coin/購錢004738N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/14076?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1330000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'待測量', '5a607292-3c13-bd35-2729-58a8abd66020'),
    ('00386df9-28b0-c6e3-7549-de4f1cd78ae7', N'PAINTING', N'artifact-故畫00025500000', N'元郭畀寫高使君意　軸－縮小複製品', N'畫面不只記錄所見，也保存創作者觀看世界的方式。這件「元郭畀寫高使君意　軸」縮小複製品，邀你把這份想像帶進自己的空間。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：繪畫' + NCHAR(10) + N'年代：元順帝至元五年（1339）' + NCHAR(10) + N'商品尺寸：40.75 × 15.3 公分' + NCHAR(10) + N'原作尺寸：81.5 × 30.6 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'元郭畀寫高使君意　軸 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'郭畀（一二八○—一三三五）字天鍚，號雲山，江蘇丹徒人，官至江浙行省辟充掾史。工書畫，書法出入趙孟頫，山水師法米芾，又善竹木窠石。' + NCHAR(13) + NCHAR(10) + NCHAR(13) + NCHAR(10) + N'此圖寫溪畔坡石高松，遠山寺宇，雲烟繚繞。山石用淡墨大筆渲染，加濃墨橫點提醒，雲烟鈎繪輪廓，這些都是從米家雲山變化來的。紀年己卯為至元五年（一三三九），時郭畀已歿，故應為後人的仿作。', 750.00, 20, N'/media/catalog/painting/故畫00025500000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/694?dep=P', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'40.75 × 15.3 公分', '625ebb2b-f11b-f9cb-7e58-1b1ab97f3561'),
    ('63af98a0-9549-e3ed-0185-deb53ba913c6', N'COIN', N'artifact-購錢004790N000000000', N'熙寧元寶－縮小複製品', N'看錢幣，不只看名稱，也看文字、形制與時代背景。這件「熙寧元寶」縮小複製品，適合作為一段歷史收藏的起點。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：錢幣' + NCHAR(10) + N'年代：北宋' + NCHAR(10) + N'商品尺寸：待測量' + NCHAR(10) + N'原作尺寸：待測量' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'熙寧元寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'銅質。方孔圓錢，正面有楷書：「熙寧元寶」四字，背面無文。', 700.00, 20, N'/media/catalog/coin/購錢004790N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/14128?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1340000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'待測量', 'cf66c67c-b293-1c0f-bd6c-3f68f6c8744d'),
    ('c347c704-ae0c-50af-2f62-df47ae92eef2', N'PAINTING', N'artifact-故畫00097100000', N'元王振鵬寶津競渡圖　卷－縮小複製品', N'遠看整體氣勢，近看筆墨細節，書畫能陪人反覆觀看。這件「元王振鵬寶津競渡圖　卷」縮小複製品，為牆面或展示角落留下一段雅致風景。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：繪畫' + NCHAR(10) + N'年代：元武宗至大三年（1310）' + NCHAR(10) + N'商品尺寸：18.3 × 91.7 公分' + NCHAR(10) + N'原作尺寸：36.6 × 183.4 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'元王振鵬寶津競渡圖　卷 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'王振鵬（約活動於西元一二八○—一三二九年），永嘉人（浙江溫州）。字明梅，受知仁宗，賜號孤雲處士。界畫極工緻，毫分縷析，左右高下，俯仰曲折，方圓平直，曲盡其體，而神氣飛動。' + NCHAR(13) + NCHAR(10) + NCHAR(13) + NCHAR(10) + N'本院藏王振鵬界畫手卷共三幅，而構圖略同，皆畫宋代習俗，農曆三月三日開放金明池，龍舟競渡，百戲雜陳。', 770.00, 20, N'/media/catalog/painting/故畫00097100000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/1107?dep=P', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'18.3 × 91.7 公分', 'e356e911-0767-8e63-e800-9213a9a2d218'),
    ('2ce522ef-5c08-a45e-4458-e0493034f906', N'CERAMIC', N'artifact-贈瓷000452N000000000', N'陶編鐘－縮小複製品', N'泥土經過塑形與窯火，才成為能被長久欣賞的器物。這件「陶編鐘」縮小複製品，把陶瓷溫雅耐看的氣質帶到眼前。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：陶瓷' + NCHAR(10) + N'年代：春秋' + NCHAR(10) + N'商品尺寸：待測量' + NCHAR(10) + N'原作尺寸：待測量' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'陶編鐘 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'陶鐘，器型仿青銅器編鐘，方鈕，鐘身有二十四枚，上下緣塗白陶衣。', 1400.00, 20, N'/media/catalog/ceramic/贈瓷000452N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/43482?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1330000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'待測量', '9542c08c-c71a-e799-b2cc-6b5f1affd48e'),
    ('bfc75b54-bbf9-d0a3-44da-e20fa909182d', N'ENAMEL', N'artifact-故琺000912N000000000', N'銅胎畫琺瑯西洋人物圖鼻煙壺－縮小複製品', N'琺瑯以釉料與燒製換來鮮明而細緻的層次。這件「銅胎畫琺瑯西洋人物圖鼻煙壺」縮小複製品，把這份講究工序的華美濃縮成展示亮點。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：琺瑯器' + NCHAR(10) + N'年代：清 乾隆' + NCHAR(10) + N'商品尺寸：高 2.45 公分、寬 1.85 公分、連座高 3.5 公分、木座長 1.6 公分、寬 1.1 公分、高 0.55 公分' + NCHAR(10) + N'原作尺寸：高 4.9 公分、寬 3.7 公分、連座高 7.0 公分、木座長 3.2 公分、寬 2.2 公分、高 1.1 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'銅胎畫琺瑯西洋人物圖鼻煙壺 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'瓶頸裝飾卷草及如意紋，瓶身彩繪通景西洋人物風景，設色柔和，底有楷書「乾隆年製」藍料款。帶雕花銅蓋與牙匙。', 770.00, 20, N'/media/catalog/enamel/故琺000912N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/61878?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1340000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 2.45 公分、寬 1.85 公分、連座高 3.5 公分、木座長 1.6 公分、寬 1.1 公分、高 0.55 公分', 'ddd42d23-bb8f-cdfa-bace-c1c237928c76'),
    ('8d2675e7-3173-2d82-610f-e2fd9bdf34a5', N'LACQUER', N'artifact-故漆000272N000000000', N'剔黃山海龍鳳花卉紋圓盤－縮小複製品', N'漆器耐看的地方，在於表面質感與製作時間共同留下的韻味。以剔黃山海龍鳳花卉紋圓盤為靈感製作的縮小複製品，適合在近處慢慢欣賞。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：漆器' + NCHAR(10) + N'年代：明 嘉靖' + NCHAR(10) + N'商品尺寸：高 1.4 公分、徑 10.55 公分、足徑 8.55 公分' + NCHAR(10) + N'原作尺寸：高 2.8 公分、徑 21.1 公分、足徑 17.1 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'剔黃山海龍鳳花卉紋圓盤 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'圓盤，圓沿，圈足，足內髹紅漆，盤內外均為紅地剔黃。底款嘉靖壬午年為嘉靖元年，西元1522年。盤底盤沿飾連枝花卉紋，花卉四種輪替，花形簡化，枝末花朵盛開，同時起另一枝。正面盤沿四開光，開光內連枝花卉，花葉左右對稱安排穩定平均。開光外，鋪錦地，各飾八寶其中的四寶。盤心紅漆錦地上飾龍鳳紋。下段波浪紋錦地，沿邊海水翻湧，一座山峰矗立，浪花飛揚。盤心中央及上段，紅漆米字形方格錦地，一龍騰空躍起，一鳳從天而降，隔火球，相互對望。龍身瘦長彎轉，瞪眼張口吐舌，四足外張，龍鰭飛揚，形貌強悍威嚴。鳳鳥頸細尾寬，張翼昂首，飄然輝煌。龍鳳外，連枝花卉上下纏繞，四種花卉自右側進入盤面，牡丹正位於畫面正上方，兩兩相應，構圖緊湊，佈局靈活均衡，頗具生氣。漆層薄，漆色潤，刀法熟練俐落，陰刻線條拙重，黃、紅相映，莊嚴中不失富麗，是官方雕漆的典型。', 900.00, 20, N'/media/catalog/lacquer/故漆000272N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/18011?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 1.4 公分、徑 10.55 公分、足徑 8.55 公分', '0355891e-623c-b96b-f6ea-ec0286dac181'),
    ('a7ee95d3-a2ae-1710-9677-e3b8d85be029', N'CARVING', N'artifact-贈雕000098N000000000', N'骨雕飾件－縮小複製品', N'從一塊材料到一件作品，中間藏著工匠無數次判斷。這件「骨雕飾件」縮小複製品，把這份手藝凝聚成耐看的收藏。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：雕刻' + NCHAR(10) + N'年代：東周至漢' + NCHAR(10) + N'商品尺寸：長 7.6-4.1 公分、寬 0.5 公分、厚 0.2 公分' + NCHAR(10) + N'原作尺寸：長 7.6-8.2 公分、寬 1.0 公分、厚 0.4 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'骨雕飾件 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'以骨磨製成長條形，兩端各鑿一小孔，以供繫掛，但器形並不規整，邊稜不平直，製作樸拙。為銅鏽染成綠色，一面刻有金文或甲骨文之「大祖亥錫作戊父」字樣。與故雕99-101同儲於一六角紋錦盒中，盒蓋尚有秦孝儀前院長題銘「商 骨牘槧 有字曰牘，無字曰槧，此三槧一牘：有文曰 大祖亥錫作戊父 乙亥(民國八十四年，1995)符之 心波記。」並鈐有朱色篆體陽文「秦孝儀」印。此類器形之器曾見與牙骨管珠串連成串飾，也件此類長條形器，然無穿孔，乃博箸。此件牙器並無紋飾，但是鑽孔技術已相當成熟，可能是東周或漢代之物。一面有陰刻仿古金文，或為後人仿刻。', 1410.00, 20, N'/media/catalog/carving/贈雕000098N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/45324?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1320000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'長 7.6-4.1 公分、寬 0.5 公分、厚 0.2 公分', 'a68f9057-4193-5de0-aa32-c9a369b83c29'),
    ('b6aaceeb-ff56-c37c-4afc-e5d420f1d32a', N'BRONZE', N'artifact-中銅000656N000000000', N'蟠虺紋豆－縮小複製品', N'青銅器迷人的地方，在於器物本身與漫長年代共同形成的質感。以蟠虺紋豆為靈感製作的縮小複製品，值得從不同角度細看。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：銅器' + NCHAR(10) + N'年代：戰國' + NCHAR(10) + N'商品尺寸：高 10 公分' + NCHAR(10) + N'原作尺寸：高 20.0 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'蟠虺紋豆 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'蓋與器身組合成球狀器腹，兩環耳，高柄足底部外撇。帶撇圈足圓頂蓋。蓋面和器腹皆飾帶狀蟠虺紋。', 1320.00, 20, N'/media/catalog/bronze/中銅000656N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/53453?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1300000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 10 公分', 'bf28c049-89d8-eca2-1028-6aa5c7ba587e'),
    ('a17489f5-85a4-d14f-7eaf-ea34ac798be6', N'ENAMEL', N'artifact-中琺000412N000000000', N'掐絲琺瑯夔龍碗－縮小複製品', N'色彩是琺瑯最直接的吸引力，工序與細節則值得再三欣賞。以掐絲琺瑯夔龍碗為靈感製作的縮小複製品，讓空間多一抹典藏氣息。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：琺瑯器' + NCHAR(10) + N'年代：清 乾隆' + NCHAR(10) + N'商品尺寸：高 1.95 公分、口徑 4.05 公分' + NCHAR(10) + N'原作尺寸：高 3.9 公分、口徑 8.1 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'掐絲琺瑯夔龍碗 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'銅胎，口略侈，垂腹，圈足小碗。碗內鍍金，器外淺藍地飾回首夔龍四，腹下方飾一圈仰蓮瓣。器底陰刻「大清乾隆年製」雙方框楷書款。一式十個碗裝成一屜，屜中每格有榫頭鎖住。', 960.00, 20, N'/media/catalog/enamel/中琺000412N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/71712?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1340000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 1.95 公分、口徑 4.05 公分', '9655ec27-9f03-4693-e629-9e5c823a65ef'),
    ('bfe97346-97b7-9348-dc1a-eb8b1f3e9d4e', N'COIN', N'artifact-購錢004766N000000000', N'政和通寶－縮小複製品', N'錢幣曾在人群之間流轉，如今也成為辨認時代的重要線索。以政和通寶為靈感製作的縮小複製品，小巧卻很有故事。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：錢幣' + NCHAR(10) + N'年代：北宋' + NCHAR(10) + N'商品尺寸：待測量' + NCHAR(10) + N'原作尺寸：待測量' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'政和通寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'銅質。方孔圓錢，正面有篆書：「政和通寶」四字，背面無文。', 780.00, 20, N'/media/catalog/coin/購錢004766N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/14104?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1330000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'待測量', 'c038c991-4476-7dc0-bdc2-d60290d75f1c'),
    ('357025b3-edff-3963-e8a3-ecd482801d42', N'ENAMEL', N'artifact-故琺000939N000000000', N'銅胎畫琺瑯四季花卉包袱紋瓶－縮小複製品', N'想讓展示空間更有亮點，又保留古典工藝的細膩感，這件「銅胎畫琺瑯四季花卉包袱紋瓶」縮小複製品會是一件很有存在感的收藏。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：琺瑯器' + NCHAR(10) + N'年代：清 嘉慶' + NCHAR(10) + N'商品尺寸：高 4.9 公分、口徑 1.2 公分、腹徑 2.6 公分' + NCHAR(10) + N'原作尺寸：高 9.8 公分、口徑 2.4 公分、腹徑 5.2 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'銅胎畫琺瑯四季花卉包袱紋瓶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'院藏嘉慶銅胎畫琺瑯僅二件，此為其一。短頸斜肩小瓶，全器淺藍色地，以墨色鉤邊彩繪，銅鍍金口沿，頸飾花葉紋，其下為蕉葉紋，器身有繪纏枝花卉，腹下緣有蕉葉紋，圈足飾回紋；瓶身為紫粉色八角錦地紋錦袱包覆，有藍色纏枝花邊與綠色團花紋內裡；底施白釉，有雙方框「嘉慶年製」楷書紅款。據其款式，應為廣琺瑯，配色清麗，畫工細緻，雖有部分釉色不均，但仍為罕見嘉慶畫琺瑯之精品。', 920.00, 20, N'/media/catalog/enamel/故琺000939N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/61900?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1340000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 4.9 公分、口徑 1.2 公分、腹徑 2.6 公分', '5cf93ce6-1f50-28a7-1a89-36e120552441'),
    ('e79f25f2-af66-844d-39bf-ee07c5fd6fb7', N'JADE', N'artifact-故玉004353N000000000', N'玉杯－縮小複製品', N'玉石經過琢磨才成器，也在流傳中留下不同時代的眼光。玉杯化為縮小複製品，讓這份溫潤含蓄的玉器之美走進日常。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：玉器' + NCHAR(10) + N'年代：西漢' + NCHAR(10) + N'商品尺寸：高 2 公分、口徑 2.15 公分、底徑 1.9 公分；木座長 2.3 公分、寬 2.45 公分、高 0.9 公分、連座高 2.75 公分' + NCHAR(10) + N'原作尺寸：高 4.0 公分、口徑 4.3 公分、底徑 3.8 公分；木座長 4.6 公分、寬 4.9 公分、高 1.8 公分、連座高 5.5 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'玉杯 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'本器為杯，玉質，敞口束腰，束腰處拋光細緻，潤澤光亮，器表滿布褐色沁染。口沿外側後刻弦紋一圈。由現今造形可知，應是截取漢代玉杯改製而成，仍可見明確的漢代玉杯圈足。此類漢代玉杯在徐州楚王墓、廣州南越王墓皆有出土。本器改製後，杯內重新打磨拋光，因而未見沁色，推測改作時間應早於清代。本器附木座，存放在院藏「紫檀雕蟠龍方盒百什件」（故雜877）中。', 1480.00, 20, N'/media/catalog/jade/故玉004353N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/71721?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 2 公分、口徑 2.15 公分、底徑 1.9 公分；木座長 2.3 公分、寬 2.45 公分、高 0.9 公分、連座高 2.75 公分', 'b90a052f-7198-7e97-e480-ab88b22dcd5c'),
    ('eddc136d-1e7d-e87a-3e54-ee71b77e24f9', N'PAINTING', N'artifact-購畫00001800000', N'清居廉花果　軸－縮小複製品', N'從構圖、線條到題材安排，書畫總有值得慢慢閱讀之處。以清居廉花果　軸為靈感製作的縮小複製品，讓欣賞不必受距離限制。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：繪畫' + NCHAR(10) + N'年代：清德宗光緒二十四年（1898）' + NCHAR(10) + N'商品尺寸：38.25 × 20 公分' + NCHAR(10) + N'原作尺寸：76.5 × 40 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'清居廉花果　軸 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'居廉（西元一八二八–一九０四年），廣東番禺人。字士剛，號古泉，別號隔山老人、羅浮散人。居廉幼年即失怙恃，從兄居巢憐其才，曾授與花卉寫生之法，後又兼取惲壽平、宋光寶、孟覲乙等人的沒骨技法，成就一派新穎之寫生風格。時人遂以「居派」名之，或稱「隔山派」。　　本幅繪瓶花、水仙，除前景配置紅柿、蘋果、柑橘外，餘均和院藏另幅「花卉」無貳，兩畫相較尤能顯現居氏一貫之構圖理念。', 560.00, 20, N'/media/catalog/painting/購畫00001800000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/32815?dep=P', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1360000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'38.25 × 20 公分', '9ac327ee-40a1-522a-b76b-6441af2801e1'),
    ('c535645b-3a48-2181-36ae-ee9894da985c', N'LACQUER', N'artifact-故漆000439N000000000', N'剔紅雲龍紋小櫃多寶格－縮小複製品', N'一道漆、一段等待，漆器的深度來自層層累積的工序。這件「剔紅雲龍紋小櫃多寶格」縮小複製品，把這份沉靜而講究的工藝氣質帶進日常。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：漆器' + NCHAR(10) + N'年代：明 嘉靖' + NCHAR(10) + N'商品尺寸：長 24.2 公分、寬 17.05 公分、高 20.6 公分' + NCHAR(10) + N'原作尺寸：長 48.4 公分、寬 34.1 公分、高 41.2 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'剔紅雲龍紋小櫃多寶格 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'清宮利用明代嘉靖朝的漆櫃作為多寶格，櫃體分為四層，每一層分別有一、二、三、四個抽屜，屜內清宮另製木屜格層，存放的文物以清代製品為主。內容包含清墨12 件、明清小玉器41件、書法小冊3件、清代瓷器6件、西洋鐘錶琺瑯7件、清代小畫卷及畫冊8件、明清漆盒6件、銅器3件以及玻璃、蜜蠟、檀香等的文具，如印石、水盛、紙鎮等22件，包含嘉靖剔紅雲龍紋小櫃總共109件。', 870.00, 20, N'/media/catalog/lacquer/故漆000439N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/62081?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'長 24.2 公分、寬 17.05 公分、高 20.6 公分', '246b42e5-b1a7-7f25-6abd-d836006a151b'),
    ('cacaba3f-e3b0-a7de-2aff-f0e60c600a51', N'JADE', N'artifact-故玉009115N000000000', N'〈般若波羅蜜多心經〉玉版－縮小複製品', N'從光澤、質地到琢磨留下的細節，玉器總有值得反覆欣賞之處。〈般若波羅蜜多心經〉玉版縮小複製品，邀你用更親近的距離重新認識它。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：玉器' + NCHAR(10) + N'年代：清 乾隆' + NCHAR(10) + N'商品尺寸：長 2.9 公分、寬 2.25 公分' + NCHAR(10) + N'原作尺寸：長 5.8 公分、寬 4.5 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'〈般若波羅蜜多心經〉玉版 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'長方形玉版，一式四件（故玉9113-9116），上刻錢汝誠（1722-1779）所書〈般若波羅蜜多心經〉填金楷字。本器為玉版中的第三片，續刻「般若波羅蜜多心經」之中段經文。', 890.00, 20, N'/media/catalog/jade/故玉009115N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/60157?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1340000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'長 2.9 公分、寬 2.25 公分', '99c5a07f-e1ae-c5ff-0d9f-af4159ed9918'),
    ('baa82697-4ff1-8efd-f77b-f16783ebcc9c', N'CARVING', N'artifact-贈雕000187N000000000', N'牙梳－縮小複製品', N'不同材料有不同個性，好的雕刻懂得順勢而為。以牙梳為靈感製作的縮小複製品，保留一份因材施藝的工藝趣味。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：雕刻' + NCHAR(10) + N'年代：宋至元' + NCHAR(10) + N'商品尺寸：長 4.55 公分、寬 2.6 公分、背厚 0.35 公分' + NCHAR(10) + N'原作尺寸：長 9.1 公分、寬 5.2 公分、背厚 0.7 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'牙梳 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'全器由五塊牙材製成，合併之即呈半月形，中央三塊兩側各有二小孔，最外面兩塊內側也有二孔，可藉插榫相接成一器。器之背寬大致相同，兩端平直，梳齒長度由中央向兩側依序遞減，齒與背之間陰刻二道弦紋間隔。器表有蝕痕，梳齒亦有殘損', 950.00, 20, N'/media/catalog/carving/贈雕000187N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/45415?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1310000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'長 4.55 公分、寬 2.6 公分、背厚 0.35 公分', '78d04087-f411-a879-04b2-3d47c056c8ef'),
    ('97dfde84-c70a-2904-8a07-f19534b3f189', N'ENAMEL', N'artifact-故琺000836N000000000', N'掐絲琺瑯梵文碟－縮小複製品', N'想讓展示空間更有亮點，又保留古典工藝的細膩感，這件「掐絲琺瑯梵文碟」縮小複製品會是一件很有存在感的收藏。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：琺瑯器' + NCHAR(10) + N'年代：清 乾隆' + NCHAR(10) + N'商品尺寸：口徑 7.55 公分' + NCHAR(10) + N'原作尺寸：口徑 15.1 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'掐絲琺瑯梵文碟 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'侈口，折沿，淺壁，平底，圈足。全器淺藍地，口沿寫有一圈梵文，內底有卷鬚錦，中心有一由七個梵文及三個符號組成的「十相自在」吉祥紋飾，盤內外壁為朵雲紋間飾佛教七珍、八寶。底部有陰刻「乾隆年製」四字雙行楷書雙方框款。', 940.00, 20, N'/media/catalog/enamel/故琺000836N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/61822?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1340000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'口徑 7.55 公分', 'd3b13677-1289-caf4-6245-3aa5ac72c627'),
    ('45f6822d-3537-988c-1329-f310f9b8dcac', N'LACQUER', N'artifact-故漆000383N000000000', N'剔紅雙獅圖圓盒－縮小複製品', N'漆藝講究耐心，也讓器物擁有難以取代的深沉質感。這件「剔紅雙獅圖圓盒」縮小複製品，是一件越看越能發現味道的收藏。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：漆器' + NCHAR(10) + N'年代：明 永樂' + NCHAR(10) + N'商品尺寸：高 2.2 公分、徑 5.3 公分' + NCHAR(10) + N'原作尺寸：高 4.4 公分、徑 10.6 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'剔紅雙獅圖圓盒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'盒作扁圓形，子母口，圈足，盒內及底部髹褐漆，漆色紅褐帶透明感。盒面雕雙獅戲球，兩獅側身躍動，回首面向圓心，露齒銜帶，獅面深目捲髮，肌肉緊拉。盒心為錦地綵球，四周綵帶翻折，三條長帶曲折延長，環繞於四周的雲紋之上，雲紋以四、五朵相連成組，自盒下緣向兩側延伸，流動綿長。盒底外緣刻雲紋，共十組，斜向流轉環繞，自然靈活。盒面佈局多處露出黃地，物象雖多，井然有序。漆色紅潤，漆層堅實，刀法深峻，雲紋、獅身肌肉等處並用減地與陰刻線，毛髮以更淺的刻線表達，雕工講究。', 820.00, 20, N'/media/catalog/lacquer/故漆000383N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/17725?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 2.2 公分、徑 5.3 公分', 'ad397695-963b-f128-72e8-a98037372c7a'),
    ('127fa860-eacf-e8e3-9a51-f33387783b23', N'ENAMEL', N'artifact-故琺000899N000000000', N'銅胎畫琺瑯西洋人物圖鼻煙壺－縮小複製品', N'琺瑯以釉料與燒製換來鮮明而細緻的層次。這件「銅胎畫琺瑯西洋人物圖鼻煙壺」縮小複製品，把這份講究工序的華美濃縮成展示亮點。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：琺瑯器' + NCHAR(10) + N'年代：清 乾隆' + NCHAR(10) + N'商品尺寸：寬 1.95 公分、高 2.5 公分' + NCHAR(10) + N'原作尺寸：寬 3.9 公分、高 5.0 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'銅胎畫琺瑯西洋人物圖鼻煙壺 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'扁壺綠地彩繪纏枝卷草花果紋，雙面開光內繪戲鳥西洋人物，底有楷書「乾隆年製」黑款，有粉色雕花料蓋與牙匙。應為廣琺瑯。', 800.00, 20, N'/media/catalog/enamel/故琺000899N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/61870?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1340000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'寬 1.95 公分、高 2.5 公分', 'e43a397e-9704-5244-b8ed-fd4c1a62ccba'),
    ('1e2b97e2-0373-0434-18bd-f36f5de20208', N'CERAMIC', N'artifact-故瓷018224N000000000', N'汝窯 青瓷碟「丙蔡」銘－縮小複製品', N'從日常器用到典藏珍品，陶瓷記錄了不同時代對生活之美的想像。這件「汝窯 青瓷碟「丙蔡」銘」縮小複製品，讓這段美感自然融入展示空間。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：陶瓷' + NCHAR(10) + N'年代：北宋' + NCHAR(10) + N'商品尺寸：高 0.75 公分、深 0.6 公分、口徑 5.45 公分、底徑 4.1 公分' + NCHAR(10) + N'原作尺寸：高 1.5 公分、深 1.2 公分、口徑 10.9 公分、底徑 8.2 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'汝窯 青瓷碟「丙蔡」銘 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'圓口，淺壁，平底無足。胎質較薄，滿釉支燒，通體施青釉，釉色粉青微泛綠。底面三枚支燒點沿邊排佈，正背兩面滿佈開片，中心後刻「蔡」、「丙」兩字。與之相似的器形，亦見於河南省寶豐縣清涼寺窯址出土的標本。', 830.00, 20, N'/media/catalog/ceramic/故瓷018224N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/61102?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1320000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 0.75 公分、深 0.6 公分、口徑 5.45 公分、底徑 4.1 公分', 'acaf0758-d52c-6957-4c83-f64cfaff540e'),
    ('74de5e1e-cc70-c710-0db6-f46c683e84c8', N'COIN', N'artifact-購錢004680N000000000', N'熙寧元寶－縮小複製品', N'一枚錢幣，連起的是制度與日常生活。這件「熙寧元寶」縮小複製品，把龐大的時代故事收進容易細看的尺寸。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：錢幣' + NCHAR(10) + N'年代：北宋' + NCHAR(10) + N'商品尺寸：待測量' + NCHAR(10) + N'原作尺寸：待測量' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'熙寧元寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'銅質。方孔圓錢，正面有楷書：「熙寧元寶」四字，背面無文。', 620.00, 20, N'/media/catalog/coin/購錢004680N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/14018?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1340000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'待測量', '48f0adc5-1bc7-a30c-32ed-06c117e3f553'),
    ('f9850514-e97c-51b2-5641-f522a0eb7262', N'COIN', N'artifact-購錢005259N000000000', N'景德元寶－縮小複製品', N'一枚錢幣，連起的是制度與日常生活。這件「景德元寶」縮小複製品，把龐大的時代故事收進容易細看的尺寸。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：錢幣' + NCHAR(10) + N'年代：北宋' + NCHAR(10) + N'商品尺寸：待測量' + NCHAR(10) + N'原作尺寸：待測量' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'景德元寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'銅質。方孔圓錢，正面有楷書：「景德元寶」四字，背面無文。', 680.00, 20, N'/media/catalog/coin/購錢005259N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/14597?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1340000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'待測量', 'b038225f-b66f-f247-e505-a8c79276792a'),
    ('3366b28c-8dd9-833a-7fbf-f69698ce8aff', N'PAINTING', N'artifact-故畫00147300000', N'宋馬遠畫水二十景　卷－縮小複製品', N'遠看整體氣勢，近看筆墨細節，書畫能陪人反覆觀看。這件「宋馬遠畫水二十景　卷」縮小複製品，為牆面或展示角落留下一段雅致風景。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：繪畫' + NCHAR(10) + N'年代：紹興十一年（1141）' + NCHAR(10) + N'商品尺寸：12.9 × 400.5 公分' + NCHAR(10) + N'原作尺寸：25.8 × 801 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'宋馬遠畫水二十景　卷 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'純以流水為主題的作品，歷來並不多見。本幅以工細之筆，一絲不茍地畫水二十景，每段各有標題，包含著著名地區和事蹟中的水景，以及水之各類型態。有浪花翻騰的壯闊之美，也有水波輕漾的柔和之美，甚為多采多姿。舊傳為馬遠之作，但欠其靈活生動之意。馬遠，字欽山，宋光、寧宗朝(西元1190-1224年)畫院待詔。畫山水、人物、花卉、禽鳥，雖得家傳，然能自樹一幟。', 820.00, 20, N'/media/catalog/painting/故畫00147300000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/90?dep=P', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'12.9 × 400.5 公分', '51baa8ed-e77a-275c-eaf9-6584e0900c0e'),
    ('13e8c925-73d4-d7ae-8b2f-f7d13bb97b9b', N'CARVING', N'artifact-贈雕000100N000000000', N'骨雕飾件－縮小複製品', N'雕刻值得從多個角度觀看，輪廓、轉折與細部會逐一展開。這件「骨雕飾件」縮小複製品，適合擺在能讓人停下腳步的位置。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：雕刻' + NCHAR(10) + N'年代：東周至漢' + NCHAR(10) + N'商品尺寸：長 7.6-4.1 公分、寬 0.5 公分、厚 0.2 公分' + NCHAR(10) + N'原作尺寸：長 7.6-8.2 公分、寬 1.0 公分、厚 0.4 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'骨雕飾件 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'以骨磨製成長條形，兩端各鑿一小孔，以供繫掛，但器形並不規整，邊稜不平直，製作樸拙。為銅鏽染成綠色。與故雕98-99、101同儲於一錦盒中。此類器形之器曾見與牙骨管珠串連成串飾，也件此類長條形器，然無穿孔，乃博箸。此件牙器並無紋飾，但是鑽孔技術已相當成熟，可能是東周或漢代之物。', 1310.00, 20, N'/media/catalog/carving/贈雕000100N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/45326?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1320000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'長 7.6-4.1 公分、寬 0.5 公分、厚 0.2 公分', '4d7f6c38-1865-ac21-fd8e-77949b898314'),
    ('c8c037cf-6c06-c250-0a29-f81e90929096', N'CERAMIC', N'artifact-故瓷018172N000000000', N'青瓷盞－縮小複製品', N'從日常器用到典藏珍品，陶瓷記錄了不同時代對生活之美的想像。這件「青瓷盞」縮小複製品，讓這段美感自然融入展示空間。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：陶瓷' + NCHAR(10) + N'年代：南宋' + NCHAR(10) + N'商品尺寸：高 2.65 公分、口徑 6.6 公分、足徑 2.45 公分' + NCHAR(10) + N'原作尺寸：高 5.3 公分、口徑 13.2 公分、足徑 4.9 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'青瓷盞 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'八瓣花口形碗，弧形深壁，矮圈足，無底，加鑲一層金屬底足。器內形塑出一個凸起的蓮房，中心開通，下設六孔，頂端加鑲一個花形金屬釦，周旁貼飾浮萍與茨菇葉各兩枚。胎體較薄，內外施青釉，釉色微泛灰。口下有多層施釉痕，口沿釉薄處露出深灰色邊及胎色。釉面出現稀疏開片紋。 浙江省杭州市老虎洞窯址也曾出土同樣使用模製成形技法完成的多瓣花口碗。由於造型奇特，而不免令人對它的用途感到好奇，近來學者透過德國柏林亞洲藝術博物館收藏的一件白瓷盞，藉由碗內相似的結構，推測此件作品的中央部位，原來應配製有模製小人物。注水入碗後，水浮力的推波助瀾，讓碗內小人物得以緩緩升起，形塑出對飲的趣味。堪稱是深受北宋以來科學氛圍影響下，利用虹吸原理完成的特殊酒具。', 880.00, 20, N'/media/catalog/ceramic/故瓷018172N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/61057?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1330000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 2.65 公分、口徑 6.6 公分、足徑 2.45 公分', '425cb341-905e-47fc-73e8-9f0cbdb2f0cf'),
    ('26f7ca29-9282-d138-7384-f9deb7805052', N'BRONZE', N'artifact-故銅002460N000000000', N'銅雙耳方鼎－縮小複製品', N'青銅器迷人的地方，在於器物本身與漫長年代共同形成的質感。以銅雙耳方鼎為靈感製作的縮小複製品，值得從不同角度細看。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：銅器' + NCHAR(10) + N'年代：清 乾隆' + NCHAR(10) + N'商品尺寸：銅鼎腹長 3.55 公分、寬 2.75 公分、連座通高 6.25 公分' + NCHAR(10) + N'原作尺寸：銅鼎腹長 7.1 公分、寬 5.5 公分、連座通高 12.5 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'銅雙耳方鼎 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'此器收儲於「紫檀嵌彩瓷博古圖小櫃」。' + NCHAR(13) + NCHAR(10) + N'方鼎，立耳，折沿，深腹，器身帶扉棱，扁足。全器局部施以金彩。器外底銘「大清乾隆年製」楷書六字。附玉頂木蓋及木座。', 830.00, 20, N'/media/catalog/bronze/故銅002460N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/62168?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1310000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'銅鼎腹長 3.55 公分、寬 2.75 公分、連座通高 6.25 公分', 'fc31545d-ae53-4c67-5bb9-c5a17fc890dc'),
    ('bf79e588-aebb-f93b-ae5b-fae5c8bf9202', N'LACQUER', N'artifact-故漆000556N000000000', N'剔彩龍鳳八寶蓋盒－縮小複製品', N'漆藝講究耐心，也讓器物擁有難以取代的深沉質感。這件「剔彩龍鳳八寶蓋盒」縮小複製品，是一件越看越能發現味道的收藏。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：漆器' + NCHAR(10) + N'年代：明 嘉靖' + NCHAR(10) + N'商品尺寸：高 8.95 公分、徑 16.65 公分、足徑 12.05 公分' + NCHAR(10) + N'原作尺寸：高 17.9 公分、徑 33.3 公分、足徑 24.1 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'剔彩龍鳳八寶蓋盒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'穹頂，圈足，盒底及盒內髹黑漆，盒外剔彩，漆層由下而上為黃、紅、綠、黃、綠、紅。盒蓋一圓形分內外，圓內頂著兩交錯的正方形，龍居中央，龍身盤旋，龍首居中，口中吐出一圓球，球內一「壽」字，三角形內、外雕八寶等。圓形外圍為八個鳳鳥小圓，間隔著花卉或八寶。盒側垂直面為行龍奔走於海面上，以山石相隔，或回首或昂首。盒身雕相同的龍紋及花卉鳳紋。全器以紅色為主調，龍以黃色為表現，此外綠色及黃色用以陪襯，底飾錦地，用色鮮艷，雕刻繁複，細節眾多。漆層薄而不堅，漆與胎之間似無織品，附著不牢，刀法純熟，或工整剔去上層，或以斜刀表現漆層色彩的變化，是嘉靖時期的佳作。', 720.00, 20, N'/media/catalog/lacquer/故漆000556N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/17575?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 8.95 公分、徑 16.65 公分、足徑 12.05 公分', '2208da89-0551-e24b-f776-d40ddabb3532'),
    ('048d35bb-e9a4-b689-3b9f-fb7ea36038b6', N'JADE', N'artifact-故玉008399N000000000', N'玉春水飾件－縮小複製品', N'一件玉器，可以寄託品味，也能收藏一段時代記憶。以玉春水飾件為靈感製作的縮小複製品，為展示空間添上一份沉靜氣質。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：玉器' + NCHAR(10) + N'年代：金至元' + NCHAR(10) + N'商品尺寸：長 4.1 公分、寬 1.75 公分、高 1 公分' + NCHAR(10) + N'原作尺寸：長 8.2 公分、寬 3.5 公分、高 2.0 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'玉春水飾件 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'玉質，鏤雕一水禽嬉游於蓮池。以細線陰刻鳥羽及葉脈。禽鳥口中銜食，自在穿梭於蓮葉間，呈現一片生意盎然景象。', 1020.00, 20, N'/media/catalog/jade/故玉008399N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/59444?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'長 4.1 公分、寬 1.75 公分、高 1 公分', '6ff0c8be-a07e-4876-fb35-df73f6d0a65f'),
    ('9f2f5280-e287-8f39-8de3-fd9f2a22a3bc', N'ENAMEL', N'artifact-故琺000880N000000000', N'銅胎畫琺瑯包袱紋蓋罐－縮小複製品', N'色彩是琺瑯最直接的吸引力，工序與細節則值得再三欣賞。以銅胎畫琺瑯包袱紋蓋罐為靈感製作的縮小複製品，讓空間多一抹典藏氣息。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：琺瑯器' + NCHAR(10) + N'年代：清 乾隆' + NCHAR(10) + N'商品尺寸：寬 4 公分、通高 6.1 公分' + NCHAR(10) + N'原作尺寸：寬 8.0 公分、通高 12.2 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'銅胎畫琺瑯包袱紋蓋罐 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'銅胎，圓冠式蓋鍍金球鈕，短頸，斜肩，扁橢圓式斂腹。琺瑯彩，蓋表黃地朵花連枝紋，鈕底飾紅邊白底點紋，外圍再繪一圈藍底白邊如意雲紋。頸藍地圍飾靈芝紋，腹飾各式纏枝花卉，近肩處四開光。於四開光位置處，繪飾著紅面藍邊的包袱巾，裹繞於器腹上；紅袱巾，底飾菊花的龜甲錦地間以蝙蝠，其上再繪飾花、蝶圖樣等，袱巾背面繪青綠色寶相花。器底綠釉，繪製一圈轉枝菊花紋，中間為藍色雙圈交疊，圈內白地書墨色「乾隆年製」款。', 780.00, 20, N'/media/catalog/enamel/故琺000880N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/61859?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1340000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'寬 4 公分、通高 6.1 公分', 'b2be60f0-d4a8-7eee-6bca-d6bf31b34602'),
    ('202535ec-9ade-65f5-0da3-fe6739f36318', N'LACQUER', N'artifact-故漆000468N000000000', N'剔紅花卉長頸瓶－縮小複製品', N'漆藝講究耐心，也讓器物擁有難以取代的深沉質感。這件「剔紅花卉長頸瓶」縮小複製品，是一件越看越能發現味道的收藏。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：漆器' + NCHAR(10) + N'年代：明 永樂' + NCHAR(10) + N'商品尺寸：高 8.35 公分、口徑 3 公分、頸徑 2.3 公分、腹徑 4.6 公分、底徑 4.25 公分' + NCHAR(10) + N'原作尺寸：高 16.7 公分、口徑 6.0 公分、頸徑 4.6 公分、腹徑 9.2 公分、底徑 8.5 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'剔紅花卉長頸瓶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'長頸，盤口，腹部造型削肩後筆直而下，圈足，底髹黑漆，口沿飾回紋，全器滿飾花卉紋。頸部轉枝花卉，枝葉作波浪狀，上下分枝交錯安排四朵全開的花朵，下層牡丹兩朵，上層為茶花及梔子花。頸部及腹部以直線區隔。器腹轉枝花卉上下交錯各三朵，上層為梔子花、菊及茶花，下層為茶花、牡丹、梔子花。枝幹婉轉相連，花形飽滿，枝葉豐厚，與端莊的器形相應，顯得落落大方，氣勢不凡。細視花葉的縫隙間露出黃色素地。漆層甚厚，花瓣得以層疊高低錯落，圓潤可搯；葉片舒展有致，葉脈刻劃挺勁有神，無處不見其設計之嚴謹，與刀法運用之靈活自如，並經仔細打磨，使「藏鋒清楚，隱起圓滑，纖細精緻」，達到剔紅技法的最高境界。不論器形和花卉樣式都是明代雕漆的新風格。', 930.00, 20, N'/media/catalog/lacquer/故漆000468N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/17565?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1350000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'高 8.35 公分、口徑 3 公分、頸徑 2.3 公分、腹徑 4.6 公分、底徑 4.25 公分', '9d51cb6c-3684-81de-050a-ee5f7f4b7fa8'),
    ('c978cded-36bb-9179-2c34-ff00416dc908', N'JADE', N'artifact-故玉009116N000000000', N'〈般若波羅蜜多心經〉玉版－縮小複製品', N'玉石經過琢磨才成器，也在流傳中留下不同時代的眼光。〈般若波羅蜜多心經〉玉版化為縮小複製品，讓這份溫潤含蓄的玉器之美走進日常。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：玉器' + NCHAR(10) + N'年代：清 乾隆' + NCHAR(10) + N'商品尺寸：長 2.9 公分、寬 2.25 公分' + NCHAR(10) + N'原作尺寸：長 5.8 公分、寬 4.5 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'〈般若波羅蜜多心經〉玉版 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'長方形玉版，一式四件（故玉9113-9116），上刻錢汝誠（1722-1779）所書〈般若波羅蜜多心經〉填金楷字。本器為玉版中的第四片，正面刻「般若波羅蜜多心經」之末段經文，以及錢汝誠款識，背面刻卷枝番蓮紋。', 860.00, 20, N'/media/catalog/jade/故玉009116N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/60158?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1340000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'長 2.9 公分、寬 2.25 公分', '424aa2bf-37d5-8069-7828-56bf94a9e253'),
    ('48989907-8387-853e-051e-ffdcdf20e1aa', N'BRONZE', N'artifact-購銅000017N000000000', N'鍑甑－縮小複製品', N'金屬與火塑成器物，歲月再替表面留下時間的痕跡。這件「鍑甑」縮小複製品，把銅器沉穩厚實的存在感帶進收藏空間。' + NCHAR(10) + NCHAR(10) + N'商品資訊：' + NCHAR(10) + N'分類：銅器' + NCHAR(10) + N'年代：西漢早期' + NCHAR(10) + N'商品尺寸：通高 16.4 公分' + NCHAR(10) + N'原作尺寸：通高 32.8 公分' + NCHAR(10) + NCHAR(10) + N'本頁商品為 MSIT173 課程專題的虛擬展示資料，使用國立故宮博物院開放資料圖像建立對應的縮小複製品，僅供系統功能測試與課堂發表，不提供訂購、付款或實際販售。商品尺寸依公開資料換算為原作的一半；來源標示待測量或未提供時不自行推測。' + NCHAR(10) + NCHAR(10) + N'圖像姓名標示：' + NCHAR(10) + N'鍑甑 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw' + NCHAR(10) + NCHAR(10) + N'原文物說明：' + NCHAR(10) + N'此器分別由三個部分組成，最上一器自名為甑，侈口折唇，圓腹內收成小圈足，器底有穿孔或箄，以容蒸氣穿透。中間一器自名為復（鍑）或釜，小口圓腹，腹部有寬沿凸出。最下一器自名為盆，亦是侈口寬沿，與鍑略似而為平底，使用時將盆倒扣於甑上以免蒸氣外洩，這種形制在戰國晚期就已出現。全器雖然自名為「甗」或「甗甑」，但與商、周時代 的甗形器明顯不同，主要是甑下已不再是三足的鬲而是圜底的鍑了，這是因為漢代爐灶普及，可以將鍑直接置於灶上受火，三足的鬲就逐漸退隱了。', 1200.00, 20, N'/media/catalog/bronze/購銅000017N000000000/display.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/71944?dep=U', 1, CONVERT(datetime2(3), '2026-08-09T05:18:41.1310000', 126), CONVERT(datetime2(3), '2026-08-11T13:49:52.7680000', 126), N'通高 16.4 公分', '3ad1a361-d308-49c7-0fb2-05f341b9bb41');
GO
